/* ====================================================================
   PEDRA SECA · MODULS CANONICS
   Fitxa de gestor, estructura del gestor, 404, pindola i panell d'admin.
   ==================================================================== */

@layer components {

/* ═══ FITXA DE GESTOR · LLEI DE PEDRA SECA ═══════════════════════════
   L'única forma d'un element dins la llista de l'UniversalManager.
     · Títol (rol H1) ≤ 2 línies · subtítol (rol H2) ≤ 1 línia · res més.
     · Media quadrada de var(--sdp-fitxa-mida) a l'esquerra.
   Pressupost vertical (arrel de 16px):
     2 × 18 × 1,3 + 16 × 1,3 + 4 = 71,6px de text + 2 × 12 de coixí = 95,6 ≤ 96px.
   Interlineat 1,3 i no --sdp-leading-snug (1,21): amb Noto Sans (àrea de
   contingut 1,362em) el retall de dues línies es menjaria la cua de la «ç».
   El pressupost també el topa per dalt: per damunt de 1,307 ja no hi cap.
   Si l'usuari engrandix la lletra, la fitxa creix: mai retalla.
   Porta: tooling/gates/tractor-fitxa-gestor.mjs (F8).
   ═══════════════════════════════════════════════════════════════════ */

/* Embolcall de pàgina dels consumidors (abans: style={{ height: '100%' }}). */
.sdp-gestor-pagina {
  height: 100%;
}

/* La llista neutralitza la tipografia editorial global de ul/li:
   sagnat de 28px, pic, i 8px de marge entre elements. */
.sdp-gestor-llista {
  list-style: none;
  margin: 0;
  padding: 0;
}

.sdp-gestor-llista > li {
  margin: 0;
  padding: 0;
}



.text-accent {
  color: var(--sdp-accent-text);
}

/* Aliniació i pes (consumidors: GestoriaHome.jsx) */
.sdp-text-dreta { text-align: right; }
.sdp-text-exit { color: var(--sdp-exit-text); font-weight: 700; }


/* Pes visual */
.sdp-text-negreta { font-weight: bold; }

/* Divisor genèric */
.sdp-divisor {
  display: block;
  border: 0;
  border-top: 1px solid var(--sdp-vora);
  margin: var(--sdp-space-4) 0;
  width: 100%;
}

.sdp-gestor-fitxa {
  display: flex;
  align-items: center;
  width: 100%;
  min-height: var(--sdp-fitxa-mida);
  padding: 0;
  border: 0;
  border-left: 3px solid transparent;
  border-bottom: 1px solid var(--sdp-vora);
  border-radius: 0;
  background: var(--sdp-fons-targeta);
  text-align: left;
  cursor: pointer;
  transition: background-color var(--sdp-t);
  position: relative;
}

/* Fase B (261004): el hover només amb ratolí; al tàctil no es queda enganxat. */
@media (hover: hover) and (pointer: fine) {
  .sdp-gestor-fitxa:hover {
    background: var(--sdp-fons-subtil);
  }
}

/* T62 · Actiu de la navegació secundària en blau d'acció (Pedra Seca §2):
   fons --sdp-accio-subtil i marcador --sdp-accio. Contrastos WCAG sobre els
   valors que tokens.css dona a cada tema (ací no hi van hex: Design Guard):
     · marcador --sdp-accio sobre --sdp-accio-subtil: 3,62:1 en clar i
       4,01:1 en fosc, per damunt del 3:1 de WCAG 1.4.11;
     · títol: 18,13:1 en clar i 15,52:1 en fosc;
     · subtítol: 8,49:1 en clar i 10,82:1 en fosc (--sdp-text-suau, 261004).
   Va després de :hover i guanya per ordre. */
.sdp-gestor-fitxa[aria-current="true"] {
  background: var(--sdp-accio-subtil);
  border-left-color: var(--sdp-accio);
}

/* Anell interior: el contenidor amb scroll retallaria l'exterior.
   :focus porta l'anell perquè Safari 15.0–15.3 no coneix :focus-visible;
   on sí que el coneix, el ratolí no l'encén. */
.sdp-gestor-fitxa:focus {
  outline: 3px solid var(--sdp-focus);
  outline-offset: -3px;
}

.sdp-gestor-fitxa:focus:not(:focus-visible) {
  outline-color: transparent;
}

.sdp-gestor-fitxa__media {
  flex: 0 0 var(--sdp-fitxa-mida);
  align-self: flex-start;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--sdp-fitxa-mida);
  height: var(--sdp-fitxa-mida);
  overflow: hidden;
  background: var(--sdp-fons-subtil);
  color: var(--sdp-text-suau);
}

.sdp-gestor-fitxa__imatge {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.sdp-gestor-fitxa__inicial {
  font-size: var(--sdp-text-h3);
  font-weight: 700;
  line-height: 1;
}

.sdp-gestor-fitxa__text {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--sdp-space-1);
  padding: var(--sdp-space-3) var(--sdp-space-4);
}



.sdp-gestor-fitxa__titol {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
  overflow-wrap: break-word;
  font-size: var(--sdp-text-base);
  font-weight: 700;
  line-height: 1.3;
  color: var(--sdp-text-titol);
}



.sdp-gestor-fitxa__subtitol {
  display: block;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: var(--sdp-text-small);
  line-height: 1.3;
  color: var(--sdp-text-suau);
}

@media (prefers-reduced-motion: reduce) {
  .sdp-gestor-fitxa {
    transition: none;
  }
}

/* ── AppGridColumn overrides ── */
.app-grid-col-header__plegable {
  flex: 1 1 auto;
  padding: 0;
  background: transparent;
}
.app-grid-col-header__chevron {
  margin-left: auto;
  display: flex;
  transition: transform var(--sdp-t);
}
.app-grid-col-header__chevron--obert {
  transform: rotate(180deg);
}

/* ═══ ESTRUCTURA I SCROLL DEL GESTOR UNIVERSAL ═══════════════════════ */
.sdp-workspace-column {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  overflow: hidden;
  background: inherit;
}

/* Gradació de color per a la columna esquerra (Pedra Seca) */
aside.sdp-workspace-column > .app-grid-col-header--dark:nth-of-type(1) {
  background: var(--sdp-crom-capcalera-profunda);
}
aside.sdp-workspace-column > .app-grid-col-header--dark:nth-of-type(2) {
  background: var(--sdp-crom-subcapcalera);
}

.sdp-workspace-column__body {
  flex: 1 1 0;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
}


.sdp-workspace-search-row {
  display: flex;
  align-items: center;
  gap: var(--sdp-space-2);
  padding: var(--sdp-space-2) var(--sdp-space-4);
  background: var(--sdp-fons-superficie);
  border-bottom: 1px solid var(--sdp-vora);
}

.sdp-workspace-search {
  flex: 1;
  display: flex;
  align-items: center;
  gap: var(--sdp-space-2);
  padding: var(--sdp-space-2) var(--sdp-space-3);
  background: var(--sdp-fons-subtil);
  border-radius: var(--sdp-radi-s);
  border: 1px solid var(--sdp-vora);
}
.sdp-workspace-search input {
  flex: 1;
  border: none;
  background: transparent;
  font: inherit;
  font-size: var(--sdp-text-small);
  color: var(--sdp-text-cos);
  outline: none;
}
.sdp-workspace-search input:focus-visible { outline: 2px solid var(--sdp-accio-forta); outline-offset: 2px; }

.sdp-workspace-clear {
  border: none;
  background: transparent;
  color: var(--sdp-text-suau);
  font: inherit;
  font-size: var(--sdp-text-small);
  cursor: pointer;
  padding: var(--sdp-space-2);
}
@media (hover: hover) and (pointer: fine) {
  .sdp-workspace-clear:hover {
    color: var(--sdp-error-text);
  }
}

.sdp-workspace-tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sdp-space-2);
  padding: var(--sdp-space-3) var(--sdp-space-4);
  background: var(--sdp-fons-app);
  border-bottom: 1px solid var(--sdp-vora);
}
.sdp-workspace-tag {
  border: 1px solid var(--sdp-vora);
  border-radius: var(--sdp-radi-pastilla);
  background: var(--sdp-fons-targeta);
  padding: var(--sdp-space-1) var(--sdp-space-3);
  font: inherit;
  font-size: var(--sdp-text-meta);
  color: var(--sdp-text-cos);
  cursor: pointer;
}
.sdp-workspace-tag[aria-pressed="true"] {
  background: var(--sdp-accent-subtil);
  border-color: var(--sdp-accent-text);
  color: var(--sdp-text-titol);
  font-weight: bold;
}

.sdp-workspace-state {
  padding: var(--sdp-space-8) var(--sdp-space-4);
  text-align: center;
  color: var(--sdp-text-suau);
}

/* Element de navegació genèric (carpeta, categoria, etiqueta, àrea…).
   Cada secció pot recolorir-lo via la seua classe arrel (p. ex. .sdp-bloc). */
.sdp-workspace-group-heading { padding: var(--sdp-space-3) var(--sdp-space-4) var(--sdp-space-2); }
.sdp-workspace-group-chevron { margin-inline-start: auto; display: flex; transition: transform var(--sdp-t); }
[aria-expanded="true"] > .sdp-workspace-group-chevron { transform: rotate(180deg); }
.sdp-workspace-groups { display: flex; flex-direction: column; min-height: 100%; color: var(--sdp-crom-text); background: var(--sdp-crom-capcalera); }
/* T28 (ordre del Mestre, 260927 nit) · «Estil Excel»: l'arbre de carpetes i
   categories (Notes, Disseny, Wiki) calca la graella del rail del Xat
   desplegat (.sdp-xat-rail-llista): sense coixí de dalt (la primera fila
   s'apega a la capçalera, com la barra principal), i el li sense el sagnat
   de 4px ni el marge que li posa la tipografia editorial d'ul/li (eren els
   4px que desquadraven l'eix de les icones: 292 a Notes contra 288 al Xat). */
.sdp-workspace-categories { padding: 0 0 var(--sdp-space-2); margin: 0; list-style: none; }
.sdp-workspace-categories > li { margin: 0; padding: 0; }
.sdp-workspace-categories .sdp-workspace-categories {
  padding-block: 0;
  padding-inline-end: 0;
  margin-inline-start: var(--sdp-space-4);
  border-inline-start: 1px solid var(--sdp-crom-hover);
}
/* T33 (ordre del Mestre, 260927 nit) · stretch: cada cel·la pren l'alçada de
   la fila (44, o 48 al Bloc). L'espaiador és un div buit i, centrat, feia
   16px d'alt: el taronja de la T26.1 quedava en una franja. */
.sdp-workspace-folder-row { display: flex; align-items: stretch; color: var(--sdp-crom-text); }
.sdp-workspace-folder-row > .sdp-workspace-nav-item { min-width: 0; }
.sdp-workspace-folder-row > .sdp-workspace-folder-toggle,
.sdp-workspace-folder-row > .sdp-workspace-folder-toggle-spacer {
  width: var(--sdp-touch-min);
  flex: none;
  padding: var(--sdp-space-2);
  justify-content: center;
}
.sdp-workspace-folder-toggle[aria-expanded="false"] svg { transform: rotate(-90deg); }
.sdp-workspace-nav-item {
  display: flex;
  align-items: center;
  /* T28 · 16px com el rail del Xat (abans 13, que Pedra Seca §3 no admet):
     icona de 24 a l'eix 28 i text a 56 de la vora, a totes les llistes. */
  gap: var(--sdp-space-4);
  width: 100%;
  min-height: var(--sdp-touch-min);
  padding: var(--sdp-space-2) var(--sdp-space-4);
  border: 0;
  /* Entrada de la primera columna (carpetes del Bloc, rail del Xat):
     rectangle pur a sang, com la barra principal (regla definitiva del
     Mestre, 260927 vespre). Els botons d'acció, en canvi, són píndoles. */
  border-radius: 0;
  background: transparent;
  color: inherit;
  font: var(--sdp-font-barra);
  letter-spacing: normal;
  text-transform: none;
  text-align: start;
  cursor: pointer;
  transition: background var(--sdp-t), color var(--sdp-t);
}
@media (hover: hover) and (pointer: fine) {
  .sdp-workspace-nav-item:hover { background: var(--sdp-crom-hover); color: var(--sdp-crom-text); }
}
/* T62 · L'entrada activa de la 1a columna va en blau de crom
   (--sdp-crom-seleccio-*, tokens.css). T62b (ordre del Mestre, 260928):
   fons blau fort, text i icona blancs, 7,20:1. Les xifres de la cel·la
   contra la columna i del focus viuen a tokens.css, al costat dels tokens.
   La barra principal conserva --sdp-crom-actiu-*. */
.sdp-workspace-nav-item[aria-current="page"] {
  position: relative;
  background: var(--sdp-crom-seleccio-fons);
  color: var(--sdp-crom-seleccio-text);
}
/* T62b · Marcador blanc de 3px (decisió del Mestre, 260928: «Marcador blanc
   3px»). A l'inici de línia de la cel·la activa, perquè l'estat no depenga
   només del color (WCAG 1.4.1): el blau de la cel·la contra la columna fa
   1,55:1, i el marcador, 11,20:1 (xifres a tokens.css). És un pseudo-element
   posat damunt de la cel·la: no li canvia el coixí ni l'amplària, i cap text
   ni cap icona es mou. Cap ombra. */
.sdp-workspace-nav-item[aria-current="page"]::before {
  content: '';
  position: absolute;
  inset-block: 0;
  inset-inline-start: 0;
  inline-size: 3px;
  background: var(--sdp-crom-seleccio-text);
  pointer-events: none;
}
/* T26.1 (ordre del Mestre, 260927 nit) · La fila de l'arbre acaba en un
   botó de desplegar o en un espaiador de 44px (CategoryBranch):
   quan l'entrada és l'activa, eixa cel·la també va del color de la
   selecció, i el fons arriba a la vora dreta com al rail del Xat, que no en
   té. Germà adjacent en lloc de :has() (Baseline 2022). */
.sdp-workspace-folder-row > .sdp-workspace-nav-item[aria-current="page"] + .sdp-workspace-folder-toggle,
.sdp-workspace-folder-row > .sdp-workspace-nav-item[aria-current="page"] + .sdp-workspace-folder-toggle-spacer {
  background: var(--sdp-crom-seleccio-fons);
  color: var(--sdp-crom-seleccio-text);
}
/* T62b · La icona de la cel·la activa, obligatòriament blanca: el glif de
   NavGlyph, la icona del rail del Xat i el chevron del toggle pinten amb
   currentColor, i ací es fixen al token de selecció perquè cap regla
   d'icona els desvie. L'entrada inactiva no es toca: hereta com sempre. */
.sdp-workspace-nav-item[aria-current="page"] .sdp-workspace-nav-item__icon,
.sdp-workspace-nav-item[aria-current="page"] svg,
.sdp-workspace-folder-row > .sdp-workspace-nav-item[aria-current="page"] + .sdp-workspace-folder-toggle svg {
  color: var(--sdp-crom-seleccio-text);
}
.sdp-workspace-nav-item__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  flex: none;
  color: inherit;
}
.sdp-workspace-nav-item__label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sdp-workspace-nav-item:focus-visible {
  /* La columna és crom (fosca en els dos temes): l'anell de focus és el de la closca. */
  outline: 2px solid var(--sdp-crom-focus);
  outline-offset: -2px;
}

.sdp-workspace-detail {
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  overflow-x: hidden;
  background: var(--sdp-fons-app);
}
/* Barres (ordre del Mestre, 261004: que la barra fixa no «es menge
   contingut») · En compacte, la barra mòbil (nav.mobile-nav, fixa) tapa la
   part de baix de la closca: .app-grid-page és absoluta i no fa cas del
   coixí d'.app-main__content (layout.css). Cada scroller del Workspace en
   reserva l'alçada dins seu, com el Xat (.sdp-xat-conversa i
   .sdp-xat-llista, més avall): l'última icona del rail, l'última fitxa i el
   final del document queden per damunt de la barra. Abast positiu
   (.sdp-workspace--universal, que posa UniversalWorkspace): el Xat també
   porta .sdp-workspace i no l'ha de tindre doble. La condició, la de la
   barra: .sdp-root.is-compact (:where() pesa 0).
   Correcció dels verificadors (261004) · L'abast és l'estructura pròpia
   del Workspace, amb combinadors de fill des de la closca (.app-grid-page
   > article > contingut > columna > aside), no qualsevol descendent: el
   detall de Disseny pinta components de producció del Xat (rail plegat,
   VistaComunitats) en marcs fixos que no toquen la barra, i hi rebien una
   segona reserva (144 px dins d'un marc de 576 a 820). Els quatre
   scrollers: el rail d'una columna plegada (navegació o llista), el rail
   d'«estret» (#app-grid-rail), el cos de la navegació i de la llista, i
   el detall. */
:where(.sdp-root.is-compact) .sdp-workspace--universal > .app-grid-shell > .app-grid-content > .app-grid-column > .sdp-workspace-column > .app-grid-col-header--collapsed > .sdp-workspace-rail,
:where(.sdp-root.is-compact) .sdp-workspace--universal > .app-grid-shell > .app-grid-content > .app-grid-rail > .sdp-workspace-column > .app-grid-col-header--collapsed > .sdp-workspace-rail,
:where(.sdp-root.is-compact) .sdp-workspace--universal > .app-grid-shell > .app-grid-content > .app-grid-column > .sdp-workspace-column > .sdp-workspace-column__body,
:where(.sdp-root.is-compact) .sdp-workspace--universal > .app-grid-shell > .app-grid-content > .app-grid-column--right > .sdp-workspace-detail {
  padding-bottom: calc(var(--sdp-alt-nav-mobil) + env(safe-area-inset-bottom, 0px));
}
.notes-column {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 0;
  overflow: hidden;
  background: inherit;
}

.notes-column__body {
  flex: 1 1 0;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
}

.notes-column__body.no-padding {
  padding: 0;
}

.sdp-scrollable {
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
}

.notes-list-header {
  padding: var(--sdp-space-3) var(--sdp-space-4);
  border-bottom: 1px solid var(--sdp-crom-vora);
  color: var(--sdp-crom-text);
}

.univ-manager-toolbar {
  display: flex;
  align-items: center;
  gap: var(--sdp-space-2);
  min-height: var(--sdp-touch-min);
}

.univ-manager-toolbar--facets {
  justify-content: space-between;
  background: var(--sdp-crom-fons);
}

.univ-manager-toolbar--list {
  justify-content: space-between;
  background:
    linear-gradient(var(--sdp-crom-hover), var(--sdp-crom-hover)),
    var(--sdp-crom-fons);
}

.univ-manager-inbox {
  display: inline-flex;
  flex: 1 1 auto;
  align-items: center;
  justify-content: flex-start;
  gap: var(--sdp-space-2);
  min-height: var(--sdp-touch-min);
  padding: 0 var(--sdp-space-3);
  border: 0;
  border-radius: var(--sdp-radi-s);
  background: transparent;
  color: var(--sdp-crom-text);
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}



.univ-manager-toolbar--list .btn-primary {
  display: inline-flex;
  align-items: center;
  gap: var(--sdp-space-1);
  min-height: var(--sdp-touch-min);
  padding-inline: var(--sdp-space-3);
  white-space: nowrap;
}





.search-bar {
  display: flex;
  align-items: center;
  gap: var(--sdp-space-2);
  background: var(--sdp-fons-subtil);
  padding: var(--sdp-space-2) var(--sdp-space-3);
  border-radius: var(--sdp-radi-s);
  border: 1px solid var(--sdp-vora);
}

.search-bar input {
  flex: 1;
  min-width: 0;
  background: transparent;
  border: none;
  font: inherit;
  font-size: var(--sdp-text-small);
  color: var(--sdp-text-cos);
  outline: none;
}
.search-bar input:focus-visible { outline: 2px solid var(--sdp-accio-forta); outline-offset: 2px; }

.univ-manager-facet-header {
  padding: var(--sdp-space-4) var(--sdp-space-4) var(--sdp-space-2);
  margin: 0;
  font-size: var(--sdp-text-meta);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--sdp-text-suau);
}

.univ-manager-facet-item {
  display: flex;
  align-items: center;
  gap: var(--sdp-space-3);
  padding: var(--sdp-space-2) var(--sdp-space-4);
  width: 100%;
  text-align: left;
  border: none;
  background: transparent;
  color: var(--sdp-text-suau);
  font-family: inherit;
  /* Era var(--sdp-text-cos), que és un token de COLOR: la declaració
     s'invalidava i el navegador la descartava. */
  font-size: var(--sdp-text-base);
  cursor: pointer;
  transition: background var(--sdp-t), color var(--sdp-t);
  border-radius: 0;
}

@media (hover: hover) and (pointer: fine) {
  .univ-manager-facet-item:hover {
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-titol);
  }
}

/* T62 · Actiu en blau d'acció, com la fitxa del llistat: el text continua
