/* AAA (Q1, 261004) · El blanc de 11,2px sobre el blau de marca (--sdp-accio)
   feia 3,87:1, ni AA. La superfície de control amb text blanc,
   --sdp-accio-control, fa 9,21:1: és el «fons blau fosc» de la Carpeta
   (sdp-universal-page §4.1) i el parell de la píndola premuda. */
.sdp-badge-buit {
  background: transparent;
  color: var(--sdp-accio-control);
  box-shadow: inset 0 0 0 1px var(--sdp-accio-control);
}

:root[data-theme="dark"] .sdp-badge-buit,
:host([data-theme="dark"]) .sdp-badge-buit {
  color: var(--sdp-accent);
  box-shadow: inset 0 0 0 1px var(--sdp-accent);
}

.sdp-badge-system {
  background: var(--sdp-accio-control);
  color: var(--sdp-sobre-accio);
}

:root[data-theme="dark"] .sdp-badge-system,
:host([data-theme="dark"]) .sdp-badge-system {
  background: var(--sdp-accent);
  color: var(--sdp-sobre-accent);
}

.sdp-badge-accent {
  background: var(--sdp-accent);
  color: var(--sdp-sobre-accent);
}

:root[data-theme="dark"] .sdp-badge-accent,
:host([data-theme="dark"]) .sdp-badge-accent {
  background: var(--sdp-accio-control);
  color: var(--sdp-sobre-accio);
}

.sdp-badge-category {
  background: var(--sdp-accio-subtil);
  color: var(--sdp-accio-text);
}

.sdp-badge-tag {
  background: var(--sdp-accent-subtil);
  color: var(--sdp-accent-text-hover);
}

.sdp-badge-neutral {
  background: var(--sdp-fons-subtil);
  color: var(--sdp-text-titol);
}

