/* ==========================================================================
   FASE 4: EXPERIÈNCIA PRÈMIUM (PEDRA SECA UX)
   ========================================================================== */

/* --- 1. View Transitions API (La Pedra Lliscant) ---
   Article 1 de la Constitució: «cap transició marejant». Entre dues vistes,
   una fosa d'opacitat de 200ms (--sdp-durada-base) i res més: la pàgina ja
   no s'escala (abans 0,98 i 1,02 en 400ms). Amb menys moviment, cap
   animació. Els @keyframes sdp-fade-in i sdp-fade-out viuen amb el calaix. */

@supports (view-transition-name: root) {
@media (prefers-reduced-motion: no-preference) {
    ::view-transition-old(root),
    ::view-transition-new(root) {
      animation-duration: var(--sdp-durada-base);
      animation-timing-function: var(--sdp-corba-eixida);
      animation-fill-mode: both;
    }

    ::view-transition-old(root) {
      animation-name: sdp-fade-out;
    }

    ::view-transition-new(root) {
      animation-name: sdp-fade-in;
    }
}
}

/* --- 2. Scroll-Driven Animations ---
   Retirades (261004): sdp-reveal i sdp-parallax no tenien cap consumidor i
   animation-timeline no és de la Baseline 2022. */

/* --- 3. Mode Bancal (Accessibilitat Visual) ---
   Interruptor data-contrast="bancal" a :root o :host (Q1, 261004): contrast
   AAA sota el sol, text opac i pes de 600 o més en la lletra menuda. Les
   regles d'este full viuen al bloc «MODE BANCAL · SUPERFÍCIES DE
   MODULES.CSS», al final del fitxer i dins de @layer components: ací, dins
   de `legacy`, perdrien contra les regles de `components` (Xat, Consola,
   Calendari). Els colors els canvia tokens.css; ací no n'hi ha cap. */

/* Reducció global de moviment: la fan els tokens. Amb
   prefers-reduced-motion, --sdp-escala-aparicio val 1 i --sdp-despl-aparicio
   0 (tokens.css): menús, avisos i diàlegs només fan la fosa. */

/* --- 4. Micro-interaccions (Hàptica) --- */

/* === TOC DRAWER ===
   Q4 (261004) · Abans `var(--sdp-t) ease-out`, que es resolia a
   `0.18s ease ease-out`: dues corbes fan el shorthand invàlid i ni el vel ni
   el calaix s'animaven mai. Ara durada i corba són tokens separats: el vel fa
   una fosa de 200ms i el calaix entra en 280ms amb la corba de calaix. Amb
   menys moviment, l'apagador global de base.css ho fa instantani. */

.toc-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background: var(--sdp-fons-vel);
  z-index: var(--z-calaix);
  display: flex;
  animation: sdp-fade-in var(--sdp-durada-base) var(--sdp-corba-eixida);
}

.toc-drawer {
  width: 85%;
  max-width: 320px;
  height: 100%;
  background: var(--sdp-fons-targeta);
  box-shadow: var(--sdp-ombra-3);
  overflow-y: auto;
  animation: slideInLeft var(--sdp-durada-panell) var(--sdp-corba-calaix);
  display: flex;
  flex-direction: column;
}

.toc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--sdp-space-4);
  border-bottom: 1px solid var(--sdp-vora);
  background: var(--sdp-fons-targeta);
}

.toc-header h2 {
  font-size: 1.1rem;
  margin: 0;
  color: var(--sdp-text-titol);
  font-weight: 700;
}

.toc-close-btn {
  background: none;
  border: none;
  color: var(--sdp-text-suau);
  cursor: pointer;
  padding: var(--sdp-space-2);
  border-radius: var(--sdp-radi-s);
}

@media (hover: hover) and (pointer: fine) {
  .toc-close-btn:hover {
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-titol);
  }
}

.toc-nav {
  padding: var(--sdp-space-4);
}

.toc-nav ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.toc-empty {
  color: var(--sdp-text-suau);
  font-style: italic;
  text-align: center;
}

.toc-item {
  margin-bottom: 0;
}

.toc-item button {
  background: none;
  border: none;
  text-align: left;
  width: 100%;
  padding: 6px var(--sdp-space-2);
  color: var(--sdp-text-cos);
  font-size: 0.95rem;
  cursor: pointer;
  border-radius: var(--sdp-radi-s);
  transition: background var(--sdp-t), color var(--sdp-t);
}

.toc-item button:focus-visible {
  background: var(--sdp-fons-subtil);
  color: var(--sdp-text-titol);
}

@media (hover: hover) and (pointer: fine) {
  .toc-item button:hover {
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-titol);
  }
}

.toc-level-1:first-child {
  margin-top: 0;
}

.toc-level-1 button {
  font-weight: 800;
  font-size: 0.95rem;
  color: var(--sdp-accio-text);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.toc-level-1 button:focus-visible {
  color: var(--sdp-accio-text);
}

@media (hover: hover) and (pointer: fine) {
  .toc-level-1 button:hover {
    color: var(--sdp-accio-text);
  }
}

.toc-level-2 button {
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--sdp-accent-titol);
}

/* AAA (Q1, 261004) · Cap hover baixa de banda. --sdp-accent-hover és un
   token de FONS: com a text feia 3,58:1. --sdp-accent-text-hover fa 7,97:1
   sobre la targeta en clar (sobre --sdp-fons-subtil, el fons del hover,
   6,76:1) i passa de 10:1 en fosc. */
.toc-level-2 button:focus-visible {
  color: var(--sdp-accent-text-hover);
}

@media (hover: hover) and (pointer: fine) {
  .toc-level-2 button:hover {
    color: var(--sdp-accent-text-hover);
  }
}

.toc-level-3 button {
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--sdp-accio-text);
}

/* AAA (Q1, 261004) · El hover passava a --sdp-accio, el blau de marca, que
   sobre --sdp-fons-subtil fa 3,29:1 en clar: es queda en --sdp-accio-text
   (7,81:1 sobre el fons del hover) i el feedback el dona el fons. */
.toc-level-3 button:focus-visible {
  color: var(--sdp-accio-text);
}

@media (hover: hover) and (pointer: fine) {
  .toc-level-3 button:hover {
    color: var(--sdp-accio-text);
  }
}

.toc-level-4 button {
  font-weight: 400;
  font-size: 0.95rem;
  color: var(--sdp-text-suau);
}

/* T2 (ordre del Mestre, 260930) · Els nivells 5 i 6 arriben a l'Índex de
   totes les pàgines (PageFrame, NIVELL_INDEX_PER_DEFECTE = 6): les mètriques
   en h5 de la Consola i qualsevol h5 o h6 d'una targeta o d'un document. El
   sagnat i el pes es van pensar per a les mètriques, que es lligen com a
   filles de la targeta que tenen damunt; els nivells 1-4 no van sagnats. */
.toc-level-5 button {
  padding-left: calc(var(--sdp-space-2) + var(--sdp-space-4));
  font-weight: 700;
  color: var(--sdp-text-cos);
  font-variant-numeric: tabular-nums;
}

.toc-level-6 button {
  padding-left: calc(var(--sdp-space-2) + var(--sdp-space-6));
  font-weight: 400;
  color: var(--sdp-text-suau);
}

@keyframes slideInLeft {
  from {
    transform: translateX(-100%);
  }

  to {
    transform: translateX(0);
  }
}

@keyframes sdp-fade-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

/* La meitat d'eixida de la fosa entre vistes (View Transitions, dalt). */
@keyframes sdp-fade-out {
  from {
    opacity: 1;
  }

  to {
    opacity: 0;
  }
}

