/* Universal Toolbar (shared between Notes and Profiles) */

.editor-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex: none;
  height: auto;
  min-height: var(--sdp-alt-accio);
  flex-wrap: nowrap;
  overflow-x: auto;
  gap: var(--sdp-space-2);
  padding: var(--sdp-space-1) var(--sdp-space-4);
  background: linear-gradient(var(--sdp-crom-hover), var(--sdp-crom-hover)), var(--sdp-crom-fons);
  color: var(--sdp-crom-text);
  border-bottom: 1px solid var(--sdp-crom-vora);
}

/* Universal Action Bars (Graelles) */



.editor-toolbar .toolbar-actions {
  display: flex;
  flex: 1 1 240px;
  flex-wrap: nowrap;
  gap: var(--sdp-space-1);
  min-width: 0;
}

.editor-toolbar .toolbar-actions.right {
  margin-left: auto;
  flex: 0 0 auto;
}

.editor-toolbar .toolbar-actions button {
  background: transparent;
  color: inherit;
  border: none;
  cursor: pointer;
  padding: var(--sdp-space-1);
  border-radius: var(--sdp-radi-s);
}

@media (hover: hover) and (pointer: fine) {
  .editor-toolbar .toolbar-actions button:hover:not(:disabled) {
    background: var(--sdp-crom-hover);
  }
}

.editor-toolbar button:disabled {
  opacity: .5;
  cursor: default;
}

/* --- REFINAMENTS DE UI --- */

.photo-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: var(--sdp-space-2);
  margin-top: var(--sdp-space-4);
}

.photo-grid__item {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  border-radius: var(--sdp-radi-m);
  border: 1px solid var(--sdp-vora);
}

.stack-grid {
  display: flex;
  flex-direction: column;
  gap: var(--sdp-space-4);
}

.sdp-stat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(100px, 1fr));
  gap: var(--sdp-space-3);
  margin: var(--sdp-space-4) 0;
}

.sdp-stat-card {
  background: var(--sdp-fons-subtil);
  border: 1px solid var(--sdp-vora);
  border-radius: var(--sdp-radi-m);
  padding: var(--sdp-space-4);
  text-align: center;
}

/* AAA (Q1, 261004): el taronja de marca és un token de FONS i com a text
   feia 2,31:1 sobre la targeta. --sdp-accent-text-hover, el taronja de
   text AAA, fa 6,76:1 sobre --sdp-fons-subtil en clar i passa de 7:1 en
   fosc: 24px en negreta és text gran, i el llindar AAA hi és 4,5:1. */
.sdp-stat-value {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--sdp-accent-text-hover);
}

.sdp-stat-label {
  font-size: var(--sdp-text-meta);
  color: var(--sdp-text-suau);
  text-transform: uppercase;
  margin-top: var(--sdp-space-1);
  font-weight: 600;
}

/* --- LOGO CREATIVE COMMONS --- */

.cc-logo-container {
  display: flex;
  justify-content: center;
  margin: var(--sdp-space-8) 0;
}

.cc-logo-container img {
  width: 400px;
  max-width: 100%;
  height: auto;
}

/* --- CERCA UNIVERSAL --- */

.universal-search-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}

.universal-search-icon {
  position: absolute;
  left: var(--sdp-space-3);
  color: var(--sdp-text-suau);
}

.universal-search-input {
  width: 100%;
  padding: var(--sdp-space-3) var(--sdp-space-3) var(--sdp-space-3) var(--sdp-space-10);
  border: 2px solid var(--sdp-vora);
  border-radius: var(--sdp-radi-pastilla);
  font-size: var(--sdp-text-base);
  font-family: inherit;
  background: var(--sdp-fons-targeta);
  color: var(--sdp-text-titol);
  /* Kowalski: cap `all`. L'anell d'ombra del focus apareix de colp. */
  transition: border-color var(--sdp-t), background-color var(--sdp-t);
}

.universal-search-input:focus {
  border-color: var(--sdp-accio-forta);
  background: var(--sdp-fons-targeta);
  box-shadow: 0 0 0 4px var(--sdp-accio-subtil);
  outline: none;
}
.universal-search-input:focus-visible { outline: 2px solid var(--sdp-accio-forta); outline-offset: 2px; }

} /* fi @layer legacy (obert a la línia ~637) */

/* ÍNDEX DE SECCIÓ · el calaix enfocat per programa (correcció final, ordre
   del Mestre, 261004). En obrir-se, PageFrame li dona el focus (tabIndex -1),
   a la SPA i a l'encastat, perquè el diàleg aria-modal siga on és el
   teclat. És un contenidor, no un control: no pinta cap anell, ni obert amb
   el ratolí ni amb el teclat (Llei del Píxel). Les entrades i l'aspa, que sí
   que són controls, conserven el seu anell de :focus-visible (base.css).
   Arreglo dels verificadors (ordre del Mestre, 261004): la regla era
   :focus:not(:focus-visible), i Chrome hereta el :focus-visible de l'element
   que tenia el focus; després d'un Esc o d'un Tab, una obertura amb el
   ratolí pintava l'anell de 3px a la vora del calaix. Fora de la capa legacy
   on viu la resta del calaix (.toc-drawer, més amunt): tota regla nova va a
   components. */
@layer components {
  .toc-drawer:focus { outline: none; }
}

/* ═══ BLOC DE NOTES (PROPOSTA CODEX) ═════════════════════════════════
   Va a la capa `components`, no a `legacy`: l'ordre de capes és
   reset, sdp, legacy, components, utilities, i AppGridShell.css (components)
   declara --app-grid-bg-* al mateix element. Dins de `legacy` cap
   especificitat guanyaria; dins de `components` decideix l'ordre
   d'@import (modules.css va abans) i per això usem `.app-grid-page.sdp-bloc`. */
@layer components {
  /* Dues files fixes amb profunditat en DOS eixos, cap dels dos inventat:
       · Per FILA (captura de referència del Mestre, 260922): la fila de dalt
         és la fosca —del pes de la barra global— i la de baix, la dels
         controls, és el gris clar. Així la segona fila «no és tan fosca com
         la barra superior», que és el que es demanava.
       · Per COLUMNA (sdp-app-grid-shell §2): dins de cada fila, la central
         queda un escaló més clara que l'esquerra.
     L'escala és monòtona i sense forats: 900 → 800 → 750 → 700 → 600.
     Cada barra aclarix cap amunt, que és d'on ve la llum. */
  /* Una sola jerarquia de grisos per a TOTS els espais de treball (Bloc, Wiki,
     Disseny…), plana i sense degradats (sdp-app-grid-shell §2; ordre del
     Mestre, 260924 vesprada; pla 1710 §3.4 «unificar sota la mateixa
     AppGridShell»):
       · fila 1 (títols de columna · eines de l'editor · PUBLICAR): Carbó 800
       · fila 2 (Tot i roda · lupa, ordenar i CREAR): Pissarra 750
       · columna de navegació i el seu arbre: Grafit 700
     Es pinten amb els --sdp-crom-* que resolen a eixos primitius: cap
     component escriu --sdp-pedra-* (tokens.css §0). Ajustar el contrast és
     canviar una d'estes tres línies, i cap secció en redefinix cap: abans el
     Bloc tenia la seua pròpia escala (800/750/600) i Wiki i Disseny portaven
     degradats, i en canviar de secció la graella canviava de cara. */
  .sdp-workspace,
  .app-grid-page.sdp-workspace {

    --app-grid-bg-esquerra: var(--sdp-workspace-nav-fons);
  }
  .sdp-workspace .sdp-workspace-column > .app-grid-col-header:not(.app-grid-col-header--collapsed),
  .sdp-workspace .app-grid-column--left .sdp-workspace-column > .app-grid-col-header,
  .sdp-workspace .sdp-editor-tools {
    background: var(--sdp-workspace-fila1-fons);
    color: var(--sdp-crom-text);
  }
  .sdp-workspace .sdp-workspace-column > .app-grid-col-header:not(.app-grid-col-header--collapsed) {
    height: var(--sdp-alt-accio);
    min-height: var(--sdp-alt-accio);
    flex: none;
  }
  .sdp-workspace .sdp-workspace-column > .app-grid-col-header + .app-grid-col-header,
  .sdp-workspace .app-grid-column--left .sdp-workspace-column > .app-grid-col-header + .app-grid-col-header {
    background: var(--sdp-workspace-fila2-fons);
  }
  .sdp-workspace .app-grid-column--left {
    background: var(--sdp-workspace-nav-fons);
    color: var(--sdp-crom-text);
    color-scheme: dark;
  }
  .sdp-workspace .sdp-workspace-groups { background: var(--sdp-workspace-nav-fons); }
  .sdp-workspace .app-grid-col-header .app-grid-col-header__plegable {
    padding: 0;
    gap: var(--sdp-space-2);
    background: transparent;
    color: var(--sdp-crom-text);
  }
  /* El títol de la columna NO és un element de navegació seleccionat, i des
     del 260924 AppGridColumn.jsx ja no li posa aria-current="page" (A11Y, P10
     de l'auditoria 0754). En repòs, la regla de dalt (0,3,0) el deixa
     transparent i blanc, com abans.

     LLEI DEL PÍXEL · decisió pendent del Mestre. Amb l'atribut, el Bloc li
     pintava dos restes del «fantasma» que sdp-app-grid-shell §2 prohibix:
     la icona en --sdp-primary-700 i, en hover, el fons crema amb text negre
     (la regla :hover de l'actiu, (0,4,0), guanyava per ordre a la tapadora).
     Perquè llevar l'atribut no moga cap píxel, el títol plegable s'ha afegit
     com a selector a eixes dues regles de l'actiu (més avall, «Actiu: fons
     clar»). Per a matar el fantasma, lleva'n els dos selectors marcats P10:
     el títol quedarà blanc i, en hover, amb el vel de la resta de la columna. */
  .sdp-workspace .app-grid-col-header__plegable .sdp-workspace-nav-item__icon {
    width: var(--sdp-touch-min);
    flex: none;
    justify-content: center;
  }
  .sdp-workspace .app-grid-col-header__accio-text > svg {
    box-sizing: content-box;
    padding-inline: calc((var(--sdp-touch-min) - 18px) / 2);
    flex: none;
  }
  .sdp-workspace .app-grid-col-header .app-grid-col-header__accio-text {
    padding-inline: 0 var(--sdp-space-3);
  }
  .sdp-workspace .app-grid-col-header__plec > svg {
    box-sizing: content-box;
    padding-inline: calc((var(--sdp-touch-min) - 20px) / 2);
    flex: none;
  }
  .sdp-workspace .app-grid-col-header__accio:disabled {
    background: var(--sdp-crom-hover);
    color: var(--sdp-crom-text-suau);
    cursor: default;
  }
  .sdp-workspace .app-grid-col-header--collapsed {
    display: grid;
    grid-template-rows: repeat(2, var(--sdp-alt-accio)) minmax(0, 1fr);
    justify-items: center;
    align-items: center;
    justify-content: stretch;
    gap: 0;
    padding: 0;
    background: var(--sdp-workspace-fila1-fons);
  }

  /* El Bloc de Notes ja no redefinix cap color: només mides pròpies
     (controls còmodes de 48px i la miniatura quadrada de la targeta). Els
     colors, l'actiu (blau de selecció des de T62) i el focus són els
     generals de dalt. Ací morien
     els «fantasmes» (actiu crema amb icona taronja i hover crema del títol
     plegable) que sdp-app-grid-shell §2 prohibix. */

  /* Segona fila de capçalera (Tot/engranatge · lupa/CREAR NOTA): immòbil.
     Les capçaleres viuen fora del cos amb scroll, però el sticky les blinda igualment. */
  .sdp-bloc .app-grid-column--middle .app-grid-col-header {
    position: sticky;
    top: 0;
    flex: none;
  }

  /* Acordions de navegació (CATEGORIES, ETIQUETES): capçalera del gris de la columna, amb chevron. */
  .sdp-bloc .sdp-workspace-group + .sdp-workspace-group { margin-top: var(--sdp-space-2); }
  .sdp-bloc .app-grid-col-header--accordion {
    background: var(--sdp-workspace-nav-fons);
    border-bottom-color: var(--sdp-crom-vora);
  }
  .sdp-bloc .app-grid-col-header--accordion .app-grid-col-header__plec { gap: var(--sdp-space-2); }

  .sdp-bloc .sdp-workspace-nav-item { min-height: var(--sdp-bloc-control); }

  /* Variant de notes; aplicar només quan presentation.list === 'notes'.
     Targeta rica: miniatura quadrada (86px) · títol + data · entradeta. */
  .sdp-bloc-list--notes .sdp-gestor-fitxa {
    min-height: var(--sdp-bloc-fitxa-mida);
    align-items: stretch;
    background: var(--sdp-fons-app);
  }
  /* T62 · Els mateixos tokens que .sdp-gestor-fitxa[aria-current]: sense
     esta regla, el fons --sdp-fons-app de dalt guanyaria per ordre. */
  .sdp-bloc-list--notes .sdp-gestor-fitxa[aria-current="true"] {
    background: var(--sdp-accio-subtil);
    border-inline-start-color: var(--sdp-accio);
  }
  .sdp-bloc-list--notes .sdp-gestor-fitxa__media {
    flex: 0 0 var(--sdp-bloc-fitxa-mida);
    width: var(--sdp-bloc-fitxa-mida);
    height: var(--sdp-bloc-fitxa-mida);
    align-self: center;
  }
  .sdp-bloc-list--notes .sdp-gestor-fitxa__text {
    gap: 2px;
    padding: var(--sdp-space-2) var(--sdp-space-3);
    justify-content: center;
  }
  .sdp-nota-fitxa__capcalera {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--sdp-space-2);
    min-width: 0;
  }
  .sdp-bloc-list--notes .sdp-gestor-fitxa__titol {
    flex: 1 1 auto;
    min-width: 0;
    font-size: var(--sdp-ui-base);
    font-weight: 700;
  }
  .sdp-nota-fitxa__data {
    flex: none;
    font-size: var(--sdp-text-meta);
    font-variant-numeric: tabular-nums;
    color: var(--sdp-text-suau);
    white-space: nowrap;
  }
  .sdp-bloc-list--notes .sdp-gestor-fitxa__subtitol {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    white-space: normal;
    /* Sòl de 14px (abans --sdp-ui-sm, 13px). Dos línies de 14 × 1,3 i el
       títol caben encara dins dels 86px de la fitxa (73,9px de text i coixí). */
    font-size: var(--sdp-text-meta);
    color: var(--sdp-text-suau);
    font-weight: 400;
  }
  .sdp-bloc-date-group {
    padding: var(--sdp-space-4) var(--sdp-space-3) var(--sdp-space-2);
    margin: 0;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
    font-weight: 700;
  }

  .sdp-editor-tools {

    flex: none;
    width: 100%;
    min-width: 0;
    color: var(--sdp-crom-text);
    background: var(--sdp-crom-fons);
  }
  .sdp-editor-tools__actions,
  .sdp-editor-tools__formats {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-2);
    flex-wrap: wrap;
    min-height: var(--sdp-alt-accio);
    padding: var(--sdp-space-1) var(--sdp-space-2);
    border-bottom: 1px solid var(--sdp-crom-vora);
  }
  .sdp-editor-tools__actions > .sdp-bloc-action { margin-inline-start: auto; }
  .sdp-editor-tools__group {
    display: flex;
    flex-wrap: wrap;
    gap: var(--sdp-space-1);
    border-inline-end: 1px solid var(--sdp-crom-vora-forta);
    padding-inline-end: var(--sdp-space-2);
  }
  .sdp-editor-tools__group:last-child { border-inline-end: 0; }

  /* Botonera de classificació (punt 7 del Mestre): Carpetes, Categories i
     Etiquetes davall del títol de l'editor, al lloc de les píndoles. Mateix
     marge que .page-title-labels. Davall, centrada, la ranura de la llicència.
     La columna de l'editor ja no té barra grisa: amb les eines a dalt, després
     d'elles ve la barra blava, a la fila 2 (sdp-app-grid-shell §2); amb les
     eines davall de l'entradilla (D13, Perfil i Bloc de Notes) la blava és la
     fila 1. */
  .page-title-classificacio {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--sdp-space-3);
    margin-block: var(--sdp-space-8);
  }
  .sdp-classificacio-botonera {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--sdp-space-2);
  }
  .sdp-classificacio-botonera > .sdp-boto { padding-inline: var(--sdp-space-4); }
  /* El resum hereta la tinta del botó: el contrast és el de la varietat. */
  .sdp-classificacio-botonera__resum {
    margin-inline-start: var(--sdp-space-2);
    font-weight: 400;
    font-variant-numeric: tabular-nums;
  }
  /* T23 · l'emoticona triada ocupa el lloc de la icona del botó (mateixa
     separació que la icona de lucide del botó veí). Al diàleg, la mostra
     grossa al costat del camp. */
  .sdp-classificacio-botonera__glif {
    margin-inline-end: var(--sdp-space-1);
    font-style: normal;
    line-height: 1;
  }
  .sdp-classificacio-dialeg__mostra {
    flex: none;
    align-self: center;
    min-width: var(--sdp-touch);
    text-align: center;
    font-size: var(--sdp-text-h3);
    line-height: 1;
  }

  /* Modals de classificació: fila = casella + reanomenar + esborrar. */
  .sdp-classificacio-dialeg__llista {
    display: grid;
    gap: var(--sdp-space-1);
    margin: 0 0 var(--sdp-space-4);
    padding: 0;
    list-style: none;
  }
  .sdp-classificacio-dialeg__fila {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-1);
  }
  .sdp-classificacio-dialeg__fila > .sdp-casella { flex: 1 1 auto; min-width: 0; }
  .sdp-classificacio-dialeg__fila > .sdp-boto {
    min-width: var(--sdp-touch);
    padding-inline: var(--sdp-space-2);
  }
  .sdp-classificacio-dialeg__edicio {
    display: flex;
    flex: 1 1 auto;
    flex-wrap: wrap;
    align-items: flex-end;
    gap: var(--sdp-space-2);
    padding-block: var(--sdp-space-2);
  }
  .sdp-classificacio-dialeg__edicio > .sdp-camp,
  .sdp-classificacio-dialeg__edicio > .sdp-classificacio-dialeg__avis { flex: 1 1 100%; margin-bottom: 0; }
  .sdp-classificacio-dialeg__avis {
    margin: 0 0 var(--sdp-space-3);
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
  }
  .sdp-classificacio-dialeg__afegir {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    gap: var(--sdp-space-2);
  }
  .sdp-classificacio-dialeg__afegir > .sdp-camp { flex: 1 1 12rem; margin-bottom: 0; }
  .sdp-classificacio-dialeg__reservat {
    display: flex;
    flex-wrap: wrap;
    gap: var(--sdp-space-2);
    margin-top: var(--sdp-space-4);
  }
  .sdp-classificacio-dialeg__reservat > .sdp-classificacio-dialeg__avis { flex: 1 1 100%; margin-bottom: 0; }

  /* T7 (P8, ordre del Mestre) · Quan un grup ja està triat, cada valor és
     una píndola de lectura (sp-card-label + sdp-badge-*, les de PageFrame)
     dins d'un botó transparent que fa l'àrea tàctil (--sdp-touch). La fila
     centra en vertical: el botó de resum i la píndola queden alineats, i una
     botonera sense píndoles es veu com sempre.
     T7B-V1 · Un sol botó per grup: les píndoles del grup s'hi ajunten i, si no
     caben, passen a una altra fila de 24 px dins del mateix botó. Entre
     píndoles d'un grup, --sdp-space-1; entre grups, el --sdp-space-2 de la
     botonera: la vista agrupa el que obri el mateix diàleg. */
  .sdp-classificacio-botonera { align-items: center; }
  .sdp-classificacio-pindola {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    align-content: center;
    justify-content: center;
    gap: var(--sdp-space-1);
    min-width: var(--sdp-touch);
    min-height: var(--sdp-touch);
    max-width: 100%;
    padding: 0;
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    cursor: pointer;
  }
  .sdp-classificacio-pindola > .sp-card-label {
    gap: var(--sdp-space-1);
    max-width: 100%;
    overflow: hidden;
  }
  .sdp-classificacio-pindola > .sp-card-label > svg {
    flex: none;
    width: var(--sdp-icona-xs);
    height: var(--sdp-icona-xs);
  }
  /* T7B-R2 · Un valor llarg s'escurça amb punts suspensius. Dins d'un
     contenidor flex el text anònim no admet text-overflow: el valor va en un
     element propi que pot encongir-se (min-width: 0) i retalla el seu text. */
  .sdp-classificacio-pindola__text {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-classificacio-pindola:hover > .sp-card-label { text-decoration: underline; }
  }
  /* L'anell de focus abraça la píndola que es veu, no l'àrea tàctil buida. */
  .sdp-classificacio-pindola:focus-visible { outline: none; }
  .sdp-classificacio-pindola:focus-visible > .sp-card-label { outline: 3px solid var(--sdp-focus); outline-offset: 2px; }

  /* T7 (P5) · L'arbre de DialegCarpeta: cada nivell, una sagnia de 1.5rem
     (fins al tercer nivell, el màxim del Workspace). */
  .sdp-classificacio-carpeta--nivell-1 { padding-inline-start: var(--sdp-space-6); }
  .sdp-classificacio-carpeta--nivell-2 { padding-inline-start: var(--sdp-space-12); }
  .sdp-bloc-icon,
  .sdp-bloc-action {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    gap: var(--sdp-space-2);
    min-width: var(--sdp-bloc-control);
    min-height: var(--sdp-bloc-control);
    border: 0;
    border-radius: var(--sdp-radi-s);
    background: transparent;
    color: var(--sdp-crom-text);
    font: inherit;
    cursor: pointer;
  }
  .sdp-bloc-icon { width: var(--sdp-bloc-control); padding: 0; }
  /* PUBLICAR · pastilla taronja, no blava.
     El blau era el de «Connectar» i els dos botons es confonien. A més, el
     Boto canònic ja reserva `varietat="accent"` (taronja) per a publicar,
     així que la barra només seguix la seua pròpia doctrina.
     Tinta: --sdp-sobre-accent damunt de --sdp-accent fa 7,12:1 (AAA) en els
     dos temes; el blanc damunt de --sdp-accio es quedava en 3,87:1.
     Majúscules i interlletrat com la resta de pastilles de barra
     (.btn-connectar, components.css § CONTROLS DE BARRA); el radi és
     l'àlies --sdp-radi-boto (tokens.css), que resol a la pastilla. */
  .sdp-bloc-action {
    padding-inline: var(--sdp-space-5);
    background: var(--sdp-accent);
    color: var(--sdp-sobre-accent);
    border-radius: var(--sdp-radi-boto);
    font-size: var(--sdp-text-meta);
    font-weight: 700;
    letter-spacing: .04em;
    text-transform: uppercase;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-bloc-icon:hover:not(:disabled) { background: var(--sdp-crom-hover); }
  }
  .sdp-bloc-icon[aria-pressed="true"] {
    background: var(--sdp-crom-actiu-fons);
    color: var(--sdp-crom-actiu-text);
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-bloc-action:hover:not(:disabled) { background: var(--sdp-accent-hover); }
  }
  [data-compact="true"] > .sdp-bloc-action,
  [data-compact="true"] .sdp-editor-tools__actions > .sdp-bloc-action {
    width: var(--sdp-bloc-control);
    padding-inline: 0;
  }
  [data-compact="true"] > .sdp-bloc-action > .sdp-bloc-action__label,
  [data-compact="true"] .sdp-editor-tools__actions > .sdp-bloc-action > .sdp-bloc-action__label {
    display: none;
  }
  .sdp-bloc-icon:disabled,
  .sdp-bloc-action:disabled { opacity: .5; cursor: default; }
  .sdp-bloc-icon:focus-visible,
  .sdp-bloc-action:focus-visible {
    outline: 2px solid var(--sdp-crom-focus);
    outline-offset: -2px;
  }

  .sdp-bloc .sdp-workspace-detail--editor { overflow: hidden; }
  .sdp-editor-shell-atomic {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
    min-width: 0;
    overflow: hidden;
  }
  .sdp-editor-document {
    flex: 1 1 0;
    min-height: 0;
    min-width: 0;
    overflow: hidden;
  }
  /* D13 · Eines davall de l'entradilla (posicioEines 'davall-entradilla'):
     l'embolcall viu dins de l'article, que està dins del contenidor de
     scroll, i s'ancora en fer scroll. El fan servir el Perfil i el Bloc de
     Notes. Al Perfil el `top` deixa lloc a la blava i la taronja, que allà
     són sticky (utilities.css, mode contingut). Qui ho adopte amb barres
     static ha de tornar el `top` a 0 en el seu àmbit, com el Bloc (davall).
     El marge negatiu anul·la el farciment lateral de l'article:
     les eines ocupen tota l'amplària de la columna, com la fila d'eines. */
  .sdp-editor-eines {
    position: sticky;
    top: calc(var(--sdp-alt-accio) * 2);
    z-index: var(--z-eines-editor);
    margin-inline: calc(var(--sdp-pad-contenidor) * -1);
    margin-block-end: var(--sdp-space-6);
  }
  /* Bloc de Notes: la blava i la taronja hi són static (utilities.css,
     `.sdp-bloc … > .bar-blue`). No hi ha res a esquivar: les eines
     s'ancoren a dalt de tot del contenidor de scroll. */
  .sdp-bloc .sdp-editor-eines { top: 0; }
  /* L'Índex salta amb desplacaASeccio (PageFrame), que respecta este
     scroll-margin-top: sense marge, el títol de destí quedaria davall de les
     eines ancorades. Les
     eines fan flex-wrap i passen d'una fila (58px) a tres (161px, columna
     de 280px): tres barres (174px) les cobrixen. Amb columnes més estretes
     (209px, 317px d'eines) no basta: caldria mesurar-les (ResizeObserver).
     Els mateixos nivells que recull l'Índex (PageFrame): de h1 a h6. */
  .sdp-bloc .sdp-editor-eines ~ * :is(h1, h2, h3, h4, h5, h6) { scroll-margin-top: calc(var(--sdp-alt-accio) * 3); }
}

/* ═══ XAT (F0 · pla 260927_0055 §4.D) ═══════════════════════════════════
   El Xat sobre AppGridShell, com el Bloc de Notes: mateixa closca, mateixes
   files de capçalera. Només tokens semàntics (bombolla pròpia --sdp-accio-
   subtil, aliena --sdp-accent-subtil, sistema --sdp-fons-subtil, meta
   --sdp-text-suau i --sdp-text-meta, marques llegit --sdp-accio-text, error
   --sdp-error-text, pastilla --sdp-accio/--sdp-sobre-accio), radi
   --sdp-radi-m, controls --sdp-touch, barres --sdp-alt-accio. Cap !important
   i un sol punt de tall: el [data-layout="estret"] de la closca.
   ═══════════════════════════════════════════════════════════════════════ */
@layer components {
  .sdp-xat .sdp-workspace-column {
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
    min-width: 0;
  }
  .sdp-xat .sdp-workspace-column__body {
    flex: 1 1 0;
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
  }
  /* Ombra separadora (T13, ordre del Mestre 260927): la columna de la llista
     projecta ombra sobre l'àrea del xat, que queda «per davall». El token
     --sdp-ombra-2 és omnidireccional: el clip-path el retalla al costat dret
     perquè no taque ni el rail ni la fila de control; el z-index fa que
     caiga damunt de la columna del xat (germana posterior). */
  .sdp-xat .app-grid-column--middle {
    position: relative;
    z-index: 1;
    background: var(--sdp-fons-targeta);
    box-shadow: var(--sdp-ombra-2);
    clip-path: inset(0 calc(var(--sdp-space-8) * -1) 0 0);
  }

  /* Rail esquerre desplegat: la mateixa graella que la barra principal
     (layout.css, .nav-item), el full de càlcul del Mestre («una graella ben
     quadrada», 260927). Files de var(--sdp-touch) a sang i sense radi, cap
     coixí lateral ni separació entre elles (Xats i Novetats fan pinya); la
     llista s'apega a la fila de títol, com el menú de la barra principal
     obert o plegat (modules.css .app-sidebar-nav, layout.css) i com la
     primera cel·la de tot rail plegat (AppGridShell.css): «Xat» i «Xats»
     cauen a la mateixa fila en els quatre estats i plegar no fa cap bot
     (ordre del Mestre, 260927 vespre: «blocs purs i durs de banda a banda,
     apegats a la capçalera»). Icona de 24 a 16px de la vora (eix
     a 28: el de la roda de «Menú», el del rail plegat i el de la barra
     principal, oberta o plegada) i text a 56 (16 + 24 + 16), on comença
     «CONTROL» a la barra principal; les files d'eixa barra queden a 57 (gap
     13 més un marge de 4 que Pedra Seca §3 no admet: deute seu, no del
     rail). Plegar i desplegar el rail no mou cap icona d'eix. El color va
     explícit, com a .sdp-workspace-groups:
     la tipografia editorial de ul/li posa --sdp-text-cos, que sobre el crom
     és el mateix gris que el fons i deixava l'entrada inactiva invisible; la
     mateixa tipografia posa sagnat i marge a li, que ací es neutralitzen
     (eren els 12px de coixí i de separació que desquadraven la graella). */
  .sdp-xat-rail-llista {
    list-style: none;
    margin: 0;
    padding: 0 0 var(--sdp-space-2);
    display: grid;
    gap: 0;
    color: var(--sdp-crom-text);
  }
  .sdp-xat-rail-llista > li { margin: 0; padding: 0; }
  .sdp-xat .sdp-xat-rail-llista .sdp-workspace-nav-item {
    min-height: var(--sdp-touch);
    gap: var(--sdp-space-4);
    padding: var(--sdp-space-2) var(--sdp-space-4);
    border-radius: 0;
  }
  /* La roda de «Menú» ocupa la mateixa cel·la que les icones de les files.
     La regla general del Workspace (.app-grid-col-header__plec > svg) li
     posa 12px de coixí a cada costat, calculats per a icones de 20, i
     AppGridColumn en pinta de 24: la caixa fa 48 i l'eix cau a 40, dotze
     píxels a la dreta de les icones del rail plegat. A la columna del rail
     el coixí és 0 i la separació amb el títol, 16, la de les files. */
  .sdp-xat .app-grid-column--left .app-grid-col-header__plec > svg { padding-inline: 0; }
  .sdp-xat .app-grid-column--left .app-grid-col-header__plec { gap: var(--sdp-space-4); }
  /* Rail plegat: al Workspace la vora i el coixí de dalt del rail separen el
     grup d'accions (roda, lupa) del de carpetes (AppGridShell.css, «un sol
     joc de regles»). Al Xat no hi ha accions: davall de la fila de «Menú» ve
     directament la primera entrada, i eixos 5px (vora 1 més coixí 4) la
     deixaven més avall que la de la barra principal plegada (layout.css,
     coixí de 4). Sense vora ni coixí, el gap de 4 de la graella fa de marge
     i la primera cel·la cau a la mateixa fila que a la barra principal. */
  .sdp-xat .app-grid-col-header--collapsed > .sdp-workspace-rail {
    border-top: 0;
    padding-top: 0;
  }

  /* Fila de títol de la llista (D5, calc de WhatsApp): una sola fila, la 1
     de la graella, amb el «+» redó de «Conversa nova» (to d'acció, com el
     botó verd de WhatsApp Desktop; radi --sdp-radi-boto, la pastilla) i, en
     estret i en mitjà, el botó que obri el rail. */
  .sdp-xat-nova {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--sdp-touch);
    height: var(--sdp-touch);
    padding: 0;
    border: 0;
    border-radius: var(--sdp-radi-boto);
    background: var(--sdp-accio);
    color: var(--sdp-sobre-accio);
    cursor: pointer;
    flex: none;
  }
  /* Hover: el blau fort, igual en clar; en fosc la icona feia 2,66:1 sobre
     el blau clar de --sdp-accio-hover i ara 9,21:1 (Q1, cap hover baixa). */
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-nova:hover { background: var(--sdp-accio-control); }
  }
  .sdp-xat-nova:focus-visible { outline: 2px solid var(--sdp-crom-focus); outline-offset: 2px; }
  .sdp-xat .sdp-xat-obri-rail { color: var(--sdp-crom-actiu-fons); }
  /* En estret i en mitjà el Xat no usa pestanyes de columna (ordre del
     Mestre, 260927 vesprada; des del MD, 261003, la closca ja no en pinta
     cap i la regla que les amagava ací s'ha retirat). Cada columna porta el
     seu control: el botó de la fila 1 obri el rail, la creu del rail el
     tanca, i la fletxa de la conversa o de l'opció torna a la llista. */
  /* La capçalera de l'opció oberta del Control del xat (fletxa d'arrere i
     títol) només té sentit en estret, on l'opció ocupa tota la pantalla; el
     títol del panell, que la repetiria, s'hi amaga. */
  .sdp-xat-capcalera--opcio { display: none; }
  .app-grid-shell[data-layout="estret"] .sdp-xat-capcalera--opcio { display: flex; }
  .app-grid-shell[data-layout="estret"] .sdp-xat-control__panell > h2 { display: none; }

  /* Cerca en píndola, sempre a la vista davall del títol (D5): fons subtil,
     sense vora visible i la lupa dins; la creu buida el terme. A la mateixa
     línia, a la dreta, la icona de filtre (T12). */
  .sdp-xat-cerca {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-2);
    flex: none;
    padding: var(--sdp-space-2) var(--sdp-space-3);
    background: var(--sdp-fons-targeta);
  }
  .sdp-xat-cerca__camp {
    display: flex;
    align-items: center;
    flex: 1 1 auto;
    min-width: 0;
    padding: 0 var(--sdp-space-1) 0 var(--sdp-space-4);
    border: 1px solid transparent;
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-suau);
  }
  .sdp-xat-cerca__etiqueta {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-3);
    flex: 1 1 auto;
    min-width: 0;
    min-height: var(--sdp-touch);
    margin: 0;
    cursor: text;
  }
  .sdp-xat-cerca__etiqueta > svg { flex: none; }
  .sdp-xat-cerca__etiqueta > input {
    flex: 1 1 auto;
    min-width: 0;
    border: 0;
    background: transparent;
    color: var(--sdp-text-cos);
    font: inherit;
    outline: none;
  }
  .sdp-xat-cerca__camp:focus-within { outline: 2px solid var(--sdp-focus); outline-offset: 1px; }
  .sdp-xat-cerca .sdp-xat-icona { color: var(--sdp-text-suau); }
  .sdp-xat-cerca__etiqueta > input::-webkit-search-cancel-button { appearance: none; }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-cerca .sdp-xat-icona:hover { background: var(--sdp-fons-targeta); }
  }
  .sdp-xat-cerca .sdp-xat-icona:focus-visible { outline-color: var(--sdp-focus); }

  /* Filtre de converses (T12, ordre del Mestre 260927): Tot · No llegits ·
     Preferits · Grups (XAT-A17) dins d'un desplegable darrere de la icona
     de filtre, a la línia de la cerca; la fila de píndoles que ocupava una
     fila de la llista ha desaparegut. La icona s'il·lumina amb el to d'acció
     quan hi ha un filtre que no és «Tot»; el menú és el mateix que el «⋯». */
  .sdp-xat-filtre { position: relative; flex: none; }
  .sdp-xat-filtre__boto { flex: none; }
  .sdp-xat-cerca .sdp-xat-filtre__boto--actiu {
    background: var(--sdp-accio-subtil);
    color: var(--sdp-accio-text);
  }
  .sdp-xat-filtre__menu { min-width: 12rem; }
  .sdp-xat-menu__buit {
    display: inline-block;
    flex: none;
    width: var(--sdp-space-5);
    height: var(--sdp-space-5);
  }

  /* Llista de converses: files de --sdp-xat-fila-mida (XAT-A09, UX-B01). */
  .sdp-xat-llista { list-style: none; margin: 0; padding: 0; }
  .sdp-xat-fila,
  .sdp-xat-opcio {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-3);
    width: 100%;
    min-height: var(--sdp-xat-fila-mida);
    padding: var(--sdp-space-2) var(--sdp-space-4);
    border: 0;
    border-bottom: 1px solid var(--sdp-vora);
    background: transparent;
    color: var(--sdp-text-cos);
    font: inherit;
    text-align: left;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-fila:hover,
    .sdp-xat-opcio:hover { background: var(--sdp-fons-subtil); }
  }
  .sdp-xat-fila[aria-current="true"],
  .sdp-xat-opcio[aria-current="true"] { background: var(--sdp-accio-subtil); }
  .sdp-xat-fila:focus-visible,
  .sdp-xat-opcio:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: -2px; }
  .sdp-xat-fila__cos {
    flex: 1 1 auto;
    min-width: 0;
    display: grid;
    gap: var(--sdp-space-1);
  }
  .sdp-xat-fila__cap,
  .sdp-xat-fila__peu {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--sdp-space-2);
    min-width: 0;
  }
  .sdp-xat-fila__nom {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 700;
    color: var(--sdp-text-titol);
  }
  .sdp-xat-fila__hora {
    flex: none;
    font-size: var(--sdp-text-meta);
    color: var(--sdp-text-suau);
    font-variant-numeric: tabular-nums;
  }
  .sdp-xat-fila--nova .sdp-xat-fila__hora { color: var(--sdp-accio-text); font-weight: 700; }
  .sdp-xat-fila__previa {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--sdp-text-suau);
  }
  /* Torn 260930 (T1, calc de WhatsApp Desktop): si l'últim missatge és teu,
     la previsualització comença amb les seues marques. Van en línia amb el
     text, no en flex, perquè l'el·lipsi continue tallant la línia sencera;
     les separa del text l'espai que posa FilaConversa. */
  .sdp-xat-fila__previa .sdp-xat-marques { vertical-align: middle; }
  .sdp-xat-fila__icones {
    display: inline-flex;
    align-items: center;
    gap: var(--sdp-space-1);
    flex: none;
    color: var(--sdp-text-suau);
  }
  /* Comptador de no llegits: número dins d'una pastilla (XAT-A10). Un fil
     marcat a mà com a no llegit i sense recompte porta la pastilla buida
     (--punt), sempre amb el seu text per al lector de pantalla (XAT-P04).
     AAA (Q1, 261004): el número blanc de 14px sobre --sdp-accio feia 3,87:1;
     sobre la superfície de control, 9,21:1 en clar i en fosc. */
  .sdp-xat-pastilla {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: var(--sdp-space-6);
    height: var(--sdp-space-6);
    padding: 0 var(--sdp-space-2);
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-accio-control);
    color: var(--sdp-sobre-accio);
    font-size: var(--sdp-text-meta);
    font-weight: 700;
    flex: none;
  }
  /* Sense número, el min-width i l'alçada de --sdp-space-6 ja en fan un
     cercle: el punt de WhatsApp, del mateix diàmetre que el comptador. */
  .sdp-xat-pastilla--punt { padding: 0; }
  /* Fil silenciat (T1): la pastilla grisa de WhatsApp, amb la parella neutra
     de .sdp-insignia--neutre (--sdp-text-cos sobre --sdp-fons-subtil: 9,50:1
     en clar i 11,51:1 en fosc). Sense número, el cercle és tota la
     informació i ha de fer 3:1 (WCAG 1.4.11): el gris de --sdp-vora-control,
     que ja ho complix sobre la targeta i sobre el hover de la fila. */
  .sdp-xat-pastilla--silenciada { background: var(--sdp-fons-subtil); color: var(--sdp-text-cos); }
  .sdp-xat-pastilla--punt.sdp-xat-pastilla--silenciada { background: var(--sdp-vora-control); }

  /* Columna dreta sense conversa: hi viu el document per defecte (ordre del
     Mestre, 260927); en obrir una conversa, només queda el xat. */
  .sdp-xat-buit {
    flex: 1 1 0;
    min-height: 0;
    overflow-y: auto;
  }
  /* En mode estret el document no hi cap: un avís sobri i centrat, amb el
     fons de la conversa perquè obrir-ne una no canvie el to de la columna. */
  .sdp-xat-buit--avis {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--sdp-space-3);
    padding: var(--sdp-space-8) var(--sdp-pad-contenidor);
    background: var(--sdp-fons-targeta);
    color: var(--sdp-text-suau);
    text-align: center;
  }
  .sdp-xat-buit__titol {
    margin: 0;
    font-size: var(--sdp-text-h6);
    font-weight: 600;
    color: var(--sdp-text-cos);
  }

  /* La conversa: fons de mapa amb la variant incrustada (:host) del fosc. */
  .sdp-xat-conversa {
    position: relative;
    z-index: 0;
    display: flex;
    flex-direction: column;
    height: 100%;
    min-height: 0;
    background: var(--sdp-fons-targeta);
  }
  .sdp-xat-conversa::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    background-image: var(--sdp-xat-fons-imatge);
    background-size: cover;
    background-position: center;
    /* 0,05 en clar i en fosc (T14, ordre del Mestre 260927): el mapa és un
       rumor de fons i les bafarades han de destacar. */
    opacity: 0.05;
    pointer-events: none;
  }
  :root[data-theme="dark"] .sdp-xat-conversa::before,
  :host([data-theme="dark"]) .sdp-xat-conversa::before {
    filter: invert(1) hue-rotate(180deg) saturate(0.5);
    opacity: 0.05;
  }

  /* Capçalera de la conversa: la fila 1 de la columna dreta, com a la resta. */
  .sdp-xat-capcalera {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-3);
    height: var(--sdp-alt-accio);
    flex: none;
    padding: 0 var(--sdp-space-4);
    background: var(--sdp-workspace-fila1-fons);
    color: var(--sdp-crom-text);
    position: relative;
    z-index: 2;
  }
  .sdp-xat-capcalera--seleccio { background: var(--sdp-workspace-fila2-fons); }
  .sdp-xat-capcalera__info {
    flex: 1 1 auto;
    min-width: 0;
    display: grid;
  }
  .sdp-xat-capcalera__nom {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 700;
  }
  .sdp-xat-capcalera__sub {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: var(--sdp-text-meta);
    color: var(--sdp-crom-text-suau);
  }
  .sdp-xat-capcalera__menu { position: relative; flex: none; }
  /* Lògica d'Usuari (T4): avatar i nom de la capçalera enllacen al perfil
     públic de l'altra part. El mateix espai que abans: cap píxel es mou. */
  .sdp-xat-capcalera__enllac {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-3);
    flex: 1 1 auto;
    min-width: 0;
    min-height: var(--sdp-touch);
    color: inherit;
    text-decoration: none;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-capcalera__enllac:hover .sdp-xat-capcalera__nom { text-decoration: underline; }
  }
  .sdp-xat-capcalera__enllac:focus-visible { outline: 2px solid var(--sdp-crom-focus); outline-offset: -2px; }

  /* Botó d'icona de --sdp-touch: capçalera, cerca i menú de bombolla. */
  .sdp-xat-icona {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--sdp-touch);
    height: var(--sdp-touch);
    padding: 0;
    border: 0;
    border-radius: var(--sdp-radi-boto);
    background: transparent;
    color: inherit;
    cursor: pointer;
    flex: none;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-icona:hover { background: var(--sdp-crom-hover); }
  }
  .sdp-xat-icona:focus-visible { outline: 2px solid var(--sdp-crom-focus); outline-offset: -2px; }
  .sdp-xat-icona:disabled { opacity: 0.5; cursor: default; }

  /* Entrada del menú (Kowalski, 261004): 180ms des de --sdp-escala-aparicio
     i l'opacitat, amb l'origen a la cantonada del disparador (dalt a la
     dreta; a l'esquerra en --esquerra i a les bombolles de l'altra part).
     El tancament és instantani: el menú es desmunta. */
  .sdp-xat-menu {
    position: absolute;
    top: calc(100% + var(--sdp-space-1));
    right: 0;
    z-index: 20;
    min-width: 14rem;
    padding: var(--sdp-space-2) 0;
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-elevat);
    color: var(--sdp-text-cos);
    box-shadow: var(--sdp-ombra-2);
    transform-origin: top right;
    animation: sdp-aparicio-menu var(--sdp-durada-rapida) var(--sdp-corba-eixida);
  }
  .sdp-xat-menu__item {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-2);
    width: 100%;
    min-height: var(--sdp-touch);
    padding: 0 var(--sdp-space-4);
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    text-align: left;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-menu__item:hover { background: var(--sdp-fons-subtil); }
  }
  .sdp-xat-menu__item:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: -2px; }

  /* La llista de missatges. */
  .sdp-xat-missatges {
    flex: 1 1 0;
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    list-style: none;
    margin: 0;
    padding: var(--sdp-space-4);
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-2);
  }
  /* Revisió adversarial 260930: la llista (tabIndex -1) rep el focus de
     «Baixa al final» en estret o sense camp (#6, #9), i cada bombolla el de
     la cita que hi porta (#12). L'anell només ix amb el teclat. */
  .sdp-xat-missatges:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: -2px; }
  .sdp-xat-missatges > .sdp-xat-item:not(.sdp-xat-item--triable):focus-visible {
    outline: 2px solid var(--sdp-focus);
    outline-offset: 2px;
    border-radius: var(--sdp-radi-s);
  }
  .sdp-xat-missatges > li {
    display: flex;
    flex-direction: column;
    min-width: 0;
  }
  .sdp-xat-item { position: relative; }
  .sdp-xat-item--meu { align-items: flex-end; }
  .sdp-xat-item--altre { align-items: flex-start; }
  .sdp-xat-sentinella { height: var(--sdp-space-1); flex: none; }
  .sdp-xat-carrega { align-items: center; }
  .sdp-xat-carrega__boto,
  .sdp-xat-bombolla__accio {
    min-height: var(--sdp-touch);
    padding: 0 var(--sdp-space-4);
    border: 1px solid var(--sdp-vora-control);
    border-radius: var(--sdp-radi-boto);
    background: var(--sdp-fons-elevat);
    color: var(--sdp-accio-text);
    font: inherit;
    font-weight: 600;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-carrega__boto:hover:not(:disabled),
    .sdp-xat-bombolla__accio:hover { background: var(--sdp-fons-subtil); }
  }
  .sdp-xat-carrega__boto:disabled { opacity: 0.6; cursor: default; }
  .sdp-xat-carrega__boto:focus-visible,
  .sdp-xat-bombolla__accio:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: 2px; }
  .sdp-xat-dia { align-items: center; padding: var(--sdp-space-2) 0; }
  .sdp-xat-dia__pastilla {
    padding: var(--sdp-space-1) var(--sdp-space-3);
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
    font-weight: 600;
    box-shadow: var(--sdp-ombra-1);
  }
  .sdp-xat-sistema { align-items: center; }
  .sdp-xat-sistema__text {
    max-width: var(--sdp-xat-bombolla-max);
    padding: var(--sdp-space-2) var(--sdp-space-3);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
    text-align: center;
  }
  .sdp-xat-conversa-buida {
    align-items: center;
    padding: var(--sdp-space-8) var(--sdp-space-4);
    color: var(--sdp-text-suau);
    text-align: center;
  }

  /* Bombolles (UX-A07, UX-B02). */
  .sdp-xat-bombolla-wrap {
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: var(--sdp-space-1);
    max-width: var(--sdp-xat-bombolla-max);
    min-width: 0;
  }
  .sdp-xat-item--meu .sdp-xat-bombolla-wrap { flex-direction: row-reverse; }
  /* Bafarada (T14, ordre del Mestre 260927): sense filet d'1px; el volum el
     dona l'ombra xicoteta del token --sdp-ombra-2, i el text va en 600 perquè
     tinga cos damunt del mapa. L'error i la tria es marquen amb un anell
     d'ombra, no amb vora.
     Torn 260930 (T1): la mateixa ombra del token va per filter:
     drop-shadow() i no per box-shadow, perquè també faça el contorn de la
     cua (::before); box-shadow no la veuria i, en clar, la cua es perdria
     sobre el fons. Els anells de l'error i de la tria continuen sent
     box-shadow, i l'ombra els envolta a ells també. No és cap ombra nova. */
  .sdp-xat-bombolla {
    min-width: 0;
    padding: var(--sdp-space-2) var(--sdp-space-3);
    border: 0;
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-elevat);
    color: var(--sdp-text-cos);
    filter: drop-shadow(var(--sdp-ombra-2));
    overflow-wrap: anywhere;
  }
  .sdp-xat-bombolla--meu { background: var(--sdp-accio-subtil); }
  .sdp-xat-bombolla--altre { background: var(--sdp-accent-subtil); }
  /* La cua (torn 260930, T1 · WhatsApp Desktop): el triangle de la cantonada
     de dalt, al costat de l'autor, només a la primera bombolla de cada grup
     (Conversa, conversa.js anotaGrups); eixa cantonada es queda recta. És un
     pseudoelement amb el fons heretat de la bombolla (background: inherit):
     cap color propi, i canvia amb el tema i amb la variant. Les següents del
     grup, sense cua, porten les quatre cantonades rodones. */
  .sdp-xat-bombolla--cua { position: relative; }
  .sdp-xat-bombolla--cua::before {
    content: '';
    position: absolute;
    top: 0;
    width: var(--sdp-space-2);
    height: var(--sdp-space-3);
    background: inherit;
    pointer-events: none;
  }
  .sdp-xat-bombolla--meu.sdp-xat-bombolla--cua { border-start-end-radius: 0; }
  .sdp-xat-bombolla--meu.sdp-xat-bombolla--cua::before { left: 100%; clip-path: polygon(0 0, 100% 0, 0 100%); }
  .sdp-xat-bombolla--altre.sdp-xat-bombolla--cua { border-start-start-radius: 0; }
  .sdp-xat-bombolla--altre.sdp-xat-bombolla--cua::before { right: 100%; clip-path: polygon(0 0, 100% 0, 100% 100%); }
  .sdp-xat-bombolla--error { box-shadow: 0 0 0 2px var(--sdp-error); }
  .sdp-xat-bombolla__autor {
    display: block;
    margin-bottom: var(--sdp-space-1);
    font-size: var(--sdp-text-meta);
    font-weight: 700;
    color: var(--sdp-accent-text);
  }
  /* El nom de l'autor també és un enllaç al seu perfil (T4). */
  a.sdp-xat-bombolla__autor { text-decoration: none; }
  @media (hover: hover) and (pointer: fine) {
    a.sdp-xat-bombolla__autor:hover { text-decoration: underline; }
  }
  a.sdp-xat-bombolla__autor:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: 2px; }
  .sdp-xat-bombolla__text { margin: 0; white-space: pre-wrap; font-weight: 600; }
  .sdp-xat-bombolla__text--esborrat { font-style: italic; color: var(--sdp-text-suau); }
  .sdp-xat-bombolla__meta {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: var(--sdp-space-1);
    margin-top: var(--sdp-space-1);
    font-size: var(--sdp-text-meta);
    color: var(--sdp-text-suau);
    font-variant-numeric: tabular-nums;
  }
  .sdp-xat-marques { display: inline-flex; align-items: center; color: var(--sdp-text-suau); }
  .sdp-xat-marques--pendent,
  .sdp-xat-marques--enviat { color: var(--sdp-text-suau); }
  .sdp-xat-marques--llegit { color: var(--sdp-accio-text); }
  .sdp-xat-marques--error { color: var(--sdp-error-text); }
  .sdp-xat-bombolla__error {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--sdp-space-2);
    margin-top: var(--sdp-space-2);
    padding-top: var(--sdp-space-2);
    border-top: 1px solid var(--sdp-vora);
    color: var(--sdp-error-text);
    font-size: var(--sdp-text-meta);
  }
  .sdp-xat-bombolla__error > svg { flex: none; }
  .sdp-xat-enllac { color: var(--sdp-accio-text); text-decoration: underline; }
  .sdp-xat-enllac__avis {
    display: inline-flex;
    align-items: center;
    gap: var(--sdp-space-1);
    margin-inline-start: var(--sdp-space-1);
    color: var(--sdp-error-text);
    font-size: var(--sdp-text-meta);
  }
  /* El «⋯» de la bombolla ix en passar per damunt o amb el focus; als
     dispositius sense ratolí és sempre visible. */
  .sdp-xat-bombolla__accions {
    position: relative;
    flex: none;
    opacity: 0;
    transition: opacity var(--sdp-t);
  }
  .sdp-xat-bombolla-wrap:hover .sdp-xat-bombolla__accions,
  .sdp-xat-bombolla-wrap:focus-within .sdp-xat-bombolla__accions,
  .sdp-xat-bombolla__accions--obert { opacity: 1; }
  @media (hover: none) {
    .sdp-xat-bombolla__accions { opacity: 1; }
  }
  .sdp-xat-bombolla__accions .sdp-xat-icona { color: var(--sdp-text-suau); }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-bombolla__accions .sdp-xat-icona:hover { background: var(--sdp-fons-subtil); }
  }
  .sdp-xat-bombolla__accions .sdp-xat-icona:focus-visible { outline-color: var(--sdp-focus); }
  .sdp-xat-item--altre .sdp-xat-menu { right: auto; left: 0; transform-origin: top left; }

  /* Grups (torn 260930, T1): entre dos files la llista posa el gap (8px)
     més el marge editorial de cada li (--sdp-li-gap, base.css); dins d'una
     tirada del mateix autor les bombolles queden a 4px. */
  .sdp-xat-missatges > .sdp-xat-item--segueix { margin-top: calc((var(--sdp-li-gap) + var(--sdp-space-1)) * -1); }
  /* El missatge on porta una cita s'il·lumina un moment (MS_RESSALT de
     conversa.js, 1,6 s) amb la tinta de l'anell d'acció, a tota l'amplada
     de la fila com a WhatsApp. Amb menys moviment, sense animació: la tinta
     fixa mentre dura la classe. */
  .sdp-xat-missatges > .sdp-xat-item--ressaltat { animation: sdp-xat-ressalt 1.6s ease-out; }
  @media (prefers-reduced-motion: reduce) {
    .sdp-xat-missatges > .sdp-xat-item--ressaltat { animation: none; background-color: var(--sdp-anell-accio); }
  }
  @keyframes sdp-xat-ressalt {
    0%, 50% { background-color: var(--sdp-anell-accio); }
    100% { background-color: transparent; }
  }

  /* Cita dins de la bombolla (torn 260930, T1): qui va escriure l'original
     i dos línies del seu text, amb la vora d'acció a l'inici com a WhatsApp.
     És un botó (porta a l'original) de --sdp-touch com a mínim; si
     l'original no s'ha carregat, o en mode de selecció, un bloc sense acció. */
  .sdp-xat-cita {
    display: grid;
    align-content: center;
    box-sizing: border-box;
    width: 100%;
    min-height: var(--sdp-touch);
    margin: 0 0 var(--sdp-space-1);
    padding: var(--sdp-space-1) var(--sdp-space-2);
    border: 0;
    border-inline-start: 4px solid var(--sdp-accio);
    border-radius: var(--sdp-radi-s);
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-suau);
    font: inherit;
    font-size: var(--sdp-text-meta);
    text-align: start;
  }
  button.sdp-xat-cita { cursor: pointer; }
  @media (hover: hover) and (pointer: fine) {
    button.sdp-xat-cita:hover .sdp-xat-cita__autor { text-decoration: underline; }
  }
  button.sdp-xat-cita:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: 2px; }
  .sdp-xat-cita__autor {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 700;
    color: var(--sdp-accio-text);
  }
  .sdp-xat-cita__text {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    overflow: hidden;
    overflow-wrap: anywhere;
  }
  .sdp-xat-cita--absent { border-inline-start-color: var(--sdp-vora-control); font-style: italic; }

  /* «N missatges no llegits» (torn 260930, T1): la franja de WhatsApp, a
     l'amplada de la llista, amb la pastilla al mig. Es calcula en obrir la
     conversa i no es mou mentre està oberta. */
  .sdp-xat-no-llegits {
    align-items: center;
    padding: var(--sdp-space-1) 0;
    border-radius: var(--sdp-radi-s);
    background: var(--sdp-fons-subtil);
  }
  .sdp-xat-no-llegits__pastilla {
    padding: var(--sdp-space-1) var(--sdp-space-3);
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-fons-elevat);
    color: var(--sdp-text-cos);
    font-size: var(--sdp-text-meta);
    font-weight: 600;
  }

  /* «Baixa al final» (torn 260930, T1): el botó redó de WhatsApp, a la
     cantonada de baix a la dreta de la llista i damunt del compositor.
     L'àncora no ocupa lloc (alçada 0) i el botó hi flota; l'ombra és la
     funcional dels elements flotants (--sdp-ombra-2, la del menú), no
     decoració. La pastilla diu quants missatges han arribat mentrestant: el
     recompte és text de 14 px (no gran) i va sobre --sdp-accio-control, 9,21:1
     amb blanc en clar i en fosc; --sdp-accio en fa 3,87 (revisió adversarial
     260930, #10). */
  .sdp-xat-baixa {
    position: relative;
    z-index: 2;
    flex: none;
    height: 0;
  }
  .sdp-xat-baixa__boto {
    position: absolute;
    right: var(--sdp-space-4);
    bottom: var(--sdp-space-4);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--sdp-touch);
    height: var(--sdp-touch);
    padding: 0;
    border: 0;
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-fons-elevat);
    color: var(--sdp-text-suau);
    box-shadow: var(--sdp-ombra-2);
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-baixa__boto:hover { background: var(--sdp-fons-subtil); }
  }
  .sdp-xat-baixa__boto:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: 2px; }
  .sdp-xat-baixa__pastilla {
    position: absolute;
    top: calc(var(--sdp-space-1) * -1);
    right: calc(var(--sdp-space-1) * -1);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: var(--sdp-space-5);
    height: var(--sdp-space-5);
    padding: 0 var(--sdp-space-1);
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-accio-control);
    color: var(--sdp-sobre-accio);
    font-size: var(--sdp-text-meta);
    font-weight: 700;
    line-height: 1;
  }

  /* Mode de selecció (Retall cap a Notes): la bombolla és una casella; es
     marca amb vora i icona, mai només amb el color del fons. */
  .sdp-xat-item--triable { cursor: pointer; }
  .sdp-xat-item--triable:focus-visible {
    outline: 3px solid var(--sdp-accio);
    outline-offset: 2px;
    border-radius: var(--sdp-radi-s);
  }
  .sdp-xat-item--triat .sdp-xat-bombolla {
    box-shadow: 0 0 0 2px var(--sdp-accio);
  }
  .sdp-xat-marca-tria {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--sdp-touch);
    height: var(--sdp-touch);
    flex: none;
    color: var(--sdp-text-suau);
  }
  .sdp-xat-item--triat .sdp-xat-marca-tria { color: var(--sdp-accio-text); }

  /* Compositor (XAT-B01, XAT-B03): creix fins a 6 línies amb CSS pur. */
  .sdp-xat-compositor {
    display: flex;
    align-items: flex-end;
    gap: var(--sdp-space-2);
    flex: none;
    min-height: var(--sdp-alt-accio);
    padding: var(--sdp-space-2) var(--sdp-space-4);
    background: var(--sdp-fons-subtil);
    border-top: 1px solid var(--sdp-vora);
    position: relative;
    z-index: 1;
  }
  .sdp-xat-compositor__camp {
    position: relative;
    flex: 1 1 auto;
    min-width: 0;
    display: grid;
    border: 1px solid var(--sdp-vora-control);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-elevat);
  }
  .sdp-xat-compositor__camp::after {
    content: attr(data-valor) " ";
    visibility: hidden;
    pointer-events: none;
  }
  .sdp-xat-compositor__camp::after,
  .sdp-xat-compositor__textarea {
    grid-area: 1 / 1 / 2 / 2;
    box-sizing: border-box;
    width: 100%;
    min-height: var(--sdp-touch);
    max-height: calc(1.5em * 6 + var(--sdp-space-2) * 2);
    padding: var(--sdp-space-2) var(--sdp-space-3);
    font: inherit;
    line-height: 1.5;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    overflow-y: auto;
  }
  .sdp-xat-compositor__textarea {
    resize: none;
    border: 0;
    background: transparent;
    color: var(--sdp-text-cos);
    outline: none;
  }
  .sdp-xat-compositor__camp:focus-within { outline: 2px solid var(--sdp-focus); outline-offset: 1px; }
  .sdp-xat-compositor__comptador {
    position: absolute;
    right: var(--sdp-space-3);
    bottom: calc(100% + var(--sdp-space-1));
    font-size: var(--sdp-text-meta);
    color: var(--sdp-text-suau);
    font-variant-numeric: tabular-nums;
  }
  .sdp-xat-compositor__comptador--limit { color: var(--sdp-error-text); font-weight: 700; }
  .sdp-xat-compositor__envia {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--sdp-touch);
    height: var(--sdp-touch);
    flex: none;
    padding: 0;
    border: 0;
    border-radius: var(--sdp-radi-boto);
    background: var(--sdp-accio);
    color: var(--sdp-sobre-accio);
    cursor: pointer;
  }
  /* Hover en blau fort: igual en clar; en fosc, 9,21:1 (abans 2,66:1). */
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-compositor__envia:hover:not(:disabled) { background: var(--sdp-accio-control); }
  }
  .sdp-xat-compositor__envia:disabled { opacity: 0.5; cursor: default; }
  .sdp-xat-compositor__envia:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: 2px; }
  .sdp-xat-compositor--seleccio { align-items: center; justify-content: center; }
  /* Barra de resposta (torn 260930, T1): dins del peu del compositor, just
     damunt del camp, amb el mateix fons; la cita porta la vora d'acció a
     l'inici i la ✕ la cancel·la. El compositor de davall no repetix el filet. */
  .sdp-xat-resposta {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    gap: var(--sdp-space-2);
    flex: none;
    padding: var(--sdp-space-2) var(--sdp-space-4) 0;
    border-top: 1px solid var(--sdp-vora);
    background: var(--sdp-fons-subtil);
  }
  .sdp-xat-resposta + .sdp-xat-compositor { border-top: 0; }
  /* Amb la barra damunt, el comptador (text-meta × 1,5 d'alt, a space-1 del
     camp) es pintaria damunt de la cita: el coixí de dalt hi afig la seua
     alçada i el comptador queda dins del compositor (revisió adversarial
     260930, #13). Sense barra, res no canvia. */
  .sdp-xat-resposta + .sdp-xat-compositor--comptador { padding-top: calc(var(--sdp-space-2) + var(--sdp-text-meta) * 1.5); }
  .sdp-xat-resposta__cita {
    flex: 1 1 auto;
    min-width: 0;
    display: grid;
    padding: var(--sdp-space-2) var(--sdp-space-3);
    border-inline-start: 4px solid var(--sdp-accio);
    border-radius: var(--sdp-radi-s);
    background: var(--sdp-fons-elevat);
    font-size: var(--sdp-text-meta);
  }
  .sdp-xat-resposta__autor,
  .sdp-xat-resposta__text {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .sdp-xat-resposta__autor { font-weight: 700; color: var(--sdp-accio-text); }
  .sdp-xat-resposta__text { color: var(--sdp-text-suau); }
  .sdp-xat-resposta .sdp-xat-icona { color: var(--sdp-text-suau); }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-resposta .sdp-xat-icona:hover { background: var(--sdp-fons-elevat); }
  }
  .sdp-xat-resposta .sdp-xat-icona:focus-visible { outline-color: var(--sdp-focus); }
  .sdp-xat-accio-bloc {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--sdp-space-2);
    flex: 1 1 auto;
    min-height: var(--sdp-touch);
    padding: 0 var(--sdp-space-4);
    border: 1px solid var(--sdp-vora-control);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-elevat);
    color: var(--sdp-text-cos);
    font: inherit;
    font-weight: 600;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-accio-bloc:hover:not(:disabled) { background: var(--sdp-fons-superficie); }
  }
  .sdp-xat-accio-bloc:disabled { opacity: 0.5; cursor: default; }
  .sdp-xat-accio-bloc:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: 2px; }

  /* Control del xat: opcions al centre, detall a la dreta. */
  .sdp-xat-opcio__icona {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--sdp-touch);
    height: var(--sdp-touch);
    flex: none;
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-accio-subtil);
    color: var(--sdp-accio-text);
  }
  .sdp-xat-opcio__cos { display: grid; gap: var(--sdp-space-1); min-width: 0; }
  .sdp-xat-opcio__titol { font-weight: 700; color: var(--sdp-text-titol); }
  .sdp-xat-opcio__text { color: var(--sdp-text-suau); font-size: var(--sdp-text-meta); }
  .sdp-xat-control {
    flex: 1 1 0;
    min-height: 0;
    overflow-y: auto;
    padding: var(--sdp-space-6) var(--sdp-pad-contenidor);
  }
  .sdp-xat-control__panell {
    max-width: var(--sdp-measure);
    margin: 0 auto;
    display: grid;
    gap: var(--sdp-space-4);
  }
  .sdp-xat-control__panell > h2,
  .sdp-xat-control__panell > p { margin: 0; }
  .sdp-xat-control__avis {
    padding: var(--sdp-space-3) var(--sdp-space-4);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-avis-fons);
    color: var(--sdp-avis-text);
  }
  .sdp-xat-control__opcions { display: flex; flex-wrap: wrap; gap: var(--sdp-space-2); }
  .sdp-xat-control__estat { color: var(--sdp-text-suau); font-size: var(--sdp-text-meta); }

  /* Mode estret: l'únic punt de tall és el de la closca. */
  .app-grid-shell[data-layout="estret"] .sdp-xat-bombolla-wrap { max-width: 90%; }
  .app-grid-shell[data-layout="estret"] .sdp-xat-missatges { padding: var(--sdp-space-3); }
  /* La barra mòbil flotant (nav.mobile-nav) tapava el compositor i l'última fila de la llista (UX-A05): es reserva la seua alçada, com fa .app-main__content a layout.css.
     Torn 260930: la reserva va amb la mateixa condició que mostra la barra
     (.sdp-root.is-compact, l'arrel ≤ 1023 px, App.jsx; C1-2 de l'auditoria
     2145), no amb la closca estreta (< 720 px): entre 720 i 1023 px, i en
     una caixa incrustada així, la barra tapava el compositor. :where() pesa 0
     i .app-grid-shell conserva l'especificitat de la regla d'abans. */
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-conversa,
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-llista {
    padding-bottom: calc(var(--sdp-alt-nav-mobil) + env(safe-area-inset-bottom, 0px));
  }
}

/* ═══ XAT · ONADA 3 (T63.2, T67, T68, T69) ═══════════════════════════════
   La columna de llista calcada de WhatsApp Desktop (captures del Mestre,
   260928): el «…» rodó de la fila de títol, la selecció de xats, el diàleg
   «Nova conversa», la cerca global amb la llista vertical de filtres, les
   files de comunitat (avatar quadrat amb targetes apilades) i la fitxa de
   comunitat. El verd de WhatsApp no es copia: l'acció és --sdp-accio (blau,
   text i icona --sdp-sobre-accio) i les capçaleres, crom fosc. Només tokens
   semàntics, radis per token, espais de 0.25rem i zona tàctil --sdp-touch.
   ═══════════════════════════════════════════════════════════════════════ */
@layer components {
  /* El «…» rodó de la fila de títol (captura 19.12.18) i el seu menú, ancorat
     a l'esquerra perquè el botó hi és. Sobre el crom fosc: fons de realç i
     icona clara, com el «+» però sense competir amb l'acció principal. */
  .sdp-xat-menu-llista { position: relative; flex: none; }
  .sdp-xat-mes {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--sdp-touch);
    height: var(--sdp-touch);
    padding: 0;
    border: 0;
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-crom-realc);
    color: var(--sdp-crom-text);
    cursor: pointer;
    flex: none;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-mes:hover { background: var(--sdp-crom-hover); }
  }
  .sdp-xat-mes:focus-visible { outline: 2px solid var(--sdp-crom-focus); outline-offset: 2px; }
  .sdp-xat-menu--esquerra { right: auto; left: 0; transform-origin: top left; }

  /* BarraSeleccio (T68): el recompte a la fila del títol i una sola acció. */
  .sdp-xat-barra-seleccio__recompte { font-variant-numeric: tabular-nums; }
  .sdp-xat-barra-seleccio__accio {
    display: inline-flex;
    align-items: center;
    min-height: var(--sdp-touch);
    padding: 0 var(--sdp-space-3);
    border: 0;
    border-radius: var(--sdp-radi-pastilla);
    background: transparent;
    color: var(--sdp-crom-text);
    font: inherit;
    font-weight: 700;
    cursor: pointer;
    flex: none;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-barra-seleccio__accio:hover:not(:disabled) { background: var(--sdp-crom-hover); }
  }
  .sdp-xat-barra-seleccio__accio:disabled { opacity: 0.5; cursor: default; }
  .sdp-xat-barra-seleccio__accio:focus-visible { outline: 2px solid var(--sdp-crom-focus); outline-offset: -2px; }

  /* Files en mode de selecció: el cercle a l'esquerra, ple quan està triada. */
  .sdp-xat-fila__tria {
    display: inline-flex;
    flex: none;
    color: var(--sdp-text-suau);
  }
  .sdp-xat-fila--triable[aria-checked="true"] { background: var(--sdp-accio-subtil); }
  .sdp-xat-fila--triable[aria-checked="true"] .sdp-xat-fila__tria { color: var(--sdp-accio-text); }

  /* Avatars sense imatge d'un grup (persones o bafarada) i d'un canal (megàfon). */
  .sdp-xat-avatar-icona {
    display: inline-grid;
    place-items: center;
    width: var(--sdp-touch);
    height: var(--sdp-touch);
    flex: none;
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-suau);
  }
  /* A la capçalera de la conversa, la mida de l'avatar 'sm' (32px). */
  .sdp-xat-avatar-icona--sm { width: var(--sdp-space-8); height: var(--sdp-space-8); }

  /* Comunitat (T67, captura 19.11.50): avatar QUADRAT i dos targetes apilades
     darrere, desplaçades a l'esquerra. Vores i fons, cap ombra decorativa.
     L'avatar s'alinea amb els de la resta de files: les targetes sobreïxen
     cap al coixí de la fila (1rem) o, en selecció, cap al gap del cercle. */
  .sdp-xat-apilat {
    position: relative;
    display: inline-grid;
    flex: none;
    isolation: isolate;
  }
  .sdp-xat-apilat::before,
  .sdp-xat-apilat::after {
    content: '';
    position: absolute;
    inset: var(--sdp-space-1) 0;
    z-index: -1;
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-s);
    background: var(--sdp-fons-subtil);
  }
  /* transform i no `translate`: la propietat solta arriba a Chrome 104 i el
     Baseline és Chrome 100. */
  .sdp-xat-apilat::before { inset: var(--sdp-space-2) 0; transform: translateX(calc(var(--sdp-space-2) * -1)); }
  .sdp-xat-apilat::after { transform: translateX(calc(var(--sdp-space-1) * -1)); }
  .sdp-xat-avatar--quadrat,
  .sdp-xat-avatar--quadrat .sdp-avatar__imatge { border-radius: var(--sdp-radi-s); }
  .sdp-xat-fila--comunitat .sdp-xat-fila__nom { font-weight: 800; }
  .sdp-xat-fila__xebro { flex: none; color: var(--sdp-text-suau); }

  /* Cerca global (T69): el filtre triat és una fitxa dins del camp. El botó
     fa --sdp-touch d'alt; la píndola de dins és el que es veu. */
  .sdp-xat-cerca__camp--actiu { background: var(--sdp-fons-targeta); border-color: var(--sdp-vora-control); }
  .sdp-xat-fitxa {
    display: inline-flex;
    align-items: center;
    flex: none;
    min-height: var(--sdp-touch);
    padding: 0;
    margin-inline-end: var(--sdp-space-2);
    border: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    cursor: pointer;
  }
  .sdp-xat-fitxa__pastilla {
    display: inline-flex;
    align-items: center;
    gap: var(--sdp-space-1);
    padding: var(--sdp-space-1) var(--sdp-space-2);
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-accio-subtil);
    color: var(--sdp-accio-text);
    font-size: var(--sdp-text-meta);
    font-weight: 700;
  }
  .sdp-xat-fitxa:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: 2px; }

  /* La llista vertical de filtres (captura 19.13.56): icona de contorn en to
     d'acció, etiqueta i la fletxa diagonal a la dreta. Sense capçalera. */
  .sdp-xat-filtres-cerca { list-style: none; margin: 0; padding: var(--sdp-space-2) 0; }
  .sdp-xat-filtres-cerca > li,
  .sdp-xat-targeta > li { margin: 0; padding: 0; }
  .sdp-xat-filtres-cerca__fila {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-4);
    width: 100%;
    min-height: var(--sdp-touch);
    padding: var(--sdp-space-2) var(--sdp-space-4);
    border: 0;
    background: transparent;
    color: var(--sdp-text-cos);
    font: inherit;
    text-align: left;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-filtres-cerca__fila:hover { background: var(--sdp-fons-subtil); }
  }
  .sdp-xat-filtres-cerca__fila:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: -2px; }
  .sdp-xat-filtres-cerca__icona { display: inline-flex; flex: none; color: var(--sdp-accio-text); }
  .sdp-xat-filtres-cerca__nom { flex: 1 1 auto; min-width: 0; }
  .sdp-xat-filtres-cerca__fletxa { flex: none; color: var(--sdp-text-suau); }

  /* Resultats de la cerca: grups amb el seu títol, fragments ressaltats i
     l'avís de l'abast al peu. */
  .sdp-xat-seccio { margin: 0; }
  .sdp-xat-seccio__titol {
    margin: 0;
    padding: var(--sdp-space-4) var(--sdp-space-4) var(--sdp-space-2);
    border: 0;
    font-size: var(--sdp-text-meta);
    font-weight: 700;
    line-height: 1.2;
    color: var(--sdp-text-suau);
    text-align: left;
  }
  .sdp-xat-marca {
    padding: 0;
    border-radius: var(--sdp-radi-s);
    background: var(--sdp-accio-subtil);
    color: inherit;
    font-weight: 700;
  }
  .sdp-xat-resultats__avis {
    margin: 0;
    padding: var(--sdp-space-3) var(--sdp-space-4);
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
  }

  /* Fitxa de comunitat (captures 19.42.54 i 19.43.00): capçalera en banda
     subtil, files, el text d'estat buit al peu i «+ Afegir grup» a tota
     l'amplària, apegat a baix. */
  .sdp-xat-fitxa-comunitat {
    display: flex;
    flex-direction: column;
    min-height: 100%;
  }
  .sdp-xat-fitxa-comunitat__cap {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-3);
    padding: var(--sdp-space-4);
    background: var(--sdp-fons-subtil);
  }
  .sdp-xat-fitxa-comunitat__identitat { display: grid; min-width: 0; }
  .sdp-xat-fitxa-comunitat__nom {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: var(--sdp-text-h6);
    font-weight: 800;
    color: var(--sdp-text-titol);
  }
  .sdp-xat-fitxa-comunitat__tipus { font-size: var(--sdp-text-meta); color: var(--sdp-text-suau); }
  .sdp-xat-fitxa-comunitat__cos { display: flex; flex-direction: column; flex: 1 1 auto; }
  .sdp-xat-fitxa-comunitat__buit {
    margin: auto 0 0;
    padding: var(--sdp-space-8) var(--sdp-space-4) var(--sdp-space-4);
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
    text-align: center;
  }
  .sdp-xat-fitxa-comunitat__peu {
    position: sticky;
    bottom: 0;
    padding: var(--sdp-space-3) var(--sdp-space-4);
    background: var(--sdp-fons-targeta);
  }

  /* Píndola d'acció a tota l'amplària: fons blau, text i icona blancs.
     AAA (Q1, 261004): el parell de .sdp-boto--primari, 9,21:1 en repòs i
     7,20:1 en hover, en clar i en fosc (abans 3,87:1, i 2,66:1 en hover fosc). */
  .sdp-xat-pindola {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--sdp-space-2);
    width: 100%;
    min-height: var(--sdp-touch);
    padding: 0 var(--sdp-space-4);
    border: 1px solid transparent;
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-accio-control);
    color: var(--sdp-sobre-accio);
    font: inherit;
    font-weight: 700;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-pindola:hover { background: var(--sdp-accio-control-hover); }
  }
  .sdp-xat-pindola:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: 2px; }
  .sdp-xat-pindola--secundaria {
    border-color: var(--sdp-vora-control);
    background: transparent;
    color: var(--sdp-accio-text);
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-pindola--secundaria:hover { background: var(--sdp-fons-subtil); }
  }

  /* El diàleg «Nova conversa» (captura 19.12.49): títol centrat, creu
     rodona, fons subtil i targetes blanques (la d'accions, la de cada
     secció). Sobre el Dialeg de Pedra Seca. */
  .sdp-xat-dialeg { background: var(--sdp-fons-app); }
  .sdp-xat-dialeg .sdp-dialeg__titol { flex: 1 1 auto; padding-inline-start: var(--sdp-touch); text-align: center; }
  .sdp-xat-dialeg .sdp-dialeg__tanca { border-radius: var(--sdp-radi-pastilla); background: var(--sdp-fons-targeta); }
  .sdp-xat-dialeg .sdp-dialeg__cos { padding: var(--sdp-space-2) var(--sdp-space-4) var(--sdp-space-4); }
  .sdp-xat-dialeg__cos { display: grid; gap: var(--sdp-space-2); }
  .sdp-xat-dialeg__cerca { background: var(--sdp-fons-targeta); border-color: var(--sdp-vora-control); }
  /* Un sol contorn de focus, dins del camp: no se suma a la vora ni es retalla. */
  .sdp-xat-dialeg__cerca:focus-within { border-color: transparent; outline-offset: -2px; }
  .sdp-xat-targeta {
    overflow: hidden;
    margin: 0;
    padding: 0;
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
  }
  .sdp-xat-targeta .sdp-xat-fila:last-child,
  .sdp-xat-targeta > li:last-child .sdp-xat-fila { border-bottom: 0; }
  .sdp-xat-opcio-accio {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-4);
    width: 100%;
    min-height: var(--sdp-touch);
    padding: var(--sdp-space-2) var(--sdp-space-4);
    border: 0;
    border-bottom: 1px solid var(--sdp-vora);
    background: transparent;
    color: var(--sdp-text-cos);
    font: inherit;
    text-align: left;
    cursor: pointer;
  }
  .sdp-xat-opcio-accio > svg { flex: none; color: var(--sdp-accio-text); }
  .sdp-xat-targeta > li:last-child .sdp-xat-opcio-accio { border-bottom: 0; }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-opcio-accio:hover { background: var(--sdp-fons-subtil); }
  }
  .sdp-xat-opcio-accio:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: -2px; }
  .sdp-xat-dialeg__panell {
    display: grid;
    gap: var(--sdp-space-4);
    padding: var(--sdp-space-4);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
    color: var(--sdp-text-cos);
  }
  .sdp-xat-dialeg__panell > p { margin: 0; max-width: var(--sdp-measure); }
  .sdp-xat-dialeg__panell:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: 2px; }
  .sdp-xat-dialeg__accions { display: grid; gap: var(--sdp-space-2); }
  .sdp-xat-avis {
    margin: 0;
    padding: var(--sdp-space-2) var(--sdp-space-4);
    background: var(--sdp-avis-fons);
    color: var(--sdp-avis-text);
    font-size: var(--sdp-text-meta);
  }

  /* Conversa de pàgina (T63.2): «Sobre: …» dins de l'enllaç de la capçalera
     (avatar, nom i línia: .sdp-xat-capcalera__enllac, de --sdp-touch d'alt,
     Pedra Seca §6), l'avís del xat públic damunt del compositor i, als
     Avisos, l'avís en lloc del compositor per a qui no n'és administrador. */
  .sdp-xat-capcalera__sobre { color: inherit; }
  .sdp-xat-capcalera__enllac .sdp-xat-capcalera__sobre { text-decoration: underline; }
  .sdp-xat-avis-public {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-2);
    flex: none;
    margin: 0;
    padding: var(--sdp-space-2) var(--sdp-space-4);
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
    position: relative;
    z-index: 1;
  }
  .sdp-xat-compositor--avis {
    align-items: center;
    justify-content: center;
    margin: 0;
    color: var(--sdp-text-suau);
    text-align: center;
  }

  /* Amb la barra mòbil a la vista (.sdp-root.is-compact; torn 260930, com la
     reserva del bloc F0): la barra flotant no ha de tapar res de l'onada. La
     reserva va al contenidor; les llistes de dins (grups de resultats, fitxa
     i diàleg) no la repetixen, com sí que fa la llista de converses. */
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-filtres-cerca,
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-resultats,
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-fitxa-comunitat__peu {
    padding-bottom: calc(var(--sdp-alt-nav-mobil) + env(safe-area-inset-bottom, 0px));
  }
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-resultats .sdp-xat-llista,
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-fitxa-comunitat .sdp-xat-llista,
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-dialeg .sdp-xat-llista { padding-bottom: 0; }
}

/* ═══ XAT · ONADA 3B (rail, vistes i catàleg) ═══════════════════════════════
   El rail calcat del menú de WhatsApp per a Mac (captura 19.11.50): les
   seccions plegables «Més» i «Comunitats» i el peu fix amb l'avatar propi,
   «Tu» i el llapis; les vistes de la columna central (Comunitats i les tres
   «En construcció») i els marcs dels espècimens del catàleg. La graella del
   rail no es toca: files de var(--sdp-touch) a sang i sense radi, icones i
   avatars de 24 sobre l'eix de 28 (16 de coixí més 12). Crom fosc al rail;
   tokens semàntics a la columna central. Cap ombra nova.
   ═══════════════════════════════════════════════════════════════════════ */
@layer components {
  /* Capçalera d'una secció plegable del rail desplegat: una fila de la
     graella (44 a sang, sense radi) amb el nom en to suau i el xebró a la
     dreta, que gira quan la secció està plegada. Eix dret (captura 19.11.50):
     el xebró va centrat en una cel·la de var(--sdp-touch) i la fila acaba
     amb var(--sdp-space-2) de coixí, igual que el llapis del peu (un
     .sdp-xat-icona de var(--sdp-touch) amb el mateix coixí): els dos centres
     cauen a 8 + 22 = 30px de la vora dreta. Amb el xebró de 24 a 16px de
     coixí queia a 28, i cap coixí múltiple de 4 igualava els 2px. */
  .sdp-xat-rail-seccio { margin: 0; }
  .sdp-xat-rail-seccio__cap {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--sdp-space-4);
    width: 100%;
    min-height: var(--sdp-touch);
    padding: var(--sdp-space-2) var(--sdp-space-4);
    padding-inline-end: var(--sdp-space-2);
    border: 0;
    border-radius: 0;
    background: transparent;
    color: var(--sdp-crom-text-suau);
    font: var(--sdp-font-barra);
    letter-spacing: normal;
    text-transform: none;
    text-align: start;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-rail-seccio__cap:hover { background: var(--sdp-crom-hover); color: var(--sdp-crom-text); }
  }
  .sdp-xat-rail-seccio__cap:focus-visible { outline: 2px solid var(--sdp-crom-focus); outline-offset: -2px; }
  .sdp-xat-rail-seccio__nom {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .sdp-xat-rail-seccio__xebro-cella {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    inline-size: var(--sdp-touch);
  }
  .sdp-xat-rail-seccio__xebro { flex: none; transition: transform var(--sdp-t); }
  .sdp-xat-rail-seccio__cap[aria-expanded="false"] .sdp-xat-rail-seccio__xebro { transform: rotate(-90deg); }
  /* La secció plegada que conté l'entrada activa (la persona l'ha plegada
     estant-hi): la capçalera porta el mateix marcador blanc de 3px que la
     fila activa (T62b, .sdp-workspace-nav-item[aria-current="page"]::before)
     i el nom en to ple, perquè l'estat actual no desaparega del rail. És un
     pseudo-element posat damunt: ni el coixí ni cap text es mouen. */
  .sdp-xat-rail-seccio__cap--actual { position: relative; color: var(--sdp-crom-text); }
  .sdp-xat-rail-seccio__cap--actual::before {
    content: '';
    position: absolute;
    inset-block: 0;
    inset-inline-start: 0;
    inline-size: 3px;
    background: var(--sdp-crom-seleccio-text);
    pointer-events: none;
  }

  /* Peu fix del rail: l'avatar propi a l'eix de les icones (16 de coixí i
     24 d'avatar), «Tu» i, a la dreta, el llapis de 44. Plegat, només
     l'avatar, en una cel·la de rail com les altres. Plegar no fa cap bot:
     en els dos estats el peu fa var(--sdp-alt-accio) amb la vora inclosa i
     va a ras de baix, i l'avatar queda centrat a la mateixa alçada. */
  .sdp-xat-rail-peu {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-4);
    flex: none;
    min-height: var(--sdp-alt-accio);
    padding: 0 var(--sdp-space-2) 0 var(--sdp-space-4);
    border-top: 1px solid var(--sdp-crom-vora-forta);
    color: var(--sdp-crom-text);
  }
  .sdp-xat-rail-peu__nom {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font: var(--sdp-font-barra);
  }
  /* Plegat, el peu viu dins de la capçalera plegada, que porta
     var(--sdp-space-2) de coixí de baix (AppGridShell.css, «un sol joc de
     regles»): el marge negatiu l'anul·la i el peu torna a anar a ras de baix. */
  .sdp-xat-rail-peu.sdp-xat-rail-peu--plegat {
    display: flex;
    align-items: center;
    min-height: var(--sdp-alt-accio);
    padding: 0;
    margin-bottom: calc(var(--sdp-space-2) * -1);
  }

  /* Controls inerts de les vistes en construcció: es veuen com a la captura
     i es poden enfocar (aria-disabled), però el cursor diu que no fan res. */
  .sdp-xat-inert[aria-disabled="true"] { cursor: not-allowed; }
  .sdp-xat-cerca__camp--inert .sdp-xat-cerca__etiqueta { cursor: not-allowed; }

  /* «Editar» de Destacats (captura 19.42.17): píndola sobre el crom, com
     el «…» de la llista, amb text. */
  .sdp-xat-vista__pindola {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    min-height: var(--sdp-touch);
    padding: 0 var(--sdp-space-4);
    border: 0;
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-crom-realc);
    color: var(--sdp-crom-text);
    font: inherit;
    font-weight: 600;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-vista__pindola:hover { background: var(--sdp-crom-hover); }
  }
  .sdp-xat-vista__pindola:focus-visible { outline: 2px solid var(--sdp-crom-focus); outline-offset: 2px; }

  /* Contingut multimèdia (captura 19.41.58): el subtítol i el control
     segmentat «Fitxers | Enllaços | Documents», davall de la fila de títol. */
  .sdp-xat-vista__fila {
    display: grid;
    gap: var(--sdp-space-2);
    flex: none;
    padding: var(--sdp-space-2) var(--sdp-space-3);
    background: var(--sdp-fons-targeta);
  }
  .sdp-xat-vista__subtitol {
    margin: 0;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-small);
  }
  .sdp-xat-segments {
    display: flex;
    gap: var(--sdp-space-1);
    padding: var(--sdp-space-1);
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-fons-subtil);
  }
  /* El segment premut no es distingix només pel to: el blanc de la targeta
     sobre el fons subtil fa 1,18:1. Porta una vora de --sdp-vora-control
     (Pedra 500), que fa 3,11:1 contra el fons subtil i 3,66:1 contra la
     targeta en clar, i 3,71:1 i 4,90:1 en fosc: WCAG 1.4.11, 3:1 per a
     l'estat d'un component. Els altres segments porten la mateixa vora,
     transparent, perquè el text no es moga en canviar de segment. */
  .sdp-xat-segments__opcio {
    flex: 1 1 0;
    min-width: 0;
    min-height: var(--sdp-touch);
    padding: 0 var(--sdp-space-3);
    border: 1px solid transparent;
    border-radius: var(--sdp-radi-pastilla);
    background: transparent;
    color: var(--sdp-text-cos);
    font: inherit;
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .sdp-xat-segments__opcio[aria-pressed="true"] {
    border-color: var(--sdp-vora-control);
    background: var(--sdp-fons-targeta);
    color: var(--sdp-text-titol);
    font-weight: 700;
  }
  .sdp-xat-segments__opcio:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: 2px; }

  /* La targeta «En construcció»: honesta, sobre fons subtil i amb vora
     discontínua, sense ombra. */
  .sdp-xat-construccio {
    display: grid;
    justify-items: center;
    gap: var(--sdp-space-2);
    margin: var(--sdp-space-4);
    padding: var(--sdp-space-6) var(--sdp-space-4);
    border: 1px dashed var(--sdp-vora-control);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-cos);
    text-align: center;
  }
  .sdp-xat-construccio__icona { display: inline-flex; color: var(--sdp-accio-text); }
  /* El h3 editorial (base.css) hi posaria 12px de coixí de baix, una vora i
     el text a l'esquerra: ací es neutralitzen; l'aire el dona el gap. */
  .sdp-xat-construccio__titol {
    margin: 0;
    padding: 0;
    border: 0;
    text-align: center;
    font-size: var(--sdp-text-h6);
    font-weight: 700;
    line-height: 1.2;
    color: var(--sdp-text-titol);
  }
  .sdp-xat-construccio__text,
  .sdp-xat-construccio__avis { margin: 0; max-width: var(--sdp-measure); }
  .sdp-xat-construccio__avis { color: var(--sdp-text-suau); }

  /* Contingut multimèdia operatiu (ordre del Mestre del 261004, prompt
     261004_0515, T5; VistaMultimedia). El control segmentat ja fa coses, i
     el cursor ho diu. A Enllaços, cada URL és una fila de la llista a sang:
     el domini en negreta, l'enllaç (de var(--sdp-touch) d'alt; una URL
     llarga es parteix on calga) i, germà de l'enllaç, el botó de la
     conversa on es va compartir, també de var(--sdp-touch). A Fitxers i
     Documents, les files de xat de sempre. Cap li hereta el sagnat del li
     editorial (base.css). */
  .sdp-xat-segments__opcio:not(.sdp-xat-inert) { cursor: pointer; }
  .sdp-xat-multimedia__item {
    display: grid;
    gap: var(--sdp-space-1);
    margin: 0;
    padding: var(--sdp-space-2) var(--sdp-space-4);
    border-bottom: 1px solid var(--sdp-vora);
  }
  .sdp-xat-multimedia__adjunt { margin: 0; padding: 0; }
  .sdp-xat-multimedia__host {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-weight: 700;
    color: var(--sdp-text-titol);
  }
  .sdp-xat-multimedia__enllac { min-width: 0; }
  .sdp-xat-multimedia__enllac > span { display: grid; gap: var(--sdp-space-1); }
  .sdp-xat-multimedia__enllac .sdp-xat-enllac {
    display: flex;
    align-items: center;
    min-height: var(--sdp-touch);
    overflow-wrap: anywhere;
  }
  .sdp-xat-multimedia__enllac .sdp-xat-enllac__avis { margin-inline-start: 0; }
  .sdp-xat-multimedia__conversa {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-2);
    width: 100%;
    min-height: var(--sdp-touch);
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--sdp-text-suau);
    font: inherit;
    text-align: left;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-multimedia__conversa:hover { color: var(--sdp-text-titol); }
  }
  .sdp-xat-multimedia__conversa:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: 2px; }
  .sdp-xat-multimedia__nom {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  /* Amb la barra mòbil a la vista (.sdp-root.is-compact): la reserva va al
     contenidor, darrere de l'avís local, i la targeta d'adjunts de dins no
     la repetix (la regla de baix la posa a totes les targetes).
     Revisió 261004 (Relleus 4-12) · Les llistes de cada mes tampoc: són
     .sdp-xat-llista, i la regla de la llista de converses (bloc F0) els
     posava la reserva a cada una. Es reinicien com a resultats, fitxa,
     diàleg i comunitats. */
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-multimedia {
    padding-bottom: calc(var(--sdp-alt-nav-mobil) + env(safe-area-inset-bottom, 0px));
  }
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-multimedia .sdp-xat-construccio { margin-bottom: var(--sdp-space-4); }
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-multimedia .sdp-xat-llista { padding-bottom: 0; }

  /* Vista Comunitats (captura 19.41.43): per a cada comunitat, la fila de
     capçalera (avatar quadrat net, sense les targetes apilades de la llista
     de Xats, i nom en negreta), les files dels fills i «Veure-ho tot ›».
     L'avatar s'alinea amb el de les files. */
  .sdp-xat-vista-comunitats__avatar { display: inline-flex; flex: none; }
  .sdp-xat-vista-comunitats {
    display: grid;
    gap: var(--sdp-space-4);
    padding-bottom: var(--sdp-space-4);
  }
  .sdp-xat-vista-comunitats__bloc { margin: 0; }
  .sdp-xat-vista-comunitats__cap {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-3);
    margin: 0;
    padding: var(--sdp-space-3) var(--sdp-space-4);
    border: 0;
    border-bottom: 1px solid var(--sdp-vora);
    font-size: inherit;
    font-weight: 800;
    line-height: 1.2;
    letter-spacing: normal;
    text-transform: none;
    text-align: left;
    color: var(--sdp-text-titol);
  }
  .sdp-xat-vista-comunitats__nom {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .sdp-xat-vista-comunitats__tot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--sdp-space-2);
    width: 100%;
    min-height: var(--sdp-touch);
    padding: var(--sdp-space-2) var(--sdp-space-4);
    border: 0;
    border-bottom: 1px solid var(--sdp-vora);
    background: transparent;
    color: var(--sdp-text-suau);
    font: inherit;
    text-align: left;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-vista-comunitats__tot:hover { background: var(--sdp-fons-subtil); }
  }
  .sdp-xat-vista-comunitats__tot:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: -2px; }

  /* Amb la barra mòbil a la vista (.sdp-root.is-compact; torn 260930): la
     reserva per a la barra flotant va al contenidor de la vista; les llistes
     de cada comunitat no la repetixen. */
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-vista-comunitats {
    padding-bottom: calc(var(--sdp-alt-nav-mobil) + env(safe-area-inset-bottom, 0px));
  }
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-construccio {
    margin-bottom: calc(var(--sdp-alt-nav-mobil) + env(safe-area-inset-bottom, 0px));
  }
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-vista-comunitats .sdp-xat-llista { padding-bottom: 0; }
  /* El peu del rail s'aparta de la barra mòbil com la llista de converses. */
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-rail-peu {
    margin-bottom: calc(var(--sdp-alt-nav-mobil) + env(safe-area-inset-bottom, 0px));
  }
  /* Revisió adversarial 260930 (P3) · Plegat, la regla de dalt substituïa el
     marge de −8px que compensa el coixí de baix de la capçalera plegada, i
     en compacte ample (900–1023px, closca 'ample') el peu plegat acabava 8px
     més amunt que el desplegat: plegar feia bot. La reserva, menys el coixí. */
  :where(.sdp-root.is-compact) .app-grid-shell .sdp-xat-rail-peu.sdp-xat-rail-peu--plegat {
    margin-bottom: calc(var(--sdp-alt-nav-mobil) + env(safe-area-inset-bottom, 0px) - var(--sdp-space-2));
  }

  /* Marcs dels espècimens del Xat al catàleg de disseny: una columna amb
     alçada fixa, perquè el peu del rail i els cossos amb scroll es vegen
     com a la closca. Dins van amb .sdp-xat, com a l'app. */
  .sdp-xat-especimen {
    display: flex;
    flex-direction: column;
    block-size: 36rem;
    inline-size: min(100%, 24rem);
    margin-bottom: var(--sdp-space-4);
    overflow: hidden;
    border: 1px solid var(--sdp-vora);
    background: var(--sdp-fons-targeta);
    color: var(--sdp-text-cos);
  }
  .sdp-xat-especimen--rail {
    inline-size: min(100%, 17.5rem);
    background: var(--sdp-workspace-nav-fons);
    color: var(--sdp-crom-text);
  }
  .sdp-xat-especimen--carril { inline-size: 3.5rem; }
  .sdp-xat-especimen--baixa { block-size: auto; }
  /* El «…» obert: el menú ix per davall de la fila de títol, i el marc li
     deixa lloc en lloc de retallar-lo. */
  .sdp-xat-especimen.sdp-xat-especimen--menu {
    block-size: auto;
    padding-bottom: var(--sdp-space-16);
    overflow: visible;
    border: 0;
    background: transparent;
  }
  .sdp-xat-especimen > .sdp-workspace-column { flex: 1 1 auto; min-height: 0; }

  /* ── El full «Ajustos» (torn 260930, T1; captures 20.47–21.05) ─────────
     Calcat del d'«Ajustes» de WhatsApp Desktop: un modal CENTRAT de mida
     FIXA (480×640 a la captura: 30×40rem), radi gran i fons neutre amb
     targetes blanques. Navegar dins del full no el mou ni el canvia de mida,
     i una pàgina curta no l'encongix: la mida és la del marc, no la del
     contingut. És el Dialeg de Pedra Seca en variant «sense-marc» (el
     <dialog> és el marc). La segona forma del selector guanya a la del modal
     local de l'encastat (layout.css, `:host .sdp-capa-modal > .sdp-dialeg`),
     que li posaria l'amplària i el radi de tots els diàlegs. */
  .sdp-dialeg.sdp-xat-ajustos,
  .sdp-capa-modal > .sdp-dialeg.sdp-xat-ajustos {
    inline-size: min(100%, 30rem);
    block-size: min(100%, 40rem);
    padding: 0;
    overflow: hidden;
    border-radius: var(--sdp-radi-xl);
    background: var(--sdp-fons-app);
    color: var(--sdp-text-cos);
  }
  /* Només obert: el full d'estil del navegador amaga el <dialog> tancat amb
     display: none, i un display d'autor sense [open] el tornaria a mostrar. */
  .sdp-dialeg.sdp-xat-ajustos[open] { display: flex; flex-direction: column; }
  /* Estret: tota la pantalla, com les pantalles empeses de WhatsApp mòbil.
     Revisió adversarial 260930 (P2) · Amb el MATEIX tall que convertix la
     resta de Dialeg en full inferior, no amb .is-compact (≤1023): entre 721
     i 1023 el full és el modal centrat, com els altres diàlegs, i a
     l'encastat ja no queda un marc de 8px de vel amb cantons rectes.
     · socdepoble.org: la media query del full inferior (components.css,
       max-width: 720px), a la qual guanya per ordre amb la mateixa
       especificitat;
     · l'encastat: [data-sdp-estret] de l'arrel (App.jsx, ≤720px de caixa),
       on la capa ja no porta coixí (layout.css). La regla iguala la del full
       inferior del modal local i, per ordre, li lleva el radi de dalt. */
  @media (max-width: 720px) {
    .sdp-dialeg.sdp-xat-ajustos {
      inset: 0;
      inline-size: 100%;
      block-size: 100%;
      max-inline-size: none;
      max-block-size: none;
      margin: 0;
      border: 0;
      border-radius: 0;
    }
    .sdp-dialeg.sdp-xat-ajustos .sdp-xat-ajustos__cap { padding-top: calc(var(--sdp-space-2) + env(safe-area-inset-top, 0px)); }
    .sdp-dialeg.sdp-xat-ajustos .sdp-xat-ajustos__cos { padding-bottom: calc(var(--sdp-space-6) + env(safe-area-inset-bottom, 0px)); }
  }
  :host .sdp-root[data-sdp-estret] > .sdp-capa-modal > .sdp-dialeg.sdp-xat-ajustos {
    inline-size: 100%;
    block-size: 100%;
    border: 0;
    border-radius: 0;
  }
  :host .sdp-root[data-sdp-estret] > .sdp-capa-modal > .sdp-dialeg.sdp-xat-ajustos .sdp-xat-ajustos__cap {
    padding-top: calc(var(--sdp-space-2) + env(safe-area-inset-top, 0px));
  }
  :host .sdp-root[data-sdp-estret] > .sdp-capa-modal > .sdp-dialeg.sdp-xat-ajustos .sdp-xat-ajustos__cos {
    padding-bottom: calc(var(--sdp-space-6) + env(safe-area-inset-bottom, 0px));
  }
  /* El marc del cos (també el de l'espècimen del catàleg): capçalera i
     cercador fixos; només el cos fa scroll per davall. */
  .sdp-xat-ajustos__marc {
    display: flex;
    flex-direction: column;
    flex: 1 1 auto;
    min-height: 0;
  }
  /* La capçalera: el botó circular (X a l'arrel, ‹ a les subpàgines) a
     l'esquerra, el títol centrat i, a la dreta, una cel·la buida de la
     mateixa amplària perquè el títol quede al centre de veres. */
  .sdp-xat-ajustos__cap {
    display: grid;
    grid-template-columns: var(--sdp-touch) minmax(0, 1fr) var(--sdp-touch);
    align-items: center;
    gap: var(--sdp-space-2);
    flex: none;
    padding: var(--sdp-space-2) var(--sdp-space-3);
  }
  .sdp-xat-ajustos__cercle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: var(--sdp-touch);
    block-size: var(--sdp-touch);
    padding: 0;
    border: 0;
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-fons-targeta);
    color: var(--sdp-text-titol);
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-ajustos__cercle:hover { background: var(--sdp-fons-subtil); }
  }
  .sdp-xat-ajustos__cercle:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: 2px; }
  /* El h2 editorial (base.css) hi posaria marges, vora i mida de lectura:
     ací és el títol d'una barra, centrat i en negreta. */
  .sdp-xat-ajustos__titol {
    margin: 0;
    padding: 0;
    border: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: var(--sdp-text-base);
    font-weight: 700;
    line-height: 1.2;
    letter-spacing: normal;
    text-transform: none;
    text-align: center;
    color: var(--sdp-text-titol);
  }
  .sdp-xat-ajustos__dreta { inline-size: var(--sdp-touch); }
  /* El cercador en píndola blanca, fix davall de la capçalera; la píndola i
     la lupa són les de la cerca del Xat (.sdp-xat-cerca__camp). */
  .sdp-xat-ajustos__cerca { flex: none; padding: 0 var(--sdp-space-5) var(--sdp-space-2); }
  .sdp-xat-ajustos__cerca .sdp-xat-cerca__camp { background: var(--sdp-fons-targeta); }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-ajustos__cerca .sdp-xat-icona:hover { background: var(--sdp-fons-subtil); }
  }
  .sdp-xat-ajustos__cerca .sdp-xat-icona:focus-visible { outline-color: var(--sdp-focus); }
  .sdp-xat-ajustos__cos {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-8);
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding: var(--sdp-space-2) var(--sdp-space-5) var(--sdp-space-6);
  }
  /* Un grup: la capçalera de secció i la nota del peu, xicotetes i grises,
     van fora de la targeta, alineades amb el text de les files. */
  .sdp-xat-ajustos__grup { display: grid; gap: var(--sdp-space-2); margin: 0; }
  .sdp-xat-ajustos__seccio {
    margin: 0;
    padding: 0 var(--sdp-space-4);
    border: 0;
    font-size: var(--sdp-text-meta);
    font-weight: 700;
    line-height: 1.2;
    letter-spacing: normal;
    text-transform: none;
    text-align: start;
    color: var(--sdp-text-suau);
  }
  .sdp-xat-ajustos__targeta {
    margin: 0;
    padding: 0;
    list-style: none;
    overflow: hidden;
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
  }
  /* Revisió adversarial 260930 (P3) · El li editorial (base.css, @layer
     legacy) porta 4px de sagnat: el botó de la fila començava 4px dins de la
     targeta i el fons de hover i l'anell de focus deixaven una franja a
     l'esquerra. El mateix reinici que .sdp-xat-targeta > li. */
  .sdp-xat-ajustos__targeta > li { margin: 0; padding: 0; }
  .sdp-xat-ajustos__nota {
    margin: 0;
    padding: 0 var(--sdp-space-4);
    max-width: var(--sdp-measure);
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
    line-height: 1.4;
  }
  .sdp-xat-ajustos__nota--error { color: var(--sdp-error-text); }
  /* La fila: icona lineal (només a l'arrel), etiqueta, valor gris i xebró o
     ✓. El separador és la vora de baix de la línia: comença a l'altura de
     l'etiqueta, no de la icona, i l'última fila de la targeta no en porta. */
  .sdp-xat-ajustos__fila {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-3);
    inline-size: 100%;
    min-block-size: var(--sdp-touch);
    margin: 0;
    padding: 0 0 0 var(--sdp-space-4);
    border: 0;
    border-radius: 0;
    background: transparent;
    color: var(--sdp-text-cos);
    font: inherit;
    text-align: start;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-ajustos__fila:hover:not(:disabled) { background: var(--sdp-fons-subtil); }
  }
  .sdp-xat-ajustos__fila:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: -2px; }
  .sdp-xat-ajustos__fila:disabled { cursor: default; opacity: 0.6; }
  /* L'acció destructiva, en roig i sense xebró (captura 20.53.25). */
  .sdp-xat-ajustos__fila--perill { color: var(--sdp-error-text); }
  .sdp-xat-ajustos__fila--conversa { min-block-size: var(--sdp-touch-comode); }
  .sdp-xat-ajustos__icona { display: inline-flex; flex: none; color: var(--sdp-text-titol); }
  .sdp-xat-ajustos__linia {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-2);
    flex: 1 1 auto;
    align-self: stretch;
    min-width: 0;
    padding-inline-end: var(--sdp-space-3);
    border-bottom: 1px solid var(--sdp-vora);
  }
  .sdp-xat-ajustos__targeta > li:last-child .sdp-xat-ajustos__linia { border-bottom: 0; }
  .sdp-xat-ajustos__etiqueta {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .sdp-xat-ajustos__valor {
    flex: 0 1 auto;
    min-width: 0;
    max-width: 60%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--sdp-text-suau);
  }
  .sdp-xat-ajustos__xebro { flex: none; color: var(--sdp-text-suau); }
  /* La selecció única: el ✓ en el color d'acció, no en el verd de WhatsApp. */
  .sdp-xat-ajustos__marca { flex: none; color: var(--sdp-accio); }
  /* La targeta del perfil: avatar gran i nom; porta al perfil. */
  .sdp-xat-ajustos__perfil {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-3);
    inline-size: 100%;
    min-block-size: var(--sdp-touch);
    margin: 0;
    padding: var(--sdp-space-3) var(--sdp-space-4);
    border: 0;
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
    color: var(--sdp-text-titol);
    font: inherit;
    font-weight: 700;
    text-align: start;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-ajustos__perfil:hover { background: var(--sdp-fons-subtil); }
  }
  .sdp-xat-ajustos__perfil:focus-visible { outline: 2px solid var(--sdp-focus); outline-offset: 2px; }
  .sdp-xat-ajustos__perfil-nom {
    flex: 1 1 auto;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: var(--sdp-text-base);
  }
  /* Una pàgina sense dades (captura 21.05.44, «No hay reportes»): el títol en
     negreta i una frase grisa, centrats al cos, sense icona ni botó. */
  .sdp-xat-ajustos__buit {
    display: grid;
    justify-items: center;
    align-content: center;
    gap: var(--sdp-space-2);
    flex: 1 1 auto;
    margin: 0;
    padding: var(--sdp-space-8) var(--sdp-space-4);
    text-align: center;
  }
  .sdp-xat-ajustos__buit-titol {
    margin: 0;
    padding: 0;
    border: 0;
    font-size: var(--sdp-text-h5);
    font-weight: 700;
    line-height: 1.2;
    letter-spacing: normal;
    text-transform: none;
    text-align: center;
    color: var(--sdp-text-titol);
  }
  .sdp-xat-ajustos__buit-text { margin: 0; max-width: var(--sdp-measure); color: var(--sdp-text-suau); }
  /* Pantalla completa: la capçalera i el cos s'aparten de les vores segures
     amb el mateix tall que la pantalla completa (dalt, «Estret»). */

  /* L'entrada al full des del peu desplegat del rail (captura 20.47.21):
     l'avatar i «Tu» en un sol botó, a sang com les files del rail. El peu li
     cedix el coixí esquerre i el botó el torna: l'avatar no es mou de l'eix
     de les icones (16 de coixí i 24 d'avatar). */
  .sdp-xat-rail-peu.sdp-xat-rail-peu--ajustos { padding-inline-start: 0; }
  .sdp-xat-ajustos-entrada {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-4);
    flex: 1 1 auto;
    align-self: stretch;
    min-width: 0;
    min-block-size: var(--sdp-touch);
    margin: 0;
    padding: 0 var(--sdp-space-2) 0 var(--sdp-space-4);
    border: 0;
    border-radius: 0;
    background: transparent;
    color: inherit;
    font: inherit;
    text-align: start;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-xat-ajustos-entrada:hover { background: var(--sdp-crom-hover); }
  }
  .sdp-xat-ajustos-entrada:focus-visible { outline: 2px solid var(--sdp-crom-focus); outline-offset: -2px; }

  /* El marc de l'espècimen del catàleg (EspecimenXatAjustos): la mida del
     full, sense Dialeg, amb el cos en línia. */
  .sdp-xat-ajustos-especimen {
    display: flex;
    flex-direction: column;
    inline-size: min(100%, 30rem);
    block-size: 40rem;
    margin-bottom: var(--sdp-space-4);
    overflow: hidden;
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-xl);
    background: var(--sdp-fons-app);
    color: var(--sdp-text-cos);
  }
}

@layer components {
  /* Els colors de reserva que duien estos var() no s'han disparat mai: els
     tres tokens existixen. Fora, doncs, sense moure cap píxel. En canvi 40px
     i 13px sí que es veien, i els dos estaven per davall de dos lleis
     declarades: --sdp-touch (44px, Llei de Vida) i --sdp-text-meta (14px,
     «sòl absolut de mida de lletra»). --sdp-text-mut no existix: `color` amb
     una variable inexistent hereta, que és el que ja passava; per això la
     línia se'n va. */
  .sdp-brain-graph-wrapper { min-height: 420px; }
  .sdp-brain-graph-canvas { display: block; width: 100%; height: 100%; }
  .sdp-brain-graph-controls button { min-width: var(--sdp-touch); min-height: var(--sdp-touch); }
  .sdp-brain-graph-inspector {
    position: absolute; top: 16px; left: 16px; width: 250px;
    max-height: calc(100% - 32px); overflow: auto; padding: 16px;
    background: var(--sdp-fons-app); color: var(--sdp-text-cos);
    border: 1px solid var(--sdp-vora); border-radius: 12px;
    box-shadow: var(--sdp-ombra-3); font-size: var(--sdp-text-meta); overflow-wrap: anywhere;
  }
  .sdp-brain-graph-inspector h3 { margin: 0 0 12px; }
  .sdp-brain-graph-inspector select { width: 100%; margin: 8px 0; color: inherit; background: inherit; }
  .sdp-brain-graph-inspector dt {
    font-weight: 600;
    margin-top: 8px;
  }
  .sdp-brain-graph-open-btn {
    display: block;
    text-align: center;
    margin-bottom: 12px;
  }
  .sdp-brain-graph-inspector dd { margin: 0; }
  .sdp-brain-graph-inspector ul { padding-left: 16px; }
  .sdp-brain-graph-inspector button { color: inherit; background: transparent; cursor: pointer; }
  @media (max-width: 640px) {
    .sdp-brain-graph-inspector { top: auto; bottom: 12px; left: 12px; width: calc(100% - 24px); max-height: 32%; box-sizing: border-box; }
  }

  /* Les dos portades (catàleg de disseny i Wiki) duien este coixí en un
     style={{…}}. Ací és el mateix coixí, però on es pot auditar. El cos dels
     documents NO el porta: per això és un modificador i no la classe base. */
  .sdp-prose--encoixinada { padding: var(--sdp-space-4); }

  /* Caixa del graf del cervell. Venia d'un style={{…}} que demanava
     --sdp-radi-lg, un token que no existix: la declaració queia i les
     cantonades ja eren rectes. No s'inventa cap radi nou ací. */
  .sdp-wiki-graf {
    height: calc(100vh - 200px);
    overflow: hidden;
    border: 1px solid var(--sdp-crom-vora);
  }
}

/* ═══ TELEMETRIA POCA-SOLTA · TAULER DE /legal (260924) ════════════════
   TaulerTelemetria.jsx, davall del text legal. Mateixa columna de lectura
   que la prosa (68ch, centrada com .cms-preview > *). Se separa per vora i
   fons, sense ombra (Pedra Seca §5), i no té cap color propi: només tokens
   semàntics. L'espai el dona el gap de la graella; per això els fills
   directes perden el marge heretat. */
@layer components {
  .sdp-telemetria {
    display: grid;
    gap: var(--sdp-space-4);
    max-width: 68ch;
    margin: var(--sdp-space-8) auto 0;
    padding-block-start: var(--sdp-space-8);
    border-block-start: 1px solid var(--sdp-vora);
  }
  .sdp-telemetria > h3,
  .sdp-telemetria > h4,
  .sdp-telemetria > p { margin: 0; }
  .sdp-telemetria > h3,
  .sdp-telemetria > h4 { line-height: 1.2; }
  .sdp-telemetria > h4 { margin-block-start: var(--sdp-space-4); }
  .sdp-telemetria__punts {
    display: grid;
    gap: var(--sdp-space-2);
    margin: 0;
    padding-inline-start: var(--sdp-space-6);
  }
  .sdp-telemetria__nota {
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
    line-height: 1.6;
  }
  .sdp-telemetria__tauler {
    display: block;
    width: 100%;
    height: min(36rem, 75dvh);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
  }
  .sdp-telemetria__llista {
    display: grid;
    gap: var(--sdp-space-2);
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .sdp-telemetria__intent {
    display: grid;
    gap: var(--sdp-space-1);
    padding: var(--sdp-space-3) var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-s);
    background: var(--sdp-fons-targeta);
  }
  .sdp-telemetria__intent > p { margin: 0; }
  .sdp-telemetria__cap {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--sdp-space-2);
  }
  .sdp-telemetria__nom { font-weight: 700; color: var(--sdp-text-titol); }
  .sdp-telemetria__ruta {
    font-family: var(--sdp-font-mono);
    color: var(--sdp-text-cos);
    overflow-wrap: anywhere;
  }
  .sdp-telemetria__moment,
  .sdp-telemetria__dades {
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
    font-variant-numeric: tabular-nums;
  }
  .sdp-telemetria__estat { color: var(--sdp-text-cos); font-size: var(--sdp-text-meta); }
}

/* Controls centrals: espai lateral comú per a totes les seccions. */
.sdp-workspace .app-grid-column--middle .app-grid-col-header:nth-child(2) {
  padding-inline: max(20px, var(--sdp-space-4));
}

/* Trasllat literal dels estils JSX: mateixa geometria i especificitat local. */
.app-sidebar.app-sidebar--tancada { display: flex; }
.app-sidebar.app-sidebar--oberta { display: flex; }
.sdp-iaia-icon { will-change: transform; }
.sdp-iaia-icon__trac { fill-rule: nonzero; clip-rule: evenodd; stroke-linejoin: round; stroke-miterlimit: 2; }
.sdp-toast-container { position: relative; z-index: 9999; }
.sdp-logo-personalitzat.sdp-logo-personalitzat--editable { max-width: 600px; width: 100%; height: auto; border-radius: var(--sdp-radi-s); cursor: pointer; }
.sdp-editor-tools__group.sdp-editor-tools__group--publicacio { margin-left: auto; border-right: 0; padding-right: 0; }
/* AAA (Q1, 261004): el to suau ve d'un token sòlid (--sdp-text-suau, 9,09:1
   sobre la targeta), no d'una opacitat de 0,7 sobre el text. */
.detail-seller { color: var(--sdp-text-suau); text-transform: uppercase; }
.badge-row.detail-tags, .detail-hero__media.detail-media { margin-top: 18px; }
.sdp-article.sdp-inventari-global { padding: 2rem; }
.sdp-media-externa-video { position: absolute; top: 0; left: 0; width: 100%; height: 100%; border: 0; }
.sdp-media-externa-mapa { border: 0; }
.onboarding-benvinguda { margin-bottom: 2rem; }
.xat-header-menu { position: relative; }

/* ═══════════════════════════════════════════════════════════════════
   LLESQUES DEL POLIMENT EDITORIAL (prompt 260925_1655)
   Quatre blocs, un per llesca vertical: editorial, Consola, Explorador i
   navegació. Viuen al final de modules.css perquè la Porta Vocabulari
   només llig els fulls canònics, i perquè ací, dins de la mateixa capa
   `components`, guanyen per ordre a .sdp-wiki-graf i .sdp-ptr-indicator
   sense cap !important.
   ═══════════════════════════════════════════════════════════════════ */

/* ── EDITORIAL · capçalera de pàgina, títols llargs i prosa de la Wiki ── */
@layer components {

  /* Un nom de fitxer o una ruta sense espais («00_arquitectura_tecnica_…»)
     no té on partir-se i empenyia el bloc blanc fora del marc. `anywhere`
     (i no `break-word`) també compta per a l'amplària mínima: el contenidor
     flex o de graella ja no creix per culpa d'una paraula. */
  header.page-title h1,
  header.page-title .h1,
  .page-intro h2,
  .sp-card-title,
  .sp-card-subtitle,
  .sdp-prose h1,
  .sdp-prose h2,
  .sdp-prose h3,
  .sdp-prose h4,
  .sdp-prose h5,
  .sdp-prose h6,
  .sdp-wiki-iso th,
  .sdp-wiki-iso td,
  .toc-item button {
    overflow-wrap: anywhere;
  }

  /* Títol de targeta amb icona: abans `flex: none` i no podia encongir-se. */
  .sp-card-heading-with-icon .sp-card-title {
    flex: 0 1 auto;
    min-width: 0;
  }

  /* El parser marca el primer paràgraf després del «# » com a p.lead. Mateixa
     veu que la .lead global (base.css) i que la de .page-intro. El marge
     superior zero després del títol ja el posa wiki.css (.h1 + .lead). */
  .sdp-prose p.lead {
    font-size: var(--sdp-text-lead);
    line-height: 1.5;
    font-weight: 600;
    color: var(--sdp-text-suau);
    text-align: center;
    margin-bottom: var(--sdp-mb-lead);
  }
}

/* ── CONSOLA · tauler forense, etiquetes d'estat i desplegables ───────── */
@layer components {

  /* La recepta del Control (.sp-card--action:hover) eleva i posa la mà a
     totes les targetes, també a les que no obrin res. Una targeta sense
     enllaç ni botó (TargetaResum sense `a` ni `onObri`) no ho fa veure. */
  .sp-card--action.sdp-consola__quieta:hover,
  .sdp-consola__targeta.sdp-consola__quieta:hover {
    box-shadow: var(--sdp-ombra-2);
    transform: none;
    cursor: default;
  }

  /* Targeta explicativa (peces.jsx · TargetaConsola): la UniversalCard del
     Mur amb la icona a la insígnia lateral. L'entradilla és un paràgraf del
     cos i la dada viva, les mètriques en h5 (més avall) o, sense mesura, un
     altre paràgraf que es llig com a dada, no com a prosa. */
  /* La graella de les targetes explicatives es mesura pel seu contenidor, no
     per la finestra: el tauler també viu incrustat en una columna de la Wiki
     (ConsolaIncrustada), on tres columnes de viewport ofegarien el cos.
     auto-fill, com la graella canònica (.sdp-card-grid), i no auto-fit
     (avís del Mestre, 261004, a /consola/pols): auto-fit esfondra les pistes
     buides d'una fila incompleta, les columnes s'eixamplen (770px a 1920) i
     la .sp-card, amb max-width 500px i marge auto, queda centrada en la seua
     cel·la amb un forat al mig. Amb auto-fill les pistes buides es queden i
     cada targeta conserva l'amplada de la seua columna, alineada a l'esquerra
     com la fila de dalt. Una fila plena es pinta igual amb les dues. */
  .sdp-card-grid.sdp-consola__graella {
    grid-template-columns: repeat(auto-fill, minmax(min(100%, 20rem), 1fr));
  }
  .sdp-consola__targeta .sp-card-text > p { margin: 0 0 var(--sdp-space-2); }
  .sdp-consola__targeta .sp-card-text > p:last-child { margin-bottom: 0; }
  .sdp-consola__dada {
    color: var(--sdp-text-cos);
    font-weight: 700;
    font-variant-numeric: tabular-nums;
  }
  /* Derogat per l'ordre del Mestre del 261004 (xat: tota targeta amb boina i
     pàgina pròpia): la línia de data del cos (.sdp-consola__data). La
     targeta de la Consola torna a portar la boina de Sóc de Poble i la data
     va a la seua pastilla (T51), com totes les targetes. */
  /* T2 (ordre del Mestre, 260930) · Mètriques de tauler: cada xifra és un
     h5 (l'Índex de la Consola les recull), centrat i amb xifres tabulars.
     clear: la insígnia lateral flota a la dreta i en desplaçaria el centre.
     El scroll-margin és el dels desplegables: el salt des de l'Índex no
     queda davall de les barres. Derogat per l'ordre del Mestre del 261004
     (barra taronja universal): el marge d'una sola barra (la blava); ara en
     són dues, la blava i la taronja, totes dues de --sdp-alt-accio. */
  .sdp-consola__metriques {
    clear: both;
    display: grid;
    gap: var(--sdp-space-1);
  }
  .sdp-consola__metrica {
    margin: 0;
    font-size: var(--sdp-text-h5);
    line-height: var(--sdp-leading-snug);
    font-weight: 700;
    color: var(--sdp-accio-text);
    text-align: center;
    font-variant-numeric: tabular-nums;
    scroll-margin-top: calc(var(--sdp-alt-accio) * 2 + var(--sdp-space-4));
  }
  /* T3 (ordre del Mestre, 260930) · Coberta: els estats de dins de la pàgina,
     el més greu primer, darrere de les mètriques i centrats com elles.
     Insígnies d'estat (Insignia), no etiquetes de la targeta ni capçaleres:
     l'Índex de la Consola no les recull. La llista es reinicia ací perquè
     cap utilitat de disposició ho fa. Cada li, també: sense el marge i el
     sagnat de base.css el buit entre files és el gap i la insígnia queda al
     centre; flex l'ajusta a l'alt de la insígnia, sense la línia de sobra. */
  .sdp-consola__estats {
    clear: both;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--sdp-space-2);
    margin: var(--sdp-space-2) 0 0;
    padding: 0;
    list-style: none;
  }
  .sdp-consola__estats > li { display: flex; margin: 0; padding: 0; }

  /* Ordre del Mestre, 261004 (cap anomalia sense mostrar) · Un avís del Mapa
     a l'Inventari (AvisosMapa.jsx): el codi amb el color de la severitat, la
     frase i les evidències, apilats; entre avisos, aire. La llista
     d'evidències es reinicia com la dels estats: sense el marge de base.css. */
  .sdp-consola__avis {
    display: grid;
    justify-items: start;
    gap: var(--sdp-space-1);
  }
  .sdp-consola__avis + .sdp-consola__avis { margin-top: var(--sdp-space-3); }
  .sdp-consola__avis > p { margin: 0; }
  .sdp-consola__evidencies {
    margin: 0;
    padding: 0 0 0 var(--sdp-space-5);
  }
  .sdp-consola__evidencies > li { margin: 0; padding: 0; }

  /* Desplegables «Veure detall de…» (peces.jsx · Desplegable): una fila
     sencera de com a mínim --sdp-touch, amb vora i radi del sistema. El
     xebró gira només amb CSS quan el <details> és obert. scroll-margin-top:
     la barra blava i la taronja són sticky dins del contenidor de scroll;
     sense marge, el desplegable que obri una targeta quedava tapat. Derogat
     per l'ordre del Mestre del 261004 (barra taronja universal): el marge
     d'una sola barra. */
  .sdp-consola__detall {
    margin-block: var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
    scroll-margin-top: calc(var(--sdp-alt-accio) * 2 + var(--sdp-space-4));
  }
  .sdp-consola__detall-cap {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--sdp-space-3);
    min-height: var(--sdp-touch);
    padding: var(--sdp-space-2) var(--sdp-space-4);
    border-radius: var(--sdp-radi-m);
    color: var(--sdp-text-titol);
    font-size: var(--sdp-text-base);
    font-weight: 700;
    line-height: var(--sdp-leading-snug);
    list-style: none;
    cursor: pointer;
    transition: background var(--sdp-t);
  }
  /* Safari pinta el triangle natiu encara que el summary siga flex. */
  .sdp-consola__detall-cap::-webkit-details-marker { display: none; }
  @media (hover: hover) and (pointer: fine) {
    .sdp-consola__detall-cap:hover { background: var(--sdp-fons-subtil); }
  }
  .sdp-consola__detall-cap:focus-visible {
    outline: 3px solid var(--sdp-focus);
    outline-offset: 2px;
  }
  .sdp-consola__detall[open] > .sdp-consola__detall-cap {
    border-end-start-radius: 0;
    border-end-end-radius: 0;
    border-block-end: 1px solid var(--sdp-vora);
  }
  .sdp-consola__detall-xebro {
    flex: none;
    color: var(--sdp-accio-text);
    transition: transform var(--sdp-t);
  }
  .sdp-consola__detall[open] > .sdp-consola__detall-cap > .sdp-consola__detall-xebro {
    transform: rotate(180deg);
  }
  .sdp-consola__detall-cos { padding: var(--sdp-space-4); }
  .sdp-consola__detall-cos > :last-child { margin-bottom: 0; }

  .sdp-consola__estrategia {
    margin-bottom: var(--sdp-space-6);
    white-space: pre-line;
    font-size: var(--sdp-text-small);
    color: var(--sdp-text-suau);
  }

}

/* ── EXPLORADOR · llegenda, cerca i filtres; el graf i el detall al final ── */
@layer components {
  /* L'Explorador (ExploradorMapa.jsx). T3 (ordre del Mestre, 260930): la
     llegenda, la cerca i els filtres plegats van primer; el graf, al final
     de la pàgina, perquè la rodeta damunt del canvas fa zoom i al començament
     no deixava baixar. */
  .sdp-explorador {
    display: grid;
    gap: var(--sdp-space-4);
    min-width: 0;
  }

  /* El graf i el detall de la peça (DetallPeca.jsx, T4): un davall de
     l'altre en estret; en ample, el detall a la dreta (vegeu la consulta de
     64rem al final del bloc). */
  .sdp-explorador__marc {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    align-items: start;
    gap: var(--sdp-space-4);
    min-width: 0;
  }

  /* La barra de cerca ja no compartix marc amb el graf: porta la seua vora.
     Vora i fons, sense ombra (Pedra Seca §5). */
  .sdp-explorador__barra {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--sdp-space-2) var(--sdp-space-4);
    padding: var(--sdp-space-2) var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
  }

  /* El Camp canònic apila etiqueta, ajuda i control; ací van en fila:
     etiqueta i camp de costat, l'ajuda davall del camp. */
  .sdp-explorador__cerca.sdp-camp {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    grid-template-areas:
      "etiqueta control"
      ".        ajuda";
    align-items: center;
    gap: var(--sdp-space-1) var(--sdp-space-3);
    flex: 1 1 24rem;
    min-width: 0;
    margin: 0;
  }
  .sdp-explorador__cerca .sdp-camp__etiqueta { grid-area: etiqueta; }
  .sdp-explorador__cerca .sdp-control { grid-area: control; }
  .sdp-explorador__cerca .sdp-camp__ajuda {
    grid-area: ajuda;
    margin: 0;
    font-size: var(--sdp-text-small);
  }

  .sdp-explorador__recompte {
    margin: 0;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-small);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  /* El graf: alçada estable. svh no bota quan la barra del navegador mòbil
     s'amaga; Chrome 100 no el coneix, descarta la segona declaració i es
     queda amb vh. Guanya a .sdp-wiki-graf (més amunt en este full) per ordre
     dins de la mateixa capa. T3: la vora, el radi i el fons que eren del marc
     compartit amb la cerca passen al graf, que ara va sol. */
  .sdp-explorador__graf {
    position: relative;
    height: clamp(26rem, 72vh, 60rem);
    height: clamp(26rem, 72svh, 60rem);
    min-width: 0;
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-app);
  }
  .sdp-explorador__graf > .sdp-brain-graph-wrapper { min-height: 0; }

  /* Cap node visible: el motiu i la manera de tornar, al mig del graf. */
  .sdp-explorador__buit {
    position: absolute;
    inset: 0;
    z-index: 1;
    display: grid;
    place-content: center;
    justify-items: center;
    gap: var(--sdp-space-3);
    padding: var(--sdp-space-6);
    text-align: center;
    pointer-events: none;
  }
  .sdp-explorador__buit > * {
    margin: 0;
    pointer-events: auto;
  }
  .sdp-explorador__buit > p {
    max-width: 36ch;
    color: var(--sdp-text-cos);
    font-size: var(--sdp-text-base);
    line-height: 1.6;
  }

  .sdp-explorador__llegenda {
    margin: 0;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-small);
    line-height: 1.6;
  }

  /* Filtres: tres plegables tancats, de costat en pantalla ampla i un davall
     de l'altre en mòbil. Cada capçalera diu l'estat del seu grup. */
  .sdp-explorador__filtres {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
    align-items: start;
    gap: var(--sdp-space-3);
  }
  .sdp-explorador__filtres > .sdp-boto { justify-self: start; }

  /* «Restablir» torna el focus a la cerca, al primer plegable o al selector
     del detall, i «Vore la peça» el passa al nom de la peça nova. La barra
     blava i la taronja són sticky dins del contenidor de scroll: sense marge,
     tapaven el que s'enfocava. Mateixa recepta que .sdp-consola__detall
     (derogat per l'ordre del Mestre del 261004, barra taronja universal: el
     marge d'una sola barra). */
  .sdp-explorador__grup > summary,
  .sdp-explorador__barra .sdp-control,
  .sdp-explorador__detall .sdp-control,
  .sdp-explorador__detall-cap > h3 {
    scroll-margin-top: calc(var(--sdp-alt-accio) * 2 + var(--sdp-space-4));
  }

  .sdp-explorador__grup {
    min-width: 0;
    overflow: hidden;
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
  }
  .sdp-explorador__grup > summary {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-3);
    min-height: var(--sdp-touch);
    padding: var(--sdp-space-2) var(--sdp-space-4);
    color: var(--sdp-text-titol);
    font-weight: 700;
    list-style: none;
    cursor: pointer;
  }
  .sdp-explorador__grup > summary::-webkit-details-marker { display: none; }
  .sdp-explorador__grup > summary::after {
    content: "";
    flex: none;
    width: 0.5rem;
    height: 0.5rem;
    margin-inline-end: var(--sdp-space-1);
    border-inline-end: 2px solid currentColor;
    border-block-end: 2px solid currentColor;
    transform: translateY(-25%) rotate(45deg);
    transition: transform var(--sdp-t);
  }
  .sdp-explorador__grup[open] > summary::after { transform: translateY(25%) rotate(225deg); }
  .sdp-explorador__grup[open] > summary { border-block-end: 1px solid var(--sdp-vora); }
  @media (hover: hover) and (pointer: fine) {
    .sdp-explorador__grup > summary:hover { background: var(--sdp-fons-subtil); }
  }
  .sdp-explorador__grup > summary:focus-visible {
    outline: 3px solid var(--sdp-focus);
    outline-offset: -3px;
  }
  .sdp-explorador__resum {
    margin-inline-start: auto;
    color: var(--sdp-text-suau);
    font-weight: 400;
    font-variant-numeric: tabular-nums;
  }
  .sdp-explorador__opcions {
    display: grid;
    gap: var(--sdp-space-1);
    padding: var(--sdp-space-2) var(--sdp-space-4) var(--sdp-space-3);
  }

  /* Llegenda dins dels interruptors de tipus: cada punt porta el mateix token
     que ESTIL_MAPA.colors (grafMapa.js) dona al canvas. grafMapa.test.js
     vigila que no divergisquen. */
  .sdp-explorador__punt {
    display: inline-block;
    width: 0.75rem;
    height: 0.75rem;
    margin-inline-end: var(--sdp-space-2);
    border-radius: var(--sdp-radi-pastilla);
  }
  .sdp-explorador__punt[data-tipus="skill"] { background: var(--sdp-accent); }
  .sdp-explorador__punt[data-tipus="ruta"] { background: var(--sdp-accio); }
  .sdp-explorador__punt[data-tipus="plantilla"] { background: var(--sdp-exit); }
  .sdp-explorador__punt[data-tipus="agent"] { background: var(--sdp-text-titol); }
  .sdp-explorador__punt[data-tipus="hook"] { background: var(--sdp-avis); }
  .sdp-explorador__punt[data-tipus="tasca"] { background: var(--sdp-accio-text); }
  .sdp-explorador__punt[data-tipus="porta"] { background: var(--sdp-error); }
  .sdp-explorador__punt[data-tipus="script"] { background: var(--sdp-text-suau); }
  .sdp-explorador__punt[data-tipus="document"] { background: var(--sdp-vora-forta); }

  /* Detall de la peça (DetallPeca.jsx), T4 (ordre del Mestre, 260930). Una
     targeta de lectura: fons de targeta, vora i cap ombra (Pedra Seca §2 i
     §5); substituïx, només a la Consola, l'inspector superposat de BrainGraph
     (.sdp-brain-graph-inspector, que la Wiki conserva). L'espai el dona el
     gap: els fills directes perden el marge editorial. */
  .sdp-explorador__detall {
    display: grid;
    align-content: start;
    gap: var(--sdp-space-6);
    min-width: 0;
    padding: var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
    color: var(--sdp-text-cos);
    overflow-wrap: anywhere;
  }
  .sdp-explorador__detall > *,
  .sdp-explorador__detall-cap > *,
  .sdp-explorador__bloc > * { margin: 0; }
  .sdp-explorador__detall > p { max-width: var(--sdp-measure); line-height: 1.6; }

  /* Capçalera: tipus, nom (h3, §1.E de la pàgina universal) i què és. El
     nom no porta la ratlla editorial dels h3: dins de la targeta separaria
     el nom de la seua pròpia descripció. */
  .sdp-explorador__detall-cap {
    display: grid;
    gap: var(--sdp-space-2);
  }
  .sdp-explorador__detall-cap > h3 {
    padding-block-end: 0;
    border-block-end: 0;
    line-height: 1.2;
  }
  .sdp-explorador__detall-cap > p:last-child { line-height: 1.6; }

  /* Text complementari (tipus, motius, codis): color suau, sense baixar
     del sòl de lletra. */
  .sdp-explorador__suau {
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-small);
  }

  /* Cada secció (On viu, Dades, Què fa, Qui hi arriba, Avisos): h4 i contingut. */
  .sdp-explorador__bloc {
    display: grid;
    gap: var(--sdp-space-2);
    min-width: 0;
  }
  .sdp-explorador__ruta {
    font-size: var(--sdp-text-small);
    overflow-wrap: anywhere;
  }
  .sdp-explorador__accions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--sdp-space-2);
  }

  /* Dades: etiqueta i valor en dues columnes; en el panell estret caben. */
  .sdp-explorador__dades {
    display: grid;
    gap: var(--sdp-space-2);
    font-size: var(--sdp-text-small);
  }
  .sdp-explorador__dades > div {
    display: grid;
    grid-template-columns: minmax(0, 11rem) minmax(0, 1fr);
    align-items: baseline;
    gap: var(--sdp-space-3);
  }
  .sdp-explorador__dades dt { font-weight: 700; }
  .sdp-explorador__dades dd { margin: 0; }

  /* Relacions i avisos: llistes sense pics, una fila per vora. «Vore la
     peça» és un botó canònic (--sdp-touch), arrimat a l'esquerra. */
  .sdp-explorador__relacions,
  .sdp-explorador__avisos {
    display: grid;
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .sdp-explorador__relacio,
  .sdp-explorador__avis {
    display: grid;
    justify-items: start;
    gap: var(--sdp-space-1);
    margin: 0;
    padding-block: var(--sdp-space-2);
    border-block-start: 1px solid var(--sdp-vora);
  }
  .sdp-explorador__relacio > p,
  .sdp-explorador__avis > p {
    margin: 0;
    font-size: var(--sdp-text-small);
    line-height: 1.6;
  }
  .sdp-explorador__relacio-text { overflow-wrap: anywhere; }
  .sdp-explorador__relacio-meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--sdp-space-2);
  }

  /* «Mostra'n N més»: plegable natiu amb zona tàctil sencera. */
  .sdp-explorador__mes > summary {
    display: flex;
    align-items: center;
    min-height: var(--sdp-touch);
    color: var(--sdp-accio-text);
    font-size: var(--sdp-text-small);
    font-weight: 700;
    cursor: pointer;
  }
  .sdp-explorador__mes > summary:focus-visible {
    outline: 3px solid var(--sdp-focus);
    outline-offset: 2px;
  }

  /* En ample, el detall a la dreta del graf: el canvas s'encongix (el
     ResizeObserver de BrainGraph) i cap node queda davall d'un panell. */
  @media (min-width: 64rem) {
    .sdp-explorador__marc { grid-template-columns: minmax(0, 1fr) minmax(20rem, 24rem); }
  }

  @media (max-width: 40rem) {
    .sdp-explorador__barra { padding-inline: var(--sdp-space-3); }
    .sdp-explorador__cerca.sdp-camp {
      grid-template-columns: minmax(0, 1fr);
      grid-template-areas:
        "etiqueta"
        "control"
        "ajuda";
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .sdp-explorador__grup > summary::after { transition: none; }
  }
}

/* ── NAVEGACIÓ · rail de la barra plegada i lliscar per recarregar ────── */
@layer components {

  /* Glif de navegació (NavGlyph): un emoji ocupa el lloc d'una icona de la
     mateixa mida, 18px a l'arbre i 20px al rail. Les icones de component
     ja duen la seua mida. */
  .sdp-nav-glyph {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: var(--sdp-text-h6);
    font-style: normal;
    line-height: 1;
  }

  /* Rail de la columna plegada (UniversalWorkspace): viu dins de la
     capçalera plegada (AppGridColumn), davall de l'expandir i de la roda
     (sdp-app-grid-shell §3); ocupa la resta de l'alçada i fa scroll si no
     hi cap. Icones transparents i blanques sobre el crom. */
  .sdp-workspace-rail {
    flex: 1 1 auto;
    align-self: stretch;
    min-height: 0;
    margin-top: var(--sdp-space-1);
    padding-top: var(--sdp-space-1);
    border-top: 1px solid var(--sdp-crom-vora-forta);
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: var(--sdp-crom-scroll) transparent;
  }

  /* Neutralitza la tipografia editorial de ul/li (sagnat, pic i marge).
     Les cel·les s'estiren de banda a banda de la columna i s'apilen sense
     separació (ordre del Mestre, 260927 vespre: «caixes sòlides, res de
     botons flotants»). */
  .sdp-workspace-rail__grup {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .sdp-workspace-rail__grup > li {
    margin: 0;
    padding: 0;
  }
  .sdp-workspace-rail__grup + .sdp-workspace-rail__grup {
    margin-top: var(--sdp-space-1);
    padding-top: var(--sdp-space-1);
    border-top: 1px solid var(--sdp-crom-vora-forta);
  }

  .sdp-workspace-rail__boto {
    display: flex;
    align-items: center;
    justify-content: center;
    /* Un <button> amb width auto s'encongix al contingut encara que siga
       flex: cal el 100% de la li (que ja va estirada) perquè la cel·la
       vaja de banda a banda de la columna. */
    width: 100%;
    height: var(--sdp-touch);
    padding: 0;
    border: 2px solid transparent;
    /* Cel·la del rail plegat: rectangle pur de banda a banda, com la fila
       desplegada (regla definitiva del Mestre, 260927 vespre). */
    border-radius: 0;
    background: transparent;
    color: var(--sdp-crom-text);
    font: inherit;
    line-height: 1;
    cursor: pointer;
    transition: background var(--sdp-t), color var(--sdp-t), border-color var(--sdp-t);
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-workspace-rail__boto:hover {
      background: var(--sdp-crom-hover);
    }
  }
  /* Actiu: el mateix blau de selecció de l'arbre desplegat
     (.sdp-workspace-nav-item, T62), amb la icona blanca (T62b). La vora
     va del color del fons: el document actiu també casa amb la regla de
     l'arrel, i sense açò duria un anell de Blau 400 dins del Blau 600. */
  .sdp-workspace-rail__boto[aria-current="page"],
  .sdp-workspace-rail--documents .sdp-workspace-rail__boto[aria-current="true"] {
    position: relative;
    border-color: var(--sdp-crom-seleccio-fons);
    background: var(--sdp-crom-seleccio-fons);
    color: var(--sdp-crom-seleccio-text);
  }
  /* T62b · El mateix marcador blanc de 3px que la fila desplegada
     (.sdp-workspace-nav-item[aria-current="page"]::before): a l'inici de
     línia de la cel·la, sense tocar-ne el coixí ni l'amplària. La cel·la
     porta una vora de 2px del color del fons i el pseudo-element es
     posiciona dins d'ella: els -2px el porten a la vora de fora, de dalt a
     baix. Contra el rail plegat fa 16,10:1 (tokens.css). */
  .sdp-workspace-rail__boto[aria-current="page"]::before,
  .sdp-workspace-rail--documents .sdp-workspace-rail__boto[aria-current="true"]::before {
    content: '';
    position: absolute;
    inset-block: -2px;
    inset-inline-start: -2px;
    inline-size: 3px;
    background: var(--sdp-crom-seleccio-text);
    pointer-events: none;
  }
  .sdp-workspace-rail__boto[aria-current="page"] svg,
  .sdp-workspace-rail--documents .sdp-workspace-rail__boto[aria-current="true"] svg {
    color: var(--sdp-crom-seleccio-text);
  }
  /* Arrel que conté la carpeta activa (una subcarpeta seleccionada): una
     vora, no un fons. Es queda en Blau 400 (--sdp-crom-seleccio-vora),
     que es veu sobre el rail; les xifres, a tokens.css. */
  .sdp-workspace-rail__boto[aria-current="true"] {
    border-color: var(--sdp-crom-seleccio-vora);
  }
  .sdp-workspace-rail__boto:focus-visible {
    outline: 2px solid var(--sdp-crom-focus);
    outline-offset: -2px;
  }
  .sdp-workspace-rail .sdp-nav-glyph {
    font-size: var(--sdp-text-h5);
  }

  /* Lliscar per recarregar (usePullToRefresh): l'indicador naix davall de
     la barra negra, amagat per ella i transparent; el hook el fa baixar amb
     el contingut mentre dura el gest. Sense transform en repòs: un
     transform al contingut trencaria els seus position: fixed. Sobreescriu
     el bloc antic .sdp-ptr-indicator de més amunt en este full. */
  .sdp-ptr-indicator {
    top: var(--sdp-alt-negra);
    height: var(--sdp-space-12);
    font-size: var(--sdp-text-small);
    opacity: 0;
    pointer-events: none;
    transform: translateY(-100%);
    transition: transform var(--sdp-t-lenta), opacity var(--sdp-t);
  }
  .sdp-ptr-indicator[data-estat="estirant"],
  .sdp-ptr-indicator[data-estat="llest"],
  .sdp-ptr-indicator[data-estat="recarregant"] {
    opacity: 1;
  }
  /* Mentre el dit estira, l'indicador el seguix sense retard. */
  .sdp-ptr-indicator[data-estat="estirant"],
  .sdp-ptr-indicator[data-estat="llest"] {
    transition: none;
  }
  .sdp-ptr-indicator[data-estat="llest"],
  .sdp-ptr-indicator[data-estat="recarregant"] {
    color: var(--sdp-text-titol);
  }
  /* Encastat (Gent de la Torre, ordre del Mestre 261004 11:11), la franja de
     l'amfitrió viu entre la barra negra i el contingut, i el hook fa baixar
     l'indicador apegat al contingut. Com la negra, la franja l'ha de tapar
     mentre naix: sense posició, quedava per davall de l'indicador (z-index
     10). Ni desplaçament ni vora nova: en repòs, píxel a píxel igual
     (els seus contorns de focus són interns, outline-offset negatiu). */
  .app-main > .sdp-amfitrio-franja {
    position: relative;
    z-index: 11;
  }

  .app-main__content[data-ptr="actiu"] {
    transition: none;
  }
  .app-main__content[data-ptr="solt"] {
    transition: transform var(--sdp-t-lenta);
  }

  @media (prefers-reduced-motion: reduce) {
    .sdp-ptr-indicator,
    .app-main__content[data-ptr="solt"],
    .sdp-workspace-rail__boto {
      transition: none;
    }
  }
}

@layer components {
  .sdp-workspace-nav-item__icon svg { width: 24px; height: 24px; }
  /* AAA (Q1, 261004): el text blanc de 14px sobre --sdp-accio feia 3,87:1;
     sobre la superfície de control, 9,21:1 (el hover, just davall, 7,20:1). */
  .sdp-classificacio-botonera > .sdp-boto, .sdp-copyright-selector {
    /* Q2 (261004) · sòl tàctil de 48px, com tot control (abans 24px). */
    min-height: var(--sdp-touch-min); height: auto; padding: 2px 8px; font-size: var(--sdp-text-meta);
    line-height: 1.4; border: 0; border-radius: var(--sdp-radi-boto);
    background: var(--sdp-accio-control); color: var(--sdp-sobre-accio); cursor: pointer;
  }
  /* Hover propi (revisió R2, 261004). «Categories» i «Emoticona» són
     .sdp-boto--secundari: el hover del secundari (0,3,0) hi posava
     --sdp-fons-subtil sota la lletra blanca, 1,18:1 mesurat. Ara el blau fort
     de control, 7,20:1 en clar i en fosc; els botons de drets, que no en
     tenien, responen igual. Només amb ratolí (Fase B). */
  @media (hover: hover) and (pointer: fine) {
    .sdp-classificacio-botonera > .sdp-boto:hover:not(:disabled),
    .sdp-copyright-selector:hover:not(:disabled) { background: var(--sdp-accio-control-hover); }
  }
  .sdp-classificacio-botonera > .sdp-boto svg { width: var(--sdp-icona-xs); height: var(--sdp-icona-xs); }
  .sdp-copyright-control { max-width: 100%; min-width: 0; }
  .sdp-copyright-selector, .page-title-copyright {
    display: block; max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  }
}
@layer components {
  .sdp-editor-tools { position: relative; z-index: var(--z-barra-negra); }
  .sdp-editor-tools__formats { position: relative; flex-wrap: nowrap; }
  .sdp-editor-tools__group--publicacio { margin-inline-start: auto; }
  .sdp-editor-tools__format-options[hidden] { display: none; }
  .sdp-editor-tools[data-compact="true"] .sdp-editor-tools__format-options:not([hidden]) {
    position: absolute; inset-block-start: 100%; inset-inline-start: 8px;
    z-index: var(--z-barra-negra); max-width: calc(100% - 16px);
    padding: 8px; border: 1px solid var(--sdp-crom-vora); background: var(--sdp-crom-fons);
    box-shadow: var(--sdp-ombra-flotant);
  }
}

@layer components {
  .sdp-copyright-control { display: flex; flex-wrap: wrap; gap: var(--sdp-space-2); }
  .sdp-copyright-selector { display: inline-flex; align-items: center; gap: 6px; }
  .sdp-copyright-selector, .sdp-note-taxonomy-button { padding-inline: 10px; }
  .sdp-workspace .app-grid-col-header .app-grid-col-header__plegable,
  .sdp-workspace .app-grid-col-header .app-grid-col-header__accio-text,
  .sdp-workspace .app-grid-col-header .app-grid-col-header__plegable svg,
  .app-sidebar-nav-footer .nav-item.nav-item--system { color: var(--sdp-crom-actiu-fons); }
  .page-title-logo { width: min(100%, 600px); min-width: min(100%, 260px); }
  /* Norma del Mestre, 261004 (logotips) · El logotip d'una altra entitat (una
     sola imatge, sovint quadrada): fins a 600x600 (skill sdp-universal-page
     §1.D). object-fit: contain ja hi és (layout.css). */
  .page-title-logo--entitat { max-height: 600px; }
  /* Norma del Mestre, 261004 (prompt 261004_1108, T2) · L'avatar redó de qui
     signa (una persona o la IA), centrat davant de l'H1: més menut que el
     logotip (--sdp-avatar-capcalera, 300px) i a l'ample de la capçalera en
     pantalla estreta. La caixa reserva el lloc abans que arribe la imatge.
     Amb onCanvia és un botó: la marca de la càmera diu que es pot canviar. */
  .page-title-avatar {
    position: relative; display: block;
    width: min(100%, var(--sdp-avatar-capcalera)); aspect-ratio: 1 / 1;
    margin: 0 auto var(--sdp-space-4); padding: 0; border: 0;
    border-radius: var(--sdp-radi-pastilla); background: var(--sdp-fons-subtil);
  }
  .page-title-avatar__imatge {
    display: block; width: 100%; height: 100%;
    border-radius: inherit; object-fit: cover;
  }
  .page-title-avatar--canvia { color: inherit; cursor: pointer; }
  .page-title-avatar__marca {
    position: absolute; inset-inline-end: var(--sdp-space-4); inset-block-end: var(--sdp-space-4);
    display: flex; align-items: center; justify-content: center;
    width: var(--sdp-touch); height: var(--sdp-touch);
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-accio); color: var(--sdp-sobre-accio);
    transition: background-color var(--sdp-t);
  }
  @media (hover: hover) and (pointer: fine) {
    .page-title-avatar--canvia:hover .page-title-avatar__marca { background: var(--sdp-accio-hover); }
  }
}

/* ── Ordres del Mestre, 260927 nit (T31, T32) ─────────────────────────── */
@layer components {
  /* T32 · les píndoles de configuració del document (drets d'autor, vista
     A4, portada) van centrades com la botonera de classificació: quan
     salten de línia en pantalla estreta, cada fila queda al centre de la
     targeta, no arrambada a l'esquerra. */
  .page-title-classificacio,
  .sdp-copyright-control { justify-content: center; }

  /* T31 · les regles de /realitat ara viuen al bloc T44. */
}

/* ── Ordres del Mestre, 260928 (T39–T47) ──────────────────────────────────
   Un bloc per tasca: cada tasca escriu només dins del seu. */

/* T39 · drets d'autor a pantalla completa dins de l'editor */
@layer components {
  /* T39 (ordre del Mestre, 260928) · «Drets d'autor» a pantalla completa dins
     de la columna de l'editor (drets/CopyrightPage.jsx). La closca s'amaga
     però continua MUNTADA: TipTap i l'autodesament no es desmunten. La vista
     porta el seu scroll (el detall del Bloc i del Perfil no en fa) i el peu
     amb «Desar autoria» queda sempre a la vista. Sense :has() ni inert. */
  .sdp-editor-shell-atomic.sdp-editor-shell-atomic--amagat { display: none; }
  .sdp-drets {
    display: flex;
    flex-direction: column;
    flex: 1 1 0;
    min-height: 0;
    min-width: 0;
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain;
    background: var(--sdp-fons-app);
    color: var(--sdp-text-cos);
  }
  .sdp-drets__cap,
  .sdp-drets__cos,
  .sdp-drets__peu {
    width: 100%;
    max-width: var(--sdp-measure);
    margin-inline: auto;
    padding-inline: var(--sdp-space-4);
  }
  .sdp-drets__cap {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--sdp-space-3);
    padding-block: var(--sdp-space-6) var(--sdp-space-4);
  }
  .sdp-drets__titol { margin: 0; font-size: var(--sdp-text-h2); line-height: 1.2; color: var(--sdp-text-titol); }
  .sdp-drets__titol:focus-visible { outline: 3px solid var(--sdp-focus); outline-offset: 2px; }
  .sdp-drets__intro,
  .sdp-drets__enllac,
  .sdp-drets__comptador,
  .sdp-drets__cc0 p { margin: 0; line-height: 1.6; }
  .sdp-drets__cos {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-6);
    padding-block-end: var(--sdp-space-8);
  }
  /* L'exemple de poble, davall de l'explicació de cada targeta. */
  .sdp-drets__exemple { display: block; margin-top: var(--sdp-space-2); font-style: italic; color: var(--sdp-text-suau); }
  /* L'acceptació irrevocable de CC0: separada per vora, sense ombra. */
  .sdp-drets__cc0 {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-3);
    padding: var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
  }
  .sdp-drets__peu {
    position: sticky;
    bottom: 0;
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: var(--sdp-space-3);
    margin-top: auto;
    padding-block: var(--sdp-space-3);
    border-block-start: 1px solid var(--sdp-vora);
    background: var(--sdp-fons-app);
  }
  /* Amb la barra mòbil flotant (nav.mobile-nav, fins a 1023px, layout.css) el
     peu quedava davall d'ella i tapava «Desar autoria». El mateix peu
     s'allarga per davall de la barra (no depén del padding del contenidor de
     scroll, que no tots els navegadors de la baseline compten). */
  :where(.sdp-root.is-compact) .sdp-drets__peu { padding-block-end: calc(var(--sdp-space-3) + var(--sdp-alt-nav-mobil) + env(safe-area-inset-bottom, 0px)); }
  /* PerfilShell.css pinta de blau tot .sdp-boto (deute previ): com el peu dels
     diàlegs, la vista torna les seues varietats (0,2,0), també al Perfil. */
  .sdp-drets .sdp-boto--secundari { background: var(--sdp-fons-targeta); color: var(--sdp-text-titol); border: 2px solid var(--sdp-vora-control); }
  .sdp-drets .sdp-boto--fantasma { background: transparent; color: var(--sdp-accio-text); border: 2px solid transparent; }
  @media (hover: hover) and (pointer: fine) {
    .sdp-drets .sdp-boto--secundari:hover:not(:disabled) { background: var(--sdp-fons-subtil); }
    .sdp-drets .sdp-boto--fantasma:hover:not(:disabled) { background: var(--sdp-fons-subtil); }
  }
  /* L'espècimen del catàleg: una columna d'editor simulada, amb alçada fixa. */
  .sdp-especimen__columna {
    display: flex;
    flex-direction: column;
    block-size: 40rem;
    overflow: hidden;
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
  }
}

/* T40 i T41 · finestra de la barra taronja: data de publicació i visibilitat */
@layer components {
  /* SDP:T40-T41 · T40–T41 (ordre del Mestre, 260928) · La finestra flotant
     ÚNICA de la barra taronja (Dialeg lloc="barra"): la data de publicació
     (SelectorDataHora) i la visibilitat (SelectorVisibilitat), amb la mateixa
     anatomia. En escriptori s'ancora dalt a la dreta, davall de les barres;
     en mòbil (≤720px) hereta el full inferior de components.css. És un
     <dialog> modal: viu a la capa superior, sense cap z-index. Pot nàixer
     dins de la barra taronja: es talla l'herència de lletra i de nowrap de
     la barra. Només vh: dvh no és Baseline 2022. */
  .sdp-dialeg--barra { font-size: var(--sdp-text-small); white-space: normal; text-align: start; }
  @media (min-width: 721px) {
    .sdp-dialeg.sdp-dialeg--barra {
      margin: var(--sdp-alt-barres) var(--sdp-space-4) auto auto;
      max-height: min(calc(100vh - var(--sdp-alt-barres) - var(--sdp-space-8)), 48rem);
    }
  }
  /* Correcció C20 (260928) · En una pantalla curta, ancorada davall de les
     barres, la finestra deixava l'«Hora» i els avisos davall del plec: quan
     no hi cap, puja fins dalt. Només vh (Baseline 2022). */
  @media (min-width: 721px) and (max-height: 760px) {
    .sdp-dialeg.sdp-dialeg--barra {
      margin-top: var(--sdp-space-4);
      max-height: calc(100vh - var(--sdp-space-8));
    }
  }

  /* Correcció C15 (260928) · En tema fosc --sdp-focus (primary-400) sobre
     --sdp-accent fa ≈1,26:1 (WCAG 1.4.11 i 2.4.7). A la barra taronja
     l'anell pren el color del text de la barra (≈7:1 en els dos temes), com
     base.css fa amb la negra i la blava. Els <dialog> que hi naixen tenen
     el fons del tema: dins, l'anell de sempre. */
  section.bar-orange .bar-actions :focus-visible { outline-color: var(--sdp-sobre-accent); }
  section.bar-orange .bar-actions dialog :focus-visible { outline-color: var(--sdp-focus); }
  /* Ordre del Mestre, 261001 · La boina de les targetes (.sp-card-header,
     UniversalCard) té el mateix fons --sdp-accent i el mateix defecte que la
     C15: en tema fosc l'anell de la pastilla (ara un botó que porta al
     Calendari), del pin i de l'enllaç d'autoria feia ≈1,26:1. El mateix anell
     que la barra de pàgina, i la mateixa excepció per als <dialog>. Com la
     C15, val en els dos temes: en clar l'anell passa de --sdp-focus (≈3,4:1)
     a --sdp-sobre-accent (≈7:1), i només es veu amb el focus de teclat.
     L'enllaç d'autoria de la barra de PÀGINA és germà de .bar-actions (fill
     directe de la secció) i la C15 no l'abastava: el mateix anell, perquè un
     mateix control no en tinga dos segons on es pinta. */
  .sp-card-header :focus-visible { outline-color: var(--sdp-sobre-accent); }
  .sp-card-header dialog :focus-visible { outline-color: var(--sdp-focus); }
  section.bar-orange > .sp-card-author-link:focus-visible { outline-color: var(--sdp-sobre-accent); }

  /* T40 · El mes en xicotet (GraellaMes compacta): la mateixa taula que la
     Consola, sense ratlles ni fons de fila; cada dia és un botó de --sdp-touch
     (7 × 44px cabien al full inferior de 360px; amb el sòl de 48px de la Q2,
     261004, en fan 336, i en un mòbil de 360px cal comprovar-ho). */
  .sdp-calendari { display: flex; flex-direction: column; gap: var(--sdp-space-3); }
  .sdp-calendari .sdp-camp { margin-bottom: 0; }
  .sdp-calendari__navegacio { display: flex; align-items: center; justify-content: space-between; gap: var(--sdp-space-2); }
  .sdp-calendari--compacte { border-block-start: 0; }
  .sdp-calendari--compacte table { width: 100%; }
  .sdp-calendari--compacte caption { padding-block-end: var(--sdp-space-2); font-weight: 700; color: var(--sdp-text-titol); }
  .sdp-calendari--compacte th,
  .sdp-calendari--compacte td { padding: 0; text-align: center; vertical-align: middle; border-block-end: 0; }
  .sdp-calendari--compacte thead th { background: transparent; font-size: var(--sdp-text-meta); color: var(--sdp-text-suau); }
  .sdp-calendari--compacte tbody tr { background: transparent; }
  .sdp-calendari__dia {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--sdp-touch);
    height: var(--sdp-touch);
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: var(--sdp-radi-boto);
    background: transparent;
    color: var(--sdp-text-cos);
    font: inherit;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-calendari__dia:hover { background: var(--sdp-fons-subtil); }
  }
  /* Hui es llig sense color: negreta i subratllat. El triat, amb el color d'acció. */
  .sdp-calendari__dia[aria-current="date"] { font-weight: 800; text-decoration: underline; text-underline-offset: var(--sdp-space-1); }
  .sdp-calendari__dia[aria-pressed="true"] { background: var(--sdp-accio-control); color: var(--sdp-sobre-accio); }
  .sdp-calendari__dia:focus-visible { outline: 3px solid var(--sdp-focus); outline-offset: 2px; }

  /* SDP:T6-T7 · T6-T7 (ordre del Mestre, 260930) · El mes gran amb
     esdeveniments (CalendariEsdeveniments): l'Agenda del Mur i el Calendari
     de la Consola. Tot va confinat a .sdp-calendari--gran i a la taula de la
     pàgina (.sdp-calendari__taula): cap regla global a taules, insígnies ni
     botons (el mes compacte i la resta de taules no canvien, i els botons
     conserven el contrast de control). Set columnes iguals, línies fines
     (--sdp-vora), sense zebra ni hover taronja, i píndoles d'amplària
     uniforme amb el text sencer. */
  .sdp-calendari--gran table { table-layout: fixed; min-inline-size: 42rem; }
  .sdp-calendari--gran thead th,
  .sdp-calendari__taula thead th { border-block-end-color: var(--sdp-vora); }
  /* La taula de la pàgina del Calendari (Tasques per cadència): només les vores. */
  .sdp-calendari__taula .sdp-insignia { border-color: var(--sdp-vora); }
  .sdp-calendari--gran th + th,
  .sdp-calendari--gran td + td { border-inline-start: 1px solid var(--sdp-vora); }
  .sdp-calendari--gran tbody tr { background: transparent; }
  .sdp-calendari--gran td { overflow-wrap: anywhere; }
  .sdp-calendari--gran .sdp-calendari__pindola {
    display: flex;
    align-items: center;
    inline-size: 100%;
    margin-block-start: var(--sdp-space-1);
    padding: 0;
    border: none;
    font-size: var(--sdp-text-meta);
    font-weight: 500;
    line-height: 1.5;
    text-align: start;
  }
  /* La píndola per defecte, sense Insignia: el to neutre. */
  .sdp-calendari__pindola:not(.sdp-insignia) { background: transparent; color: var(--sdp-text-cos); }
  .sdp-calendari__pindola:not(.sdp-insignia)::before {
    content: "•";
    color: var(--sdp-accio-control);
    margin-inline-end: var(--sdp-space-1);
    font-weight: 800;
  }
  /* L'Agenda: la barra «‹ Hui ›» i cada dia, un botó que ocupa la cel·la. */
  .sdp-calendari__barra { display: flex; flex-wrap: wrap; align-items: center; gap: var(--sdp-space-2); margin-block: var(--sdp-space-4) var(--sdp-space-2); }
  /* Pantalla completa (ordre del Mestre, 261001) · A /calendari, el botó
     d'entrar tanca la fila «‹ Hui ›», a la dreta. El Mur no el porta. */
  .sdp-calendari__barra > .sdp-pantalla-completa__entra { margin-inline-start: auto; }
  .sdp-calendari--triable td { padding: 0; }
  .sdp-calendari__cella {
    display: flex;
    flex-wrap: wrap;
    align-content: flex-start;
    gap: 0 var(--sdp-space-1);
    inline-size: 100%;
    min-block-size: 5rem;
    margin: 0;
    padding: var(--sdp-space-1) var(--sdp-space-2);
    border: 2px solid transparent;
    border-radius: 0;
    background: transparent;
    color: var(--sdp-text-cos);
    font: inherit;
    text-align: start;
    cursor: pointer;
  }
  .sdp-calendari__numero { flex-basis: 100%; }
  @media (hover: hover) {
    .sdp-calendari__cella:hover { background: var(--sdp-fons-subtil); }
  }
  /* El dia triat (el ?date= del Mur): vora i fons d'acció, sense ombra. */
  .sdp-calendari__cella[aria-pressed="true"] { border-color: var(--sdp-accio-control); background: var(--sdp-accio-subtil); }
  .sdp-calendari__cella:focus-visible { outline: 3px solid var(--sdp-focus); outline-offset: -3px; }
  /* Pantalla estreta: la graella cap sense scroll horitzontal. Les píndoles
     es fan punts del color del seu estat; el text s'amaga a la vista però no
     al lector de pantalla (res de display: none), i el detall queda a les
     targetes del Mur o a la taula de la Consola. */
  @media (max-width: 40rem) {
    .sdp-calendari--gran table { min-inline-size: 0; }
    .sdp-calendari--gran th,
    .sdp-calendari--gran td { padding: var(--sdp-space-1); }
    .sdp-calendari--triable td { padding: 0; }
    .sdp-calendari--gran td > div { display: inline-block; }
    .sdp-calendari--gran .sdp-calendari__pindola {
      display: inline-block;
      inline-size: var(--sdp-space-2);
      block-size: var(--sdp-space-2);
      margin: var(--sdp-space-1) var(--sdp-space-1) 0 0;
      padding: 0;
      border: 0;
      overflow: hidden;
      white-space: nowrap;
      text-indent: 200%;
      background: currentColor;
    }
    .sdp-calendari__cella { min-block-size: var(--sdp-touch); padding: var(--sdp-space-1); }
  }
  /* «Sense data» sense res a buidar: no es desactiva (el focus no cau), s'apaga. */
  .sdp-selector-data .sdp-dialeg__peu .sdp-boto[aria-disabled="true"] { opacity: 0.6; cursor: not-allowed; }

  /* T41 · El selector de visibilitat: les dues targetes de GrupOpcions (T44)
     i, davant, qui signa la publicació. */
  .sdp-selector-visibilitat__com { margin: 0 0 var(--sdp-space-3); }
  .sdp-selector-visibilitat .sdp-grup--targetes { margin-bottom: var(--sdp-space-3); }
}

/* T10 · vistes Setmana i Mes del calendari (esquelet) */
@layer components {
  /* SDP:calendari-vistes · T10 (ordre del Mestre, 261001) · L'esquelet de les
     vistes Setmana i Mes a l'estil Google Calendar (VistaSetmana, VistaMes i
     NavegacioPeriode). Només estructura: graella i posicionament amb calc()
     de les propietats --sdp-cal-* que cada bloc rep des d'una ref
     (usePropietatsCss), mai d'un style en JSX. Les de línia de graella
     (--sdp-cal-col-inici, --sdp-cal-col-fi, --sdp-cal-carril) ja arriben
     1-based. Colors, només els tokens que ja fa servir el mes gran
     (.sdp-calendari--gran); cap ombra; el color i la línia d'«ara» esperen
     les captures del Mestre. La graella de 24 h creix dins del visor: cap
     scroll propi (Pedra Seca §1). Les llistes es reinicien (el ol i el li
     editorials de base.css porten sagnat i marge). */

  /* Fase visual (prompt 261001_0445) · Àlies de color i de mètrica de totes
     les vistes noves, derivats de tokens semàntics existents. Es declaren dins
     de l'App (.sdp-root): el tema fosc els resol sol, sense cap redefinició.
     Cap hex ni primitiu. */
  /* El color d'un acte segons la seua font (classeDeFont, utils/disposicioCalendari.js). */

  /* Navegació (NavegacioPeriode). Fase visual (prompt 261001_0445) · «Hui»,
     les fletxes, el títol i el selector de vista, en l'ordre de les captures;
     en un contenidor estret la barra s'apila sola (flex-wrap). */
  .sdp-cal-navegacio { display: flex; flex-wrap: wrap; align-items: center; gap: var(--sdp-space-2); margin-block: var(--sdp-space-4) var(--sdp-space-3); }
  /* Les fletxes: només icona, 44×44 (el Boto ja fa --sdp-touch d'alt); sense
     el gap del text buit, la icona queda centrada. --sdp-accio-text: 9,21:1
     en clar i 10,32:1 en fosc sobre la targeta. */
  .sdp-cal-navegacio__fletxa { inline-size: var(--sdp-touch); min-inline-size: var(--sdp-touch); padding: 0; gap: 0; }
  /* PerfilShell.css pinta de blau tot .sdp-boto i hi torna a posar el farciment
     de 24px (deute previ; carrega després, a la mateixa capa): sense context, el
     farciment deixava la icona de la fletxa a 0px d'ample i «Hui» en blau. Com
     .sdp-drets, la navegació torna les seues varietats amb (0,2,0). */
  .sdp-cal-navegacio .sdp-boto--secundari { background: var(--sdp-fons-targeta); color: var(--sdp-text-titol); border: 2px solid var(--sdp-vora-control); }
  .sdp-cal-navegacio .sdp-boto--fantasma { background: transparent; color: var(--sdp-accio-text); border: 2px solid transparent; }
  @media (hover: hover) and (pointer: fine) {
    .sdp-cal-navegacio .sdp-boto--secundari:hover:not(:disabled) { background: var(--sdp-fons-subtil); }
    .sdp-cal-navegacio .sdp-boto--fantasma:hover:not(:disabled) { background: var(--sdp-fons-subtil); }
  }
  .sdp-cal-navegacio .sdp-cal-navegacio__fletxa { padding: 0; }
  /* El títol del període, gran i de pes normal com a les captures
     (--sdp-text-titol: 19,42:1 en clar i 17,91:1 en fosc). */
  .sdp-cal-navegacio__titol { flex: 1 1 12rem; min-inline-size: 0; margin: 0; font-size: var(--sdp-text-h5); font-weight: 400; line-height: 1.2; color: var(--sdp-text-titol); }
  /* El selector de vista: el PillToggle de sèrie sense ombra ni marge,
     alineat a l'inici i amb radi de targeta (en estret s'apila en dues files).
     La premuda va en --sdp-accio-control (text blanc a 9,21:1; el --sdp-accio
     de sèrie en fa 3,87:1) i subratllada: en fosc el fons fa 1,95:1 sobre la
     targeta, i l'estat s'ha de llegir també sense color (WCAG 1.4.1). */
  .sdp-cal-vistes { justify-content: flex-start; gap: var(--sdp-space-1); margin: 0; padding: var(--sdp-space-1); border-radius: var(--sdp-radi-m); box-shadow: none; }
  .sdp-cal-vistes .sdp-pindola__opcio { padding-inline: var(--sdp-space-3); }
  .sdp-cal-vistes .sdp-pindola__opcio[aria-pressed="true"] {
    background: var(--sdp-accio-control);
    color: var(--sdp-sobre-accio);
    text-decoration: underline;
    text-underline-offset: var(--sdp-space-1);
  }

  /* Agenda (VistaAgenda). Fase visual (prompt 261001_0445) · La superfície de
     targeta de la setmana i del mes. Cada dia és una fila flexible: la data a
     l'esquerra (7rem) i les files dels actes a la dreta (16rem com a mínim);
     en un contenidor estret la data passa damunt (flex-wrap, cap media
     query). Cap scroll propi: la llista creix dins del visor. */
  .sdp-cal-agenda {
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
  }
  .sdp-cal-agenda__dies { margin: 0; padding: 0; list-style: none; }
  .sdp-cal-agenda__dia {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    gap: var(--sdp-space-1) var(--sdp-space-4);
    margin: 0;
    padding: var(--sdp-space-3) var(--sdp-space-4);
  }
  .sdp-cal-agenda__dia + .sdp-cal-agenda__dia { border-block-start: 1px solid var(--sdp-vora); }
  /* La data: el número en un cercle que només es pinta hui (invers: 19,42:1
     en clar i 18,01:1 en fosc) i «oct., dj.» en --sdp-text-suau (9,09:1 i
     12,49:1, des del 261004). Reinicia l'encapçalament editorial, també la ratlla i el
     coixí de baix que base.css posa a tot h3. */
  .sdp-cal-agenda__cap {
    flex: 0 0 var(--sdp-cal-agenda-data);
    display: flex;
    align-items: center;
    gap: var(--sdp-space-2);
    margin: 0;
    padding-block-end: 0;
    border-block-end: 0;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
    font-weight: 400;
    line-height: 1.2;
  }
  .sdp-cal-agenda__numero {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--sdp-cal-cercle);
    block-size: var(--sdp-cal-cercle);
    border-radius: var(--sdp-radi-pastilla);
    color: var(--sdp-text-titol);
    font-size: var(--sdp-text-h5);
    font-variant-numeric: tabular-nums;
    line-height: 1;
  }
  .sdp-cal-agenda__data { white-space: nowrap; }
  .sdp-cal-agenda__dia[aria-current="date"] .sdp-cal-agenda__numero { background: var(--sdp-cal-hui-fons); color: var(--sdp-cal-hui-text); font-weight: 700; }
  .sdp-cal-agenda__dia[aria-current="date"] .sdp-cal-agenda__data { color: var(--sdp-text-titol); font-weight: 700; }
  /* Les files (no interactives): el punt, l'hora en una columna fixa amb
     xifres tabulars (--sdp-text-cos: 11,20:1 i 15,20:1) i el títol
     (--sdp-text-titol: 19,42:1 i 17,91:1). */
  .sdp-cal-agenda__actes { flex: 1 1 16rem; min-inline-size: 0; margin: 0; padding: 0; list-style: none; }
  /* Sense el sagnat de 4px del li editorial: el punt de cada fila queda a
     l'inici, alineat amb el de la línia d'«ara». */
  .sdp-cal-agenda__acte {
    display: grid;
    grid-template-columns: var(--sdp-space-3) var(--sdp-cal-agenda-hora) minmax(0, 1fr);
    align-items: center;
    column-gap: var(--sdp-space-3);
    margin: 0;
    padding: var(--sdp-space-1) 0;
    font-size: var(--sdp-text-small);
    line-height: 1.6;
  }
  /* El punt, del color de la vora de la font: almenys 3:1 sobre la targeta en
     clar i en fosc (WCAG 1.4.11). L'agenda de Sollutia, en anell: és una font
     externa, i la forma també ho diu. */
  .sdp-cal-agenda__punt {
    inline-size: var(--sdp-space-3);
    block-size: var(--sdp-space-3);
    border: 2px solid var(--sdp-cal-bloc-vora);
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-cal-bloc-vora);
  }
  .sdp-cal-font--agenda .sdp-cal-agenda__punt { background: transparent; }
  .sdp-cal-agenda__hora { color: var(--sdp-text-cos); font-variant-numeric: tabular-nums; white-space: nowrap; }
  .sdp-cal-agenda__titol { min-inline-size: 0; color: var(--sdp-text-titol); overflow-wrap: anywhere; }
  /* La línia d'«ara» dins del grup de hui: --sdp-cal-ara (5,51:1 en clar i
     8,28:1 en fosc), de 2px, amb el punt alineat amb els de les files. */
  .sdp-cal-agenda__ara { position: relative; block-size: 2px; margin: 0; padding: 0; background: var(--sdp-cal-ara); list-style: none; }
  .sdp-cal-agenda__ara::before {
    content: '';
    position: absolute;
    inset-inline-start: calc(var(--sdp-space-3) / 2);
    inset-block-start: 50%;
    inline-size: var(--sdp-space-3);
    block-size: var(--sdp-space-3);
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-cal-ara);
    transform: translate(-50%, -50%);
  }
  .sdp-cal-agenda > p,
  .sdp-cal-agenda__buit { margin: 0; padding: var(--sdp-space-3) var(--sdp-space-4); color: var(--sdp-text-cos); }

  /* Any (VistaAny). Fase visual (prompt 261001_0445) · Dotze mesos en una
     graella auto-fill: les columnes les decidix l'amplada del contenidor, cap
     media query de viewport. El mínim d'un mes és set dies de
     --sdp-cal-any-dia: --sdp-touch en tàctil (cap dia baixa dels 44px; en un
     mòbil, un mes per fila) i 2rem amb ratolí (la densitat compacta: hi caben
     quatre mesos, com a la captura). El farciment lateral és de 8px perquè
     els 44px valguen en un mòbil de 360px: 360 − 2 × 16 (marge de la pàgina)
     − 2 × 1 (vora) − 2 × 8 = 310px ≥ 7 × 44px. Amb el sòl de 48px (Q2,
     261004) set dies en demanen 336: en eixe mòbil el min(100%, …) de la
     graella els deixa en 44,3px, sense desbordar. */
  .sdp-cal-any {
    padding: var(--sdp-space-4) var(--sdp-space-2);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
  }
  .sdp-cal-any__mesos {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(100%, calc(7 * var(--sdp-cal-any-dia))), 1fr));
    gap: var(--sdp-space-6) var(--sdp-space-8);
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .sdp-cal-any__mes { min-inline-size: 0; margin: 0; padding: 0; }
  /* El nom del mes: sense la ratlla ni el coixí de baix del h3 editorial. */
  .sdp-cal-any__nom {
    margin: 0 0 var(--sdp-space-2);
    padding-inline-start: var(--sdp-space-2);
    padding-block-end: 0;
    border-block-end: 0;
    color: var(--sdp-text-titol);
    font-size: var(--sdp-text-small);
    font-weight: 700;
    line-height: 1.2;
    text-transform: capitalize;
  }
  /* La taula de cada mes desfà dos defectes de sdp.css: en pantalla estreta
     (max-width: 40rem) tota taula passa a bloc amb scroll horitzontal propi
     (Llei de Scroll), i les setmanes parelles es ratllen i la fila es pinta
     amb el ratolí damunt (sense zebra ni hover taronja, com els calendaris
     d'ara). */
  .sdp-cal-any__graella { display: table; inline-size: 100%; margin: 0; overflow: visible; border-collapse: collapse; table-layout: fixed; }
  .sdp-cal-any__graella tbody tr { background: transparent; }
  .sdp-cal-any__graella th,
  .sdp-cal-any__graella td { padding: 0; border: 0; background: transparent; text-align: center; }
  .sdp-cal-any__graella th { padding-block-end: var(--sdp-space-1); color: var(--sdp-text-suau); font-size: var(--sdp-text-meta); font-weight: 400; line-height: 1.2; }
  .sdp-cal-any__graella abbr { text-decoration: none; }
  /* El dia: tota la cel·la és el botó (≥ --sdp-cal-any-dia) i el número va
     dins d'un cercle que només es pinta hui (invers) o al triat (el fons i la
     vora d'acció de la setmana i del mes). Els veïns, en --sdp-text-suau.
     L'amplada la decidix la cel·la: sense el min-width de 44px que base.css
     posa a tot botó, que amb ratolí desbordaria la cel·la de 2rem i taparia
     el dia veí (el mínim tàctil el garantix el minmax de la graella). */
  .sdp-cal-any__dia {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    inline-size: 100%;
    min-inline-size: 0;
    min-block-size: var(--sdp-cal-any-dia);
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: var(--sdp-radi-s);
    background: transparent;
    color: var(--sdp-text-cos);
    font: inherit;
    font-size: var(--sdp-text-meta);
    font-variant-numeric: tabular-nums;
    line-height: 1;
  }
  button.sdp-cal-any__dia { cursor: pointer; }
  .sdp-cal-any__dia--fora { color: var(--sdp-text-suau); }
  .sdp-cal-any__numero {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    inline-size: var(--sdp-cal-cercle);
    block-size: var(--sdp-cal-cercle);
    border: 2px solid transparent;
    border-radius: var(--sdp-radi-pastilla);
  }
  /* El punt de «té actes», amb el color del text del dia (11,20:1 i 15,20:1);
     sempre reserva el lloc perquè els números no ballen. */
  .sdp-cal-any__punt { flex: none; inline-size: var(--sdp-space-1); block-size: var(--sdp-space-1); border-radius: var(--sdp-radi-pastilla); background: currentColor; }
  .sdp-cal-any__punt--buit { visibility: hidden; }
  @media (hover: hover) {
    button.sdp-cal-any__dia:not([aria-current="date"]):not(.sdp-cal-any__dia--triat):hover .sdp-cal-any__numero { background: var(--sdp-fons-subtil); }
  }
  /* Triat: vora --sdp-accio-text (9,21:1 i 10,32:1) i text --sdp-text-titol
     sobre --sdp-accio-subtil (18,13:1 i 15,52:1). Hui guanya el fons. */
  .sdp-cal-any__dia--triat .sdp-cal-any__numero { border-color: var(--sdp-accio-text); background: var(--sdp-accio-subtil); color: var(--sdp-text-titol); }
  .sdp-cal-any__dia[aria-current="date"] .sdp-cal-any__numero { background: var(--sdp-cal-hui-fons); color: var(--sdp-cal-hui-text); font-weight: 700; }
  .sdp-cal-any__dia:focus-visible { outline: 3px solid var(--sdp-focus); outline-offset: -3px; }
  .sdp-cal-any > p { margin: var(--sdp-space-4) 0 0; color: var(--sdp-text-cos); }

  /* El dia: la capçalera de la setmana i la cel·la del mes. Botó si es pot triar. */
  .sdp-cal-dia {
    display: flex;
    flex-direction: column;
    align-items: center;
    inline-size: 100%;
    min-block-size: var(--sdp-touch);
    margin: 0;
    padding: var(--sdp-space-1);
    border: 2px solid transparent;
    border-radius: 0;
    background: transparent;
    color: var(--sdp-text-cos);
    font: inherit;
    text-align: center;
  }
  button.sdp-cal-dia { cursor: pointer; }
  .sdp-cal-dia__nom { font-size: var(--sdp-text-meta); color: var(--sdp-text-suau); text-decoration: none; }
  .sdp-cal-dia__numero { font-weight: 700; }
  /* Hui es llig sense color: negreta i subratllat. El triat, amb el color d'acció. */
  .sdp-cal-dia[aria-current="date"] .sdp-cal-dia__numero { font-weight: 800; text-decoration: underline; text-underline-offset: var(--sdp-space-1); }
  @media (hover: hover) {
    .sdp-cal-dia[aria-pressed="false"]:hover { background: var(--sdp-fons-subtil); }
  }
  /* Fase visual (prompt 261001_0445) · La vora del triat és --sdp-accio-text:
     en clar és el mateix blau que --sdp-accio-control (9,21:1 sobre la
     targeta); en fosc, --sdp-accio-control queda en 1,95:1 sobre la targeta i
     no marca l'estat (WCAG 1.4.11), i --sdp-accio-text en fa 10,32:1. */
  .sdp-cal-dia[aria-pressed="true"] { border-color: var(--sdp-accio-text); background: var(--sdp-accio-subtil); }
  .sdp-cal-dia:focus-visible { outline: 3px solid var(--sdp-focus); outline-offset: -3px; }
  /* El punt de «té actes» (la tira de la setmana): reserva el lloc sempre, i
     només el ple es pinta (--sdp-text-suau: 9,09:1 en clar i 12,49:1 en fosc
     sobre la targeta; 8,49:1 i 10,82:1 sobre el triat; tests/
     contrast_calendari_setmana.test.mjs). */
  .sdp-cal-dia__punt { flex: none; inline-size: var(--sdp-space-2); block-size: var(--sdp-space-2); border-radius: var(--sdp-radi-pastilla); }
  .sdp-cal-dia__punt--ple { background: var(--sdp-text-suau); }

  /* Barres per carrils: la franja de tot el dia i les files del mes. */
  .sdp-cal-setmana__barres,
  .sdp-cal-mes__barres {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    grid-auto-rows: var(--sdp-cal-alt-carril);
    row-gap: var(--sdp-space-1);
    margin: 0;
    padding: 0;
    list-style: none;
  }
  /* Fase visual · La barra porta el color de la seua font (classeDeFont):
     --sdp-cal-bloc-*, declarats a l'arrel de cada vista (per defecte, el de
     publicació). Les vistes hi afigen la seua forma. */
  .sdp-cal-barra {
    grid-column: var(--sdp-cal-col-inici) / var(--sdp-cal-col-fi);
    grid-row: var(--sdp-cal-carril);
    overflow: hidden;
    margin: 0 var(--sdp-space-1);
    padding: 0 var(--sdp-space-1);
    border: 1px solid var(--sdp-cal-bloc-vora);
    border-radius: var(--sdp-radi-s);
    background: var(--sdp-cal-bloc-fons);
    color: var(--sdp-cal-bloc-text);
    font-size: var(--sdp-text-meta);
    font-weight: 700;
    line-height: 1.4;
    white-space: nowrap;
    text-overflow: ellipsis;
  }
  /* Ve de la fila d'abans o seguix en la de després: la vora d'eixe costat, oberta. */
  .sdp-cal-barra--abans { margin-inline-start: 0; border-start-start-radius: 0; border-end-start-radius: 0; }
  .sdp-cal-barra--despres { margin-inline-end: 0; border-start-end-radius: 0; border-end-end-radius: 0; }
  /* Un acte amb hora d'un sol dia, al mes: l'hora i el títol, sense caixa. */
  .sdp-cal-barra--punt { border-color: transparent; background: transparent; font-weight: 400; }

  /* Setmana (VistaSetmana). Fase visual (prompt 261001_0445) · Una superfície
     de targeta amb la capçalera de dies enganxosa, la franja de tot el dia i
     la graella d'hores. El mode el decidix l'amplada del contenidor (el JS hi
     posa --tira per davall de 41,5em), mai una media query de viewport.
     overflow: clip retalla els cantons de la superfície (també els de la
     capçalera, que és quadrada) sense fer cap contenidor de scroll: el sticky
     continua funcionant, com al mes (Safari 16, Chrome 90, Firefox 81). El
     rang dinàmic (--sdp-cal-hora-inicial i --sdp-cal-hores) arriba a la
     graella des d'una ref. */
  .sdp-cal-setmana {
    /* L'alçada de les barres enganxoses de damunt. D2 (barra taronja
       universal, ordre del Mestre 261004) · Tota pàgina porta ara la blava I
       la taronja, enganxada just davall (top: var(--sdp-alt-accio)), en tots
       els modes de chrome i en tots els amples: a /calendari (chrome
       'system', layout 'contained') i al catàleg (chrome 'context') el sostre
       són les dues barres. Abans era la blava sola i la capçalera de dies
       quedava 58px davall de la taronja. La regla de l'espècimen i la seua
       @media de 720px (que replicava la T38, revertida: la taronja ja no
       s'amaga en mòbil) ja no calen: valien el mateix o eren falses. */
    overflow: clip;
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
  }
  /* Pantalla completa (ordre del Mestre, 261001) · Dins del diàleg no hi ha
     cap barra damunt: la capçalera de dies s'enganxa a dalt del visor, que és
     el que fa scroll. (0,3,0): guanya a la de la base sense dependre de
     l'ordre (abans, també a la de l'espècimen, que ja no hi és). */

  .sdp-cal-setmana__capcal {
    position: sticky;
    inset-block-start: var(--sdp-cal-sostre);
    z-index: 2;
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    margin: 0;
    padding: 0;
    padding-inline-start: var(--sdp-cal-marge);
    list-style: none;
    border-block-end: 1px solid var(--sdp-vora);
    background: var(--sdp-fons-targeta);
  }
  .sdp-cal-setmana__cap { margin: 0; padding: 0; }
  /* La capçalera del dia: l'abreviatura xicoteta i suau i, davall, el número
     gran dins d'un cercle que només es pinta hui (invers: 19,42:1 en clar i
     18,01:1 en fosc). El triat porta el fons i la vora d'acció de la base. */
  .sdp-cal-setmana .sdp-cal-dia { gap: var(--sdp-space-1); padding-block: var(--sdp-space-2); border-radius: var(--sdp-radi-s); }
  .sdp-cal-setmana .sdp-cal-dia__nom { font-weight: 700; line-height: 1.2; }
  .sdp-cal-setmana .sdp-cal-dia__numero {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: var(--sdp-cal-cercle);
    block-size: var(--sdp-cal-cercle);
    border-radius: var(--sdp-radi-pastilla);
    color: var(--sdp-text-titol);
    font-size: var(--sdp-text-h4);
    font-weight: 400;
    line-height: 1;
  }
  .sdp-cal-setmana .sdp-cal-dia[aria-current="date"] .sdp-cal-dia__nom { color: var(--sdp-text-titol); }
  .sdp-cal-setmana .sdp-cal-dia[aria-current="date"] .sdp-cal-dia__numero {
    background: var(--sdp-cal-hui-fons);
    color: var(--sdp-cal-hui-text);
    font-weight: 700;
    text-decoration: none;
  }
  /* La tira (contenidor estret): set botons de dia sense el marge de les hores
     (a 343px, 49px cadascun) i una sola columna. Cap pista baixa de
     --sdp-touch: per davall de 7 × --sdp-touch (308px amb 44; 336px amb el
     sòl de 48 de la Q2, 261004) el darrer dia passa a una segona fila en lloc
     d'encavalcar-se o d'eixir de la vora (auto-fit plega les pistes buides i
     les set ocupen tota l'amplada). */
  .sdp-cal-setmana--tira .sdp-cal-setmana__capcal { grid-template-columns: repeat(auto-fit, minmax(var(--sdp-touch), 1fr)); padding-inline-start: 0; }
  .sdp-cal-setmana--tira .sdp-cal-dia { padding-block: var(--sdp-space-1); }
  .sdp-cal-setmana--tira .sdp-cal-dia__numero { font-size: var(--sdp-text-h5); }
  .sdp-cal-setmana--tira .sdp-cal-setmana__barres,
  .sdp-cal-setmana--tira .sdp-cal-setmana__graella { grid-template-columns: minmax(0, 1fr); }

  .sdp-cal-setmana__franja {
    display: grid;
    grid-template-columns: var(--sdp-cal-marge) minmax(0, 1fr);
    align-items: start;
    padding-block: var(--sdp-space-1);
    border-block-end: 1px solid var(--sdp-vora);
  }
  .sdp-cal-setmana__etiqueta {
    margin: 0;
    padding-inline-end: var(--sdp-space-2);
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
    line-height: 1.2;
    text-align: end;
  }
  .sdp-cal-setmana__barres { min-block-size: var(--sdp-cal-alt-carril); }
  /* Les barres de la franja: plenes amb el color de la font, vora d'inici de
     --sdp-space-1 i el text centrat en el carril. La que ve d'abans no porta
     vora d'inici (no és on comença). L'agenda de Sollutia, en contorn
     discontinu: és una font externa. */
  .sdp-cal-setmana .sdp-cal-barra {
    border-width: 0;
    border-inline-start-width: var(--sdp-space-1);
    line-height: var(--sdp-cal-alt-carril);
  }
  .sdp-cal-setmana .sdp-cal-barra.sdp-cal-font--agenda {
    border-width: 1px;
    border-style: dashed;
    border-inline-start: var(--sdp-space-1) solid var(--sdp-cal-bloc-vora);
  }
  .sdp-cal-setmana .sdp-cal-barra.sdp-cal-barra--abans { border-inline-start-width: 0; }

  /* La graella: el marge de les hores i les columnes dels dies, de l'alçada
     del rang (--sdp-cal-hores × --sdp-cal-hora). */
  .sdp-cal-setmana__graella {
    position: relative;
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    padding-inline-start: var(--sdp-cal-marge);
  }
  /* Les hores, darrere de les columnes: una línia a cada hora en punt, només
     damunt de les columnes (cap a la mitja hora), i l'etiqueta HH:00 al marge,
     alineada a la dreta i centrada sobre la seua línia (--sdp-text-suau: 9,09:1
     en clar i 12,49:1 en fosc). La primera hora no es rotula ni es ratlla: la
     vora de la franja ja hi és. */
  .sdp-cal-setmana__hores { position: absolute; inset: 0; margin: 0; padding: 0; list-style: none; pointer-events: none; }
  .sdp-cal-setmana__hora {
    position: relative;
    block-size: var(--sdp-cal-hora);
    margin: 0;
    margin-inline-start: var(--sdp-cal-marge);
    padding: 0;
    border-block-start: 1px solid var(--sdp-vora);
  }
  .sdp-cal-setmana__hora:first-child { border-block-start-color: transparent; }
  .sdp-cal-setmana__rotul {
    position: absolute;
    inset-inline-end: 100%;
    inset-block-start: 0;
    padding-inline-end: var(--sdp-space-2);
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
    font-variant-numeric: tabular-nums;
    line-height: 1.2;
    white-space: nowrap;
    transform: translateY(-50%);
  }
  .sdp-cal-setmana__columna {
    position: relative;
    block-size: calc(var(--sdp-cal-hores, 24) * var(--sdp-cal-hora));
    border-inline-start: 1px solid var(--sdp-vora);
  }
  /* Els blocs deixen un passadís a la dreta de cada dia, com Google. */
  .sdp-cal-setmana__blocs { position: absolute; inset-block: 0; inset-inline: 0 var(--sdp-space-2); margin: 0; padding: 0; list-style: none; }
  /* Un acte: dalt, el seu minut d'inici menys el de l'hora inicial del rang;
     alt, fins a la seua fi visual; esquerra i amplada, la columna i les
     columnes que ocupa del seu clúster. Alçada i amplada perden
     --sdp-cal-separacio: dos actes seguits no es toquen. Ple amb el color de
     la font i vora d'inici. Text sobre fons, en clar i en fosc: esdeveniment
     8,60:1 i 9,68:1; publicació 9,50:1 i 11,51:1; producte 7,37:1 i 10,53:1;
     pàgina 5,17:1 i 5,43:1; agenda 11,20:1 i 15,20:1. */
  .sdp-cal-setmana__bloc {
    position: absolute;
    inset-block-start: calc((var(--sdp-cal-inici) - var(--sdp-cal-hora-inicial, 0) * 60) * var(--sdp-cal-hora) / 60);
    inset-inline-start: calc(var(--sdp-cal-col) * 100% / var(--sdp-cal-cols));
    display: flex;
    flex-direction: column;
    block-size: calc((var(--sdp-cal-fi) - var(--sdp-cal-inici)) * var(--sdp-cal-hora) / 60 - var(--sdp-cal-separacio));
    inline-size: calc(var(--sdp-cal-amplada) * 100% / var(--sdp-cal-cols) - var(--sdp-cal-separacio));
    overflow: hidden;
    margin: 0;
    padding-block: var(--sdp-space-1) 0;
    padding-inline: var(--sdp-space-1);
    border: 0;
    border-inline-start: var(--sdp-space-1) solid var(--sdp-cal-bloc-vora);
    border-radius: var(--sdp-radi-s);
    background: var(--sdp-cal-bloc-fons);
    color: var(--sdp-cal-bloc-text);
    font-size: var(--sdp-text-meta);
    line-height: var(--sdp-leading-tight);
  }
  .sdp-cal-setmana__bloc.sdp-cal-font--agenda {
    border: 1px dashed var(--sdp-cal-bloc-vora);
    border-inline-start: var(--sdp-space-1) solid var(--sdp-cal-bloc-vora);
  }
  /* A la vista, el títol primer (al DOM, l'hora: el lector diu «10:00–11:30
     Concert»), en negreta i fins a tres línies; amb menys alçada, dos o una
     (formaDelBloc). L'interval mai es parteix (el guió llarg és un punt de
     tall, UAX #14): una sola línia, amb punts suspensius si no hi cap, que és
     la que compta formaDelBloc. El títol no encongix per davall de les seues
     línies senceres: si falta alçada, el que es retalla és l'interval. */
  .sdp-cal-setmana__quan { flex: none; overflow: hidden; font-variant-numeric: tabular-nums; white-space: nowrap; text-overflow: ellipsis; }
  .sdp-cal-setmana__titol {
    display: -webkit-box;
    flex-shrink: 0;
    order: -1;
    overflow: hidden;
    font-weight: 700;
    overflow-wrap: anywhere;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
  }
  .sdp-cal-setmana__bloc--dues-linies .sdp-cal-setmana__titol { -webkit-line-clamp: 2; }
  .sdp-cal-setmana__bloc--una-linia .sdp-cal-setmana__titol { -webkit-line-clamp: 1; }
  /* Curt (menys de 50 minuts visibles, o de 54 en compacta: no hi caben dos
     línies): una sola línia «HH:MM Títol», amb punts suspensius; ací el títol
     sí que encongix, en amplada. */
  .sdp-cal-setmana__bloc--curt { flex-direction: row; align-items: center; column-gap: var(--sdp-space-1); padding-block: 0; white-space: nowrap; }
  .sdp-cal-setmana__bloc--curt .sdp-cal-setmana__titol { display: block; flex: 1 1 auto; order: 0; min-inline-size: 0; text-overflow: ellipsis; }
  /* La línia d'«ara»: --sdp-cal-ara (5,51:1 en clar i 8,28:1 en fosc sobre la
     targeta), de 2px i centrada en el minut, amb un punt a la vora d'inici de
     la columna de hui; damunt dels blocs i davall de la capçalera. */
  .sdp-cal-setmana__ara {
    position: absolute;
    inset-inline: 0;
    inset-block-start: calc((var(--sdp-cal-minut) - var(--sdp-cal-hora-inicial, 0) * 60) * var(--sdp-cal-hora) / 60);
    z-index: 1;
    block-size: 2px;
    background: var(--sdp-cal-ara);
    transform: translateY(-50%);
    pointer-events: none;
  }
  .sdp-cal-setmana__ara::before {
    content: '';
    position: absolute;
    inset-inline-start: 0;
    inset-block-start: 50%;
    inline-size: var(--sdp-space-3);
    block-size: var(--sdp-space-3);
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-cal-ara);
    transform: translate(-50%, -50%);
  }
  .sdp-cal-setmana__avis { margin: 0; padding: var(--sdp-space-2) var(--sdp-space-3); border-block-start: 1px solid var(--sdp-vora); }
  /* Densitat compacta, només amb ratolí: l'hora i els carrils baixen i els
     blocs perden el farciment (formaDelBloc en fa servir els llindars propis:
     54, 78 i 102 minuts). En tàctil res no canvia i cap control baixa de
     --sdp-touch. */
  @media (pointer: fine) {
    .sdp-cal-setmana--compacta .sdp-cal-dia { padding-block: var(--sdp-space-1); }
    .sdp-cal-setmana--compacta .sdp-cal-setmana__bloc { padding-block: 0; }
  }

  /* Mes i 2 setmanes (VistaMes). Fase visual (prompt 261001_0445) · Una
     superfície de targeta amb les setmanes justes del mes (o N des d'un
     dilluns), totes de la mateixa alçada: la de la cel·la (el número, els
     carrils i la línia del «+N»), que el contingut no fa créixer. Les barres
     són una capa damunt dels botons dels dies, que reben el clic
     (pointer-events). overflow: clip retalla els cantons sense fer cap
     contenidor de scroll (Llei de Scroll; Safari 16, Chrome 90, Firefox 81). */
  .sdp-cal-mes {
    overflow: clip;
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
  }
  /* L'abreviatura del dia, només a dalt; les línies de columna hi pugen. */
  .sdp-cal-mes__setmana {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    margin: 0;
    padding: var(--sdp-space-2) 0 var(--sdp-space-1);
    list-style: none;
    font-size: var(--sdp-text-meta);
    font-weight: 700;
    line-height: 1.2;
    color: var(--sdp-text-suau);
    text-align: center;
  }
  .sdp-cal-mes__setmana > li { margin: 0; padding: 0; }
  .sdp-cal-mes__setmana > li + li { border-inline-start: 1px solid var(--sdp-vora); }
  .sdp-cal-mes__setmana abbr { text-decoration: none; }
  .sdp-cal-mes__files { margin: 0; padding: 0; list-style: none; }
  .sdp-cal-mes__fila { position: relative; margin: 0; padding: 0; }
  .sdp-cal-mes__fila + .sdp-cal-mes__fila { border-block-start: 1px solid var(--sdp-vora); }
  .sdp-cal-mes__dies { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); margin: 0; padding: 0; list-style: none; }
  .sdp-cal-mes__cella { margin: 0; padding: 0; }
  .sdp-cal-mes__cella + .sdp-cal-mes__cella { border-inline-start: 1px solid var(--sdp-vora); }
  /* La cel·la: el número centrat dalt i, baix de tot, el «+N» a l'altura de
     l'últim carril. L'alçada és la mateixa a totes les files. */
  .sdp-cal-dia--mes {
    justify-content: flex-start;
    block-size: 100%;
    min-block-size: calc(var(--sdp-cal-alt-numero) + (var(--sdp-cal-carrils) - 1) * (var(--sdp-cal-alt-carril) + var(--sdp-space-1)) + var(--sdp-cal-alt-mes));
  }
  .sdp-cal-mes .sdp-cal-dia__numero {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    min-inline-size: var(--sdp-cal-cercle);
    block-size: var(--sdp-cal-cercle);
    padding-inline: var(--sdp-space-1);
    border-radius: var(--sdp-radi-pastilla);
    font-size: var(--sdp-text-meta);
    line-height: 1;
    white-space: nowrap;
  }
  /* Hui, un cercle invers xicotet (19,42:1 en clar i 18,01:1 en fosc). El dia
     triat porta el fons i la vora d'acció de la base (.sdp-cal-dia). */
  .sdp-cal-mes .sdp-cal-dia[aria-current="date"] .sdp-cal-dia__numero {
    inline-size: var(--sdp-cal-cercle);
    padding-inline: 0;
    background: var(--sdp-cal-hui-fons);
    color: var(--sdp-cal-hui-text);
    text-decoration: none;
  }
  /* El focus de teclat, un anell de 2px dins de la vora de 2px del dia i d'un
     altre color: en clar, --sdp-focus i la vora del triat (--sdp-accio-text)
     són el mateix blau, i el focus quedava amagat damunt del triat. Amb
     --sdp-accent-text, en clar és taronja (5,51:1 sobre la cel·la, 5,14:1 sobre
     la triada i 4,68:1 en hover) i en fosc és el mateix --sdp-focus d'abans.
     Damunt del triat es veuen tots dos, la vora i l'anell. */
  .sdp-cal-mes .sdp-cal-dia:focus-visible { outline: 2px solid var(--sdp-accent-text); outline-offset: -4px; }
  .sdp-cal-dia--fora { color: var(--sdp-text-suau); }
  .sdp-cal-mes__mes {
    align-self: stretch;
    margin-block-start: auto;
    overflow: hidden;
    padding-inline: var(--sdp-space-1);
    font-size: var(--sdp-text-meta);
    font-weight: 700;
    line-height: 1.4;
    text-align: start;
    white-space: nowrap;
    text-overflow: ellipsis;
  }
  .sdp-cal-mes__barres { position: absolute; inset: var(--sdp-cal-alt-numero) 0 auto 0; pointer-events: none; }
  /* Les barres de tot el dia o de diversos dies, plenes amb el color de la
     font: el de la base (.sdp-cal-barra, classeDeFont). Els actes amb hora,
     «● HH:MM Títol»: l'hora i el títol, amb el text de cos, i el punt, amb el
     color del text de la font, l'únic senyal de la font de l'acte: passa de
     4,5:1 sobre la cel·la, la triada i el hover, en clar i en fosc (el de la
     vora baixava, per a producte en fosc, a 2,99:1 sobre la triada i 2,61:1 en
     hover). L'agenda de Sollutia, en anell com a VistaAgenda: comparteix el
     color de la publicació i la forma la distingix. */
  .sdp-cal-mes .sdp-cal-barra--punt { color: var(--sdp-text-cos); }
  .sdp-cal-mes__punt {
    display: inline-block;
    inline-size: var(--sdp-space-2);
    block-size: var(--sdp-space-2);
    margin-inline-end: var(--sdp-space-1);
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-cal-bloc-text);
    vertical-align: middle;
  }
  .sdp-cal-font--agenda .sdp-cal-mes__punt { border: 2px solid var(--sdp-cal-bloc-text); background: transparent; }
  .sdp-cal-mes__hora { font-variant-numeric: tabular-nums; }
  .sdp-cal-mes > p { margin: 0; padding: var(--sdp-space-2) var(--sdp-space-3); border-block-start: 1px solid var(--sdp-vora); }
  /* Densitat compacta, només amb ratolí: en tàctil cap control baixa de
     --sdp-touch. La cel·la perd el farciment de dalt i els carrils baixen. */
  @media (pointer: fine) {
    .sdp-cal-mes--densitat-compacta .sdp-cal-dia--mes { padding-block-start: 0; }
    .sdp-cal-mes--densitat-compacta .sdp-cal-mes__setmana { padding-block-start: var(--sdp-space-1); }
  }
  /* Mode compacte (contenidor estret): les barres, tires de color sense text;
     els actes amb hora, el punt sol. Tires i punts van amb el color del text
     de la font, que passa de 4,5:1 sobre la cel·la, la triada i el hover en
     clar i en fosc: ací el color és l'únic senyal visible que el dia té actes
     (el nom del botó ho diu tot). Després de la densitat: guanya la tira.
     L'agenda, en contorn: la tira buida amb vora i el punt en anell (regla
     de dalt), com a la resta de vistes. */
  .sdp-cal-mes--compacte .sdp-cal-barra { padding: 0; border-width: 0; background: var(--sdp-cal-bloc-text); }
  .sdp-cal-mes--compacte .sdp-cal-barra.sdp-cal-font--agenda:not(.sdp-cal-barra--punt) { border: 2px solid var(--sdp-cal-bloc-text); background: transparent; }
  .sdp-cal-mes--compacte .sdp-cal-barra--punt { display: flex; align-items: center; background: transparent; }
  .sdp-cal-mes--compacte .sdp-cal-mes__punt { margin: 0; }
}

/* T42 · vista prèvia d'impressió amb un sol scroll */
@layer components {
  /* Un sol scroll: el del document dins de l'iframe. El diàleg té alçada
     fixa; el cos és una columna i l'iframe pren la resta. Sense margin: el
     full inferior del mòbil (components.css) conserva el seu. max-width:
     none desfà els 40rem de :where(dialog) (sdp.css); text-align talla
     l'herència de header.page-title. vh primer: dvh només on existix
     (Chrome 108). overflow: auto és la reserva de pantalla curta (apaïsat,
     zoom del 400 %): si no hi cap, fa scroll el diàleg sencer i el peu amb
     «Imprimir» sempre és abastable. */
  .sdp-dialeg.sdp-print-dialog {
    inset: 0;
    height: 90vh;
    max-height: 90vh;
    max-width: none;
    overflow: auto;
    overscroll-behavior: contain;
    text-align: start;
  }
  @supports (height: 1dvh) {
    .sdp-dialeg.sdp-print-dialog { height: 90dvh; max-height: 90dvh; }
  }
  /* max-height: el marc no passa de la caixa del diàleg (el que hereta de
     components.css és 2px més alt, per la vora). */
  .sdp-print-dialog .sdp-dialeg__marc { height: 100%; max-height: 100%; }
  /* Sense scroll propi i sense min-height: 0: el cos no s'encongix per
     davall de la casella i l'iframe mínim, i la reserva és la del diàleg. */
  .sdp-print-dialog .sdp-dialeg__cos {
    display: flex;
    flex-direction: column;
    flex: 1;
    gap: var(--sdp-space-3);
    overflow: visible;
  }
  /* min-height: en pantalla molt curta el diàleg fa scroll de reserva abans
     que deixar un iframe de 0px. */
  .sdp-print-preview {
    display: block;
    flex: 1;
    width: 100%;
    min-height: 10rem;
    border: 0;
    background: var(--sdp-fons-app);
  }
}

/* T43 · connexions i identitat activa */
@layer components {
  /* T43 (ordre del Mestre, 260928) · La vista Connectar. Abans vivia a
     sections/connectar/ConnectarSection.css, importat des del JSX: fora de
     @layer, fora del shadow root de l'embed i amb colors crus. Ara només
     tokens semàntics, sense ombres decoratives ni escala en triar, sense
     :has(). L'estat triat es pinta des d'aria-pressed, no d'una classe. */
  .sdp-connectar {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-8);
    max-width: var(--sdp-measure);
    margin-inline: auto;
    padding-bottom: var(--sdp-space-16);
  }
  .sdp-connectar__objecte {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--sdp-space-1);
    padding: var(--sdp-space-5);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-g);
    background: var(--sdp-fons-targeta);
    text-align: center;
  }
  .sdp-connectar__objecte p { margin: 0; max-width: 100%; overflow-wrap: anywhere; }
  /* T54 · Mini-card de l'element (UniversalCard sense peu). La .sp-card de
     sèrie fa 500px i reserva 400px d'alçada fora de pantalla: la mini té
     amplària pròpia, es pinta sempre i la foto és apaïsada. Sense foto, la
     icona de capes va al costat del títol, centrada com el cos. */
  .sdp-connectar__previsualitzacio { width: 100%; margin-block: var(--sdp-space-2); }
  .sdp-connectar__previsualitzacio .sp-card {
    max-width: calc(var(--sdp-space-16) * 5);
    margin: 0 auto;
    content-visibility: visible;
  }
  /* No és cap enllaç: el hover no l'alça com les targetes del Mur. */
  .sdp-connectar__previsualitzacio .sp-card:hover { box-shadow: var(--sdp-ombra-2); }
  .sdp-connectar__previsualitzacio .sp-card-media-container { aspect-ratio: 4 / 3; }
  .sdp-connectar__previsualitzacio .sp-card-body { padding: var(--sdp-space-4); }
  .sdp-connectar__previsualitzacio .sp-card .sp-card-title {
    flex: 0 1 auto;
    min-width: 0;
    margin: 0;
    font-size: var(--sdp-text-h5);
    overflow-wrap: anywhere;
  }
  .sdp-connectar__previsualitzacio .sp-card-heading-with-icon { justify-content: center; gap: var(--sdp-space-3); margin: 0; }
  .sdp-connectar__tipus {
    font-size: var(--sdp-text-meta);
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--sdp-text-suau);
  }
  .sdp-connectar__autor { font-size: var(--sdp-text-small); color: var(--sdp-text-cos); }
  .sdp-connectar__identitat { font-size: var(--sdp-text-meta); color: var(--sdp-text-suau); }
  .sdp-connectar__seccio { display: flex; flex-direction: column; gap: var(--sdp-space-3); }
  .sdp-connectar__seccio > .sdp-grup { margin: 0; }
  .sdp-connectar__titol-seccio {
    margin: 0;
    font-size: var(--sdp-text-meta);
    font-weight: 800;
    line-height: 1.2;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--sdp-accent-titol);
  }
  .sdp-connectar__ajuda { margin: 0; font-size: var(--sdp-text-meta); line-height: 1.6; color: var(--sdp-text-suau); }
  /* Persones i grups: el que es tria es veu junt, dins d'un marc. */
  .sdp-connectar__panell {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-3);
    padding: var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-g);
    background: var(--sdp-fons-targeta);
  }
  .sdp-connectar__panell .sdp-camp,
  .sdp-connectar__panell .sdp-grup { margin: 0; }
  /* Carpetes: la triada porta la vora taronja (identitat del MAS) i el fons suau. */
  .sdp-connectar__carpetes { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--sdp-space-3); }
  .sdp-connectar__carpeta {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--sdp-space-3);
    min-height: var(--sdp-touch);
    padding: var(--sdp-space-4);
    border: 2px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-g);
    background: var(--sdp-fons-targeta);
    color: var(--sdp-text-cos);
    font: inherit;
    cursor: pointer;
    transition: border-color var(--sdp-t), background-color var(--sdp-t);
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-connectar__carpeta:hover { border-color: var(--sdp-vora-forta); }
  }
  .sdp-connectar__carpeta[aria-pressed="true"] { border-color: var(--sdp-accent); background: var(--sdp-accent-subtil); }
  /* Correcció C18 (260928) · La vora taronja (2,73:1) és identitat, no
     l'única marca: la insígnia «Triada» amb el check, com les targetes de
     GrupOpcions. Totes la porten (triar no mou la graella); només es veu en
     la triada. I el hover no passa per damunt de la triada. */
  @media (hover: hover) and (pointer: fine) {
    .sdp-connectar__carpeta[aria-pressed="true"]:hover { border-color: var(--sdp-accent); }
  }
  .sdp-connectar__carpeta[aria-pressed="false"] .sdp-connectar__carpeta-insignia { visibility: hidden; }
  .sdp-connectar__carpeta-icona { flex: none; }
  .sdp-connectar__carpeta-nom {
    font-size: var(--sdp-text-small);
    font-weight: 700;
    line-height: 1.2;
    text-align: center;
    overflow-wrap: anywhere;
    color: var(--sdp-text-titol);
  }
  /* Píndoles (gent del padró, categories, etiquetes): tota la píndola és l'àrea tàctil. */
  .sdp-connectar__pindoles { display: flex; flex-wrap: wrap; gap: var(--sdp-space-2); margin: 0; padding: 0; list-style: none; }
  .sdp-connectar__pindola {
    display: inline-flex;
    align-items: center;
    gap: var(--sdp-space-2);
    min-height: var(--sdp-touch);
    padding: 0 var(--sdp-space-4);
    border: 1px solid var(--sdp-vora-control);
    border-radius: var(--sdp-radi-boto);
    background: var(--sdp-fons-targeta);
    color: var(--sdp-text-cos);
    font: inherit;
    font-size: var(--sdp-text-small);
    font-weight: 700;
    cursor: pointer;
    transition: border-color var(--sdp-t), background-color var(--sdp-t);
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-connectar__pindola:hover { border-color: var(--sdp-vora-forta); }
  }
  .sdp-connectar__pindola[aria-pressed="true"],
  .sdp-connectar__pindola--triada {
    border-color: var(--sdp-accio-control);
    background: var(--sdp-accio-control);
    color: var(--sdp-sobre-accio);
  }
  .sdp-connectar__pindola:disabled { cursor: not-allowed; opacity: 0.6; }
  .sdp-connectar__carpeta:focus-visible,
  .sdp-connectar__pindola:focus-visible,
  .sdp-connectar__resum:focus-visible { outline: 3px solid var(--sdp-focus); outline-offset: 2px; }
  .sdp-connectar__entrada { display: flex; flex-wrap: wrap; align-items: flex-end; gap: var(--sdp-space-2); }
  .sdp-connectar__entrada > .sdp-camp { flex: 1 1 14rem; margin: 0; }
  .sdp-connectar__peu { display: flex; flex-direction: column; gap: var(--sdp-space-3); }
  .sdp-connectar__nota { margin: 0; text-align: center; font-size: var(--sdp-text-meta); color: var(--sdp-text-suau); }

  /* Resum per destinatari (ResumConnexio): l'estat es llig en text; la
     icona, decorativa, porta el color de l'estat. */
  .sdp-connexio-resum { margin: 0; }
  .sdp-connexio-resum__llista { display: flex; flex-direction: column; gap: var(--sdp-space-2); margin: 0; padding: 0; list-style: none; }
  .sdp-connexio-resum__fila { display: flex; align-items: flex-start; gap: var(--sdp-space-2); }
  .sdp-connexio-resum__icona { flex: none; margin-top: var(--sdp-space-1); }
  .sdp-connexio-resum__fila--fet .sdp-connexio-resum__icona { color: var(--sdp-exit-text); }
  .sdp-connexio-resum__fila--error .sdp-connexio-resum__icona { color: var(--sdp-error-text); }
  .sdp-connexio-resum__fila--pendent .sdp-connexio-resum__icona { color: var(--sdp-info-text); }
  .sdp-connexio-resum__text { display: flex; flex-wrap: wrap; column-gap: var(--sdp-space-2); min-width: 0; }
  .sdp-connexio-resum__nom,
  .sdp-connexio-resum__estat { font-weight: 700; }
  .sdp-connexio-resum__detall { flex-basis: 100%; font-size: var(--sdp-text-meta); }

  /* SDP:T43-barra · T43 (ordre del Mestre, 260928) · Identitat activa a la
     barra negra (BotoIdentitatActiva). És closca: només --sdp-crom-*
     (tractor-crom K3), igual en clar i en fosc. Una entitat porta un anell
     de crom: es veu d'un colp que no actues com a tu.
     Acta 261004_1027 §3 (ordre del Mestre, beta testers) · Amb sessió,
     l'avatar és el botó sencer: redó (radi de pastilla) i gran (Avatar lg,
     56px, dins dels 64px de la barra), mai per davall de --sdp-touch. No
     porta .icon ni .sdp-top-bar-btn: la caixa de 48px amb coixí de 6px i el
     radi de 12px d'utilities eren per a les icones i el feien xicotet i
     quadrat. Sense sessió (el Foraster), el botó de sempre. */
  .sdp-top-bar-avatar {
    display: inline-grid;
    place-items: center;
    flex: none;
    min-width: var(--sdp-touch);
    min-height: var(--sdp-touch);
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: var(--sdp-radi-pastilla);
    background: transparent;
    color: inherit;
    font: inherit;
    cursor: pointer;
  }
  .sdp-top-bar-avatar .sdp-avatar {
    border-width: 0;
    background: var(--sdp-crom-capcalera-clara);
    color: var(--sdp-crom-text);
  }
  .sdp-top-bar-avatar--entitat .sdp-avatar { border: 2px solid var(--sdp-crom-actiu-fons); }
  /* On es punxa: amb ratolí, un anell de crom en passar-hi per damunt. */
  @media (hover: hover) and (pointer: fine) {
    .sdp-top-bar-avatar:hover .sdp-avatar { box-shadow: 0 0 0 2px var(--sdp-crom-hover); }
  }
  .sdp-top-bar-avatar:focus-visible {
    outline: 2px solid var(--sdp-crom-focus);
    outline-offset: 2px;
  }

  /* Calaix «Amb qui actues?» (CalaixIdentitats): fora de la closca, un
     <dialog> amb el tema. L'activa es pinta des d'aria-current. */
  .sdp-calaix-identitats {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-2);
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .sdp-calaix-identitats__item {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-3);
    width: 100%;
    min-height: var(--sdp-touch);
    padding: var(--sdp-space-2) var(--sdp-space-3);
    border: 1px solid transparent;
    border-radius: var(--sdp-radi-m);
    background: transparent;
    color: var(--sdp-text-cos);
    font: inherit;
    text-align: start;
    cursor: pointer;
    transition: background-color var(--sdp-t), border-color var(--sdp-t);
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-calaix-identitats__item:hover { background: var(--sdp-fons-hover-subtil); }
  }
  .sdp-calaix-identitats__item:focus-visible { outline: 3px solid var(--sdp-focus); outline-offset: 2px; }
  .sdp-calaix-identitats__item[aria-current="true"] { background: var(--sdp-accio-subtil); border-color: var(--sdp-accio); }
  .sdp-calaix-identitats__text { display: flex; flex-direction: column; flex: 1; min-width: 0; }
  .sdp-calaix-identitats__nom { color: var(--sdp-text-titol); font-weight: 700; line-height: 1.2; overflow-wrap: anywhere; }
  .sdp-calaix-identitats__rol { color: var(--sdp-text-suau); font-size: var(--sdp-text-meta); }
}

/* SDP:amfitrio · Enxufe universal, T2 (260929) · marca de l'amfitrió */
@layer components {
  /* SDP:amfitrio · Quan l'amfitrió declara nomPoble, la closca diu on és la
     gent (MarcaAmfitrio.jsx; AppShell tria per isCompact, l'amplada del
     contenidor). Sense nomPoble no hi ha cap node ni cap classe d'estes.
     Escriptori: el nom és el primer fill de la barra negra. És closca: només
     --sdp-crom-* (tractor-crom K3), igual en clar i en fosc. */
  .sdp-amfitrio-titol {
    flex: 0 1 auto;
    min-width: 0;
    margin: 0;
    padding-inline: var(--sdp-space-4);
    color: var(--sdp-crom-text);
    font: var(--sdp-font-barra);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .sdp-amfitrio-titol > span { color: var(--sdp-crom-text-suau); }
  /* Barra lateral plegada (escriptori): la marca (.brand) fa 232px dins d'un
     rail de 56px i tapa l'inici de la barra negra (layout.css, § TRUC PER A LA
     SIDEBAR EN ESCRIPTORI). El títol comença on acaba la marca: 232 − 56 =
     176px. Si canvia un d'eixos números a layout.css, canvia este: ho vigila
     MarcaAmfitrio.capes.test.js. Només el títol que és fill directe de la
     barra negra real es desplaça; la mostra del catàleg (/disseny,
     .sdp-amfitrio-mostra) no té cap marca damunt i queda on és. */
  .sdp-root.sidebar-closed header.bar-black > .sdp-amfitrio-titol { margin-inline-start: 176px; }

  /* Compacte: franja davall de la barra negra, del mateix crom.
     T7-T8 (ordre del Mestre, 261001) · Dos germans: l'enllaç a /fedivers
     (pilot, frase, fletxa) i la X. Tots dos fan l'àrea tàctil de
     --sdp-touch, i per això la franja passa d'uns 40px a 44px d'alt: és un
     canvi de píxels ordenat, no una regressió. L'enllaç conserva el
     padding d'abans: la frase no es mou. */
  .sdp-amfitrio-franja {
    flex: none;
    display: flex;
    align-items: stretch;
    margin: 0;
    padding: 0;
    background: var(--sdp-crom-fons);
    color: var(--sdp-crom-text);
    border-bottom: 1px solid var(--sdp-crom-vora);
    font-size: var(--sdp-text-small);
  }
  .sdp-amfitrio-franja__enllac {
    flex: 1 1 auto;
    min-width: 0;
    display: flex;
    align-items: center;
    gap: var(--sdp-space-2);
    min-height: var(--sdp-touch);
    padding: var(--sdp-space-2) var(--sdp-space-4);
    color: var(--sdp-crom-text);
    text-decoration: none;
  }
  .sdp-amfitrio-franja__enllac > svg { flex: none; margin-inline-start: auto; }
  .sdp-amfitrio-franja__text { min-width: 0; overflow-wrap: anywhere; }
  .sdp-amfitrio-franja__tanca {
    flex: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: var(--sdp-touch);
    min-height: var(--sdp-touch);
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--sdp-crom-text);
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-amfitrio-franja__enllac:hover,
    .sdp-amfitrio-franja__tanca:hover { background: var(--sdp-crom-hover); }
  }
  .sdp-amfitrio-franja__enllac:focus-visible,
  .sdp-amfitrio-franja__tanca:focus-visible { outline: 3px solid var(--sdp-crom-focus); outline-offset: -3px; }
  /* Sobre el crom el pilot pinta amb els seus tokens de crom (tokens.css). */
  .sdp-amfitrio-franja .sdp-pilot {
    --pilot-verd: var(--sdp-crom-pilot-verd);
    --pilot-groc: var(--sdp-crom-pilot-groc);
  }

  /* Catàleg (/disseny, EspecimenShell): el títol viu sobre la barra negra; la
     mostra li dona el mateix fons de crom perquè es llija. */
  .sdp-amfitrio-mostra {
    display: flex;
    align-items: center;
    min-height: var(--sdp-alt-negra);
    background: var(--sdp-crom-fons);
    color: var(--sdp-crom-text);
    border-radius: var(--sdp-radi-s);
  }
}

/* SDP:nodes · T7-T9 (261001) · pilot de connexió i llista de nodes */
@layer components {
  /* SDP:nodes · El pilot (connexio/PilotConnexio.jsx), amb l'estat en
     data-estat: verd i ple, connectat; groc i en anell, connectant o sense
     connexió. La forma també diu l'estat (WCAG 1.4.1). Fora del crom pinta
     amb els semàntics d'estat; la franja de l'amfitrió li passa els de crom
     (bloc SDP:amfitrio). Sense animació. */
  .sdp-pilot {
    --pilot-verd: var(--sdp-exit);
    --pilot-groc: var(--sdp-avis);
    flex: none;
    display: inline-block;
    inline-size: var(--sdp-space-3);
    block-size: var(--sdp-space-3);
    border: 2px solid var(--pilot-groc);
    border-radius: var(--sdp-radi-pastilla);
    background: transparent;
  }
  .sdp-pilot[data-estat="connectat"] { border-color: var(--pilot-verd); background: var(--pilot-verd); }

  /* SDP:nodes · Els nodes del Perfil (connexio/LlistaNodes.jsx): una fitxa
     per node, i el node on estàs (aria-current) amb la vora d'acció. */
  .sdp-llista-nodes {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-2);
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .sdp-llista-nodes__node {
    padding: var(--sdp-space-3) var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-s);
    background: var(--sdp-fons-targeta);
  }
  .sdp-llista-nodes__node[aria-current="true"] { border-color: var(--sdp-accio); }
  .sdp-llista-nodes__nom {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-2);
    margin: 0;
    color: var(--sdp-text-cos);
  }
  .sdp-llista-nodes__descripcio {
    max-width: var(--sdp-measure);
    margin: var(--sdp-space-1) 0 0;
    color: var(--sdp-text-suau);
  }
}

/* T54 · lector de connexions del MAS */
@layer components {
  /* T54 · La tira de recopilació del lector (notes/ConnexioDetall.jsx): va
     davall del contingut de l'original, separada per una vora, i no és cap
     barra d'edició. Els botons són Boto de sèrie (àrea tàctil inclosa). */
  .sdp-connexio-lector__tira {
    display: flex;
    flex-wrap: wrap;
    gap: var(--sdp-space-2);
    margin-top: var(--sdp-space-8);
    padding-top: var(--sdp-space-4);
    border-top: 1px solid var(--sdp-vora);
  }
}

/* T44 · /realitat amb targetes */
@layer components {
  /* GrupOpcions aspecte="targetes" (genèric, formulari.jsx; T41 el reutilitza).
     Cada opció és una targeta clicable sencera, però el control continua
     sent el ràdio natiu: l'estat triat es pinta des del seu :checked (sense
     :has()) i també es llig sense color (punt del ràdio i insígnia). */
  .sdp-grup--targetes { padding: 0; border: 0; min-width: 0; }
  .sdp-grup--targetes > .sdp-grup__llegenda { padding: 0; font-size: var(--sdp-text-base); }
  .sdp-grup__targetes {
    display: grid;
    gap: var(--sdp-space-4);
    margin-top: var(--sdp-space-3);
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));
  }
  /* El ràdio va damunt del label: amb opacity (targeta desactivada) el label
     fa context d'apilament, ve després en l'arbre i el tapava. isolation
     tanca el z-index dins de la targeta: no puja damunt de barres fixes. */
  .sdp-targeta-opcio { position: relative; display: flex; min-width: 0; isolation: isolate; }
  .sdp-targeta-opcio__control {
    position: absolute;
    z-index: 1;
    inset-block-start: var(--sdp-space-5);
    inset-inline-end: var(--sdp-space-5);
    width: var(--sdp-space-6);
    height: var(--sdp-space-6);
    margin: 0;
    accent-color: var(--sdp-accio);
    cursor: pointer;
  }
  /* La zona tàctil és la targeta sencera (el label), mai menys de --sdp-touch.
     En columna: la icona dalt, al costat del ràdio, i el text amb tot l'ample. */
  .sdp-targeta-opcio__cos {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: var(--sdp-space-3);
    min-width: 0;
    min-height: var(--sdp-touch);
    padding: var(--sdp-space-5);
    border: 2px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-g);
    background: var(--sdp-fons-targeta);
    color: var(--sdp-text-cos);
    cursor: pointer;
    transition: border-color var(--sdp-t), background-color var(--sdp-t);
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-targeta-opcio__cos:hover { border-color: var(--sdp-vora-forta); }
  }
  /* Contrast sobre --sdp-accio-subtil mesurat: text-suau 8,49:1 en clar
     (261004) i 10,8:1 en fosc; text-cos i text-titol, més. */
  .sdp-targeta-opcio__control:checked + .sdp-targeta-opcio__cos {
    border-color: var(--sdp-accio);
    background: var(--sdp-accio-subtil);
  }
  .sdp-targeta-opcio__control:checked + .sdp-targeta-opcio__cos .sdp-targeta-opcio__icona {
    background: var(--sdp-accio-control);
    color: var(--sdp-sobre-accio);
  }
  /* Error del grup: .sdp-grup--targetes lleva la vora del fieldset, així que
     la vora d'error la porten les targetes (també la triada, que conserva fons
     i insígnia). Va darrere de :checked i davant de :focus-visible i
     :disabled, que continuen guanyant. El missatge d'error no canvia. */
  .sdp-grup--targetes.sdp-grup--error .sdp-targeta-opcio__cos { border-color: var(--sdp-error); }
  .sdp-targeta-opcio__control:focus-visible { outline: 3px solid var(--sdp-focus); outline-offset: 2px; }
  .sdp-targeta-opcio__control:focus-visible + .sdp-targeta-opcio__cos { border-color: var(--sdp-focus); }
  .sdp-targeta-opcio__control:disabled,
  .sdp-targeta-opcio__control:disabled + .sdp-targeta-opcio__cos { cursor: not-allowed; }
  .sdp-targeta-opcio__control:disabled + .sdp-targeta-opcio__cos { border-color: var(--sdp-vora); opacity: 0.6; }
  .sdp-targeta-opcio__icona {
    flex: none;
    align-self: flex-start;
    display: inline-grid;
    place-items: center;
    width: var(--sdp-space-12);
    height: var(--sdp-space-12);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-cos);
    transition: background-color var(--sdp-t), color var(--sdp-t);
  }
  .sdp-targeta-opcio__text { display: flex; flex-direction: column; gap: var(--sdp-space-1); min-width: 0; }
  /* Sense icona, antetítol i títol queden a l'altura del ràdio: li deixen lloc. */
  .sdp-targeta-opcio__antetitol,
  .sdp-targeta-opcio__titol { padding-inline-end: var(--sdp-space-8); }
  .sdp-targeta-opcio__antetitol { font-size: var(--sdp-text-meta); font-weight: 700; color: var(--sdp-text-suau); }
  .sdp-targeta-opcio__titol { font-size: var(--sdp-text-h6); font-weight: 800; line-height: 1.2; color: var(--sdp-text-titol); }
  .sdp-targeta-opcio__ajuda { font-size: var(--sdp-text-small); line-height: 1.6; }
  .sdp-targeta-opcio__detall {
    display: inline-flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--sdp-space-2);
    margin-top: var(--sdp-space-1);
    font-size: var(--sdp-text-meta);
    color: var(--sdp-text-suau);
  }
  .sdp-targeta-opcio__insignia { align-self: flex-start; margin-top: var(--sdp-space-2); }

  /* /realitat (substituïx el bloc T31): dins de l'ample de lectura. */
  .sdp-realitat {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-8);
    max-width: var(--sdp-measure);
    margin-inline: auto;
  }
  .sdp-realitat .sdp-grup { margin: 0; }
  .sdp-realitat__estat,
  .sdp-realitat__connexio {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--sdp-space-4);
    padding: var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-g);
    background: var(--sdp-fons-targeta);
  }
  .sdp-realitat__estat-text { flex: 1; display: flex; flex-direction: column; gap: var(--sdp-space-1); min-width: 0; }
  .sdp-realitat__estat-titol { margin: 0; font-weight: 800; color: var(--sdp-text-titol); }
  .sdp-realitat__estat-desc,
  .sdp-realitat__connexio-text { margin: 0; font-size: var(--sdp-text-small); line-height: 1.6; color: var(--sdp-text-cos); }
  .sdp-realitat__connexio-text { flex: 1 1 14rem; min-width: 0; }
  .sdp-realitat__iaia {
    flex: none;
    display: inline-grid;
    place-items: center;
    width: var(--sdp-space-16);
    height: var(--sdp-space-16);
    border: 2px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-cos);
  }
  .sdp-realitat__iaia .sdp-iaia-icon { width: var(--sdp-space-10); height: var(--sdp-space-10); }
  /* Mateixos @keyframes que la IAIA de la barra negra (layout.css,
     sdp-iaia-resplendor): si es reanomenen allà, cal canviar-los ací. Amb
     moviment reduït l'animació para i la vora taronja sosté l'estat. */
  .sdp-realitat__iaia--activa {
    border-color: var(--sdp-accent);
    color: var(--sdp-accent-text);
    animation: sdp-iaia-resplendor 8s ease-in-out infinite;
  }
  /* Mesurador d'intensitat 0-3 (decoratiu): el taronja del resplendor. */
  .sdp-realitat__pedres { display: inline-flex; gap: var(--sdp-space-1); }
  .sdp-realitat__pedra {
    width: var(--sdp-space-4);
    height: var(--sdp-space-3);
    border: 2px solid var(--sdp-vora-control);
    border-radius: var(--sdp-radi-s);
  }
  .sdp-realitat__pedra--plena { border-color: var(--sdp-accent); background: var(--sdp-accent); }
  /* Acompanyants del nivell 2: targetes-casella. La vora de la triada la
     posa React amb una classe, no :has(). */
  .sdp-realitat__acompanyants { padding: 0; border: 0; min-width: 0; }
  .sdp-realitat__acompanyants > .sdp-grup__llegenda { padding: 0; font-size: var(--sdp-text-base); }
  .sdp-realitat__acompanyants > .sdp-camp__ajuda { margin: var(--sdp-space-1) 0 0; }
  .sdp-realitat__graella {
    display: grid;
    gap: var(--sdp-space-3);
    margin-top: var(--sdp-space-3);
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
  }
  .sdp-realitat__company {
    align-items: center;
    min-width: 0;
    padding: var(--sdp-space-3) var(--sdp-space-4);
    border: 2px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-g);
    background: var(--sdp-fons-targeta);
    transition: border-color var(--sdp-t), background-color var(--sdp-t);
  }
  .sdp-realitat__company--triat { border-color: var(--sdp-accio); background: var(--sdp-accio-subtil); }
  .sdp-realitat__company .sdp-casella__etiqueta {
    flex: 1;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    column-gap: var(--sdp-space-3);
    row-gap: var(--sdp-space-1);
    align-items: center;
    min-width: 0;
  }
  .sdp-realitat__company .sdp-avatar { grid-row: span 2; }
  .sdp-realitat__company-nom { font-weight: 700; color: var(--sdp-text-titol); }
  .sdp-realitat__company .sdp-casella__ajuda { grid-column: 2; }
  .sdp-realitat__connexio .sdp-avatar-grup { flex: none; }
}

/* T45 · cerca avançada */
@layer components {
  /* T45 · /cerca: una columna de lectura (68ch) amb la caixa, els filtres
     (PillToggle compacte, les opcions salten de línia i no canvien de lloc),
     el recompte i els grups de resultats. */
  .sdp-cerca {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-4);
    max-width: var(--sdp-measure);
    margin-inline: auto;
    padding-block-end: var(--sdp-space-8);
  }
  .sdp-cerca__formulari { margin: 0; }
  .sdp-cerca__filtres {
    justify-content: flex-start;
    margin: 0;
    border-radius: var(--sdp-radi-g);
  }
  .sdp-cerca__filtres .sdp-pindola__opcio { padding-inline: var(--sdp-space-3); }
  /* En mòbil, una sola fila que es desplaça dins de la píndola: les onze
     opcions no ocupen mitja pantalla i cap canvia de lloc. */
  @media (max-width: 720px) {
    .sdp-cerca__filtres {
      flex-wrap: nowrap;
      overflow-x: auto;
      overscroll-behavior-inline: contain;
      border-radius: var(--sdp-radi-boto);
    }
    .sdp-cerca__filtres .sdp-pindola__opcio { flex: none; }
  }
  .sdp-cerca__recompte { font-weight: 400; }
  .sdp-cerca__estat {
    margin: 0;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
  }
  .sdp-cerca__carregant { align-self: flex-start; }
  .sdp-cerca__grup {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-2);
  }
  .sdp-cerca__grup-titol {
    margin: 0;
    color: var(--sdp-text-titol);
    font-size: var(--sdp-text-h5);
    line-height: var(--sdp-leading-tight);
  }
  .sdp-cerca__grup-recompte {
    color: var(--sdp-text-suau);
    font-weight: 400;
  }
  .sdp-cerca__llista {
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .sdp-cerca__mes { align-self: flex-start; }

  /* T45 · ResultatCerca (PedraSeca): miniatura 1:1 o avatar, meta, títol
     enllaçat i extracte de dues línies. Classes pròpies: les legacy
     .search-result* no es toquen (Llei del Píxel del catàleg antic). */
  .sdp-resultat-cerca {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: start;
    gap: var(--sdp-space-4);
    padding-block: var(--sdp-space-4);
    border-block-end: 1px solid var(--sdp-vora);
  }
  .sdp-resultat-cerca--sense-media { grid-template-columns: minmax(0, 1fr); }
  .sdp-resultat-cerca__miniatura {
    display: block;
    width: var(--sdp-space-16);
    height: auto;
    aspect-ratio: 1 / 1;
    object-fit: cover;
    border-radius: var(--sdp-radi-s);
    background: var(--sdp-fons-subtil);
  }
  .sdp-resultat-cerca__avatar { align-self: start; }
  .sdp-resultat-cerca__cos {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-1);
    min-width: 0;
  }
  .sdp-resultat-cerca__meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--sdp-space-1) var(--sdp-space-2);
    margin: 0;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
    line-height: var(--sdp-leading-snug);
  }
  .sdp-resultat-cerca__sep { color: var(--sdp-text-suau); }
  .sdp-resultat-cerca__titol {
    margin: 0;
    color: var(--sdp-text-titol);
    font-size: var(--sdp-text-h6);
    line-height: var(--sdp-leading-snug);
    overflow-wrap: anywhere;
  }
  .sdp-resultat-cerca__enllac {
    display: inline-flex;
    align-items: center;
    min-height: var(--sdp-touch);
    color: var(--sdp-accio-text);
    text-decoration: none;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-resultat-cerca__enllac:hover { text-decoration: underline; }
  }
  .sdp-resultat-cerca__enllac:focus-visible {
    outline: 3px solid var(--sdp-focus);
    outline-offset: 2px;
    border-radius: var(--sdp-radi-s);
  }
  /* Com un cercador web: la paraula trobada va en negreta, sense fons
     (els tons -subtil no es distingixen del fons de lectura). */
  .sdp-resultat-cerca mark {
    background: transparent;
    color: inherit;
    font-weight: 700;
  }
  /* El títol ja va en negreta: ací la paraula trobada es distingix amb un
     subratllat del to d'accent, que tapa el de l'enllaç en passar-hi. */
  .sdp-resultat-cerca__titol mark {
    text-decoration-line: underline;
    text-decoration-color: var(--sdp-accent-text);
    text-decoration-thickness: 2px;
  }
  .sdp-resultat-cerca__extracte {
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    overflow: hidden;
    max-width: var(--sdp-measure);
    margin: 0;
    color: var(--sdp-text-cos);
    line-height: var(--sdp-leading-body);
  }
  .sdp-resultat-cerca__accio { margin-block-start: var(--sdp-space-2); }
}

/* T46 · enquadrament d'imatges */
@layer components {
  /* T46 (ordre del Mestre, 260928) · DialegEnquadrament. El visor és un
     <canvas> amb la mida en atributs (sense style=): amb width/height auto i
     els dos max conserva la proporció. touch-action:none perquè arrossegar la
     foto amb el dit no desplace el diàleg. */
  .sdp-enquadrament {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-4);
  }
  .sdp-enquadrament__visor-marc {
    display: flex;
    justify-content: center;
    padding: var(--sdp-space-2);
    background: var(--sdp-fons-subtil);
    border-radius: var(--sdp-radi-m);
  }
  .sdp-enquadrament__visor {
    display: block;
    width: auto;
    height: auto;
    max-width: 100%;
    max-height: 50vh;
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-s);
    background: var(--sdp-fons-targeta);
    touch-action: none;
    cursor: grab;
  }
  .sdp-enquadrament__visor:active { cursor: grabbing; }
  /* Correcció C19 (260928) · La foto i els lliscadors han de cabre alhora.
     Mesurat a 1280×800 abans: el cos feia 500px i el primer control era a
     y=743; després, foto de 360px i els tres lliscadors dins del cos. En
     mòbil, en columna: la vista, els lliscadors i la forma. A 375×812 el
     peu de tres botons apilats (189px, components.css) deixa el cos en
     368px: la foto i el primer lliscador encara no hi caben junts. */
  .sdp-enquadrament__obra { display: flex; flex-direction: column; gap: var(--sdp-space-4); }
  .sdp-enquadrament__vista { display: flex; flex-direction: column; gap: var(--sdp-space-2); }
  .sdp-enquadrament__vista > .sdp-camp__ajuda { margin: 0; }
  @media (max-width: 720px) {
    .sdp-enquadrament__visor { max-height: min(40vh, 18rem); }
  }
  /* ≥721px · Dues columnes: la vista a una banda (sticky: es queda a la
     vista quan el cos fa scroll fins a la forma) i els controls a l'altra
     (en 20rem, el seu auto-fit ja fa una sola columna). 45vh deixa lloc a
     l'ajuda davall de la foto. */
  @media (min-width: 721px) {
    /* La mida g (56rem) de sèrie: :where(dialog) de sdp.css la tallava a
       40rem i la foto, al costat dels controls, es quedava en 238px. */
    .sdp-dialeg.sdp-enquadrament__dialeg { max-width: none; }
    .sdp-enquadrament__obra {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(16rem, 20rem);
      align-items: start;
    }
    .sdp-enquadrament__vista { position: sticky; top: 0; }
    .sdp-enquadrament__visor { max-height: 45vh; }
  }
  /* La forma a una banda i els lliscadors a l'altra quan hi ha lloc; en
     mòbil, en columna. min(100%, 16rem): per davall de 16rem la columna
     s'estreny amb el diàleg en lloc de desbordar-lo (T46, poliment). */
  .sdp-enquadrament__controls {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr));
    align-items: start;
    gap: var(--sdp-space-4);
  }
  .sdp-enquadrament__lliscadors {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-3);
  }
  /* El lliscador natiu no porta la caixa del camp de text; l'àrea tàctil i
     el focus (.sdp-control:focus-visible) es conserven. */
  .sdp-enquadrament__lliscador.sdp-control {
    padding: 0;
    border: 0;
    background: transparent;
    min-height: var(--sdp-touch);
  }
  /* Espècimen: el resultat desat, perquè es veja el que ix del diàleg. */
  .sdp-enquadrament__resultat {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-2);
    margin: 0;
  }
  .sdp-enquadrament__resultat img {
    display: block;
    width: auto;
    height: auto;
    max-width: 100%;
    max-height: 20rem;
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-s);
  }
}

/* T47 · autodesament */
@layer components {
  /* T47 (ordre del Mestre, 260928) · L'indicador de l'autodesament
     (EstatDesament.jsx): primer element de la barra taronja, no
     interactiu en 'pendent' i 'enviant' (C14). Mateixa caixa que els cercles de la barra (48px) perquè la
     fila no es desquadre. L'avís es distingix per la forma de la icona
     (triangle), no només pel color.
     T51 (ordre del Mestre, 260928) · Icona blanca (--sdp-sobre-color) dins
     del mateix cercle de vel fosc que la resta de controls de la barra
     taronja (.btn-icon-orange): el blanc directe damunt del taronja no
     arriba al 3:1 de contrast, i dins del vel sí. Abans no tenia fons i
     heretava el negre de la barra. */
  .sdp-estat-desament {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    width: var(--sdp-touch-comode);
    height: var(--sdp-touch-comode);
    border-radius: var(--sdp-radi-boto);
    background: var(--sdp-crom-scroll-pista);
    color: var(--sdp-sobre-color);
  }
  .sdp-estat-desament--pendent .icon { stroke-width: 2; }
  .sdp-estat-desament--avis .icon { stroke-width: 2.5; }
  /* .bar-actions .icon (layout.css) hi posa la mà de «clica'm»: l'indicador no és cap botó. */
  .bar-actions .sdp-estat-desament .icon { cursor: default; opacity: 1; }
  /* Correcció C14 (260928) · En 'error' i 'sessio' la icona és un <button>
     que obri el detall: la mateixa caixa (48px ≥ --sdp-touch) i la mateixa
     pell, sense la del navegador. L'anell de focus és rodó, com els cercles.
     T51 · El mateix vel que la resta; en passar-hi el ratolí, el vel fort. */
  .sdp-estat-desament--boto {
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: var(--sdp-radi-pastilla);
    background: var(--sdp-crom-scroll-pista);
    font: inherit;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-estat-desament--boto:hover { background: var(--sdp-crom-scroll-puny); }
  }
  .bar-actions .sdp-estat-desament--boto .icon { cursor: pointer; }

  /* Els avisos en línia dels camps, davall de l'entradilla (UniversalEditorShell):
     la mesura del text de lectura i l'alerta canònica (.sdp-alerta--error). */
  .sdp-avisos-camps {
    max-width: var(--sdp-measure);
    margin: 0 auto var(--sdp-space-4);
    padding: 0;
    list-style: none;
  }
  /* És una llista d'avisos, no prosa: fora el sagnat i el marge de base.css. */
  .sdp-avisos-camps > li { margin: 0; padding: 0; }
  .sdp-avisos-camps .sdp-avis-camp { margin-block: 0 var(--sdp-space-3); }
  .sdp-avis-camp__comptador {
    margin: 0 0 var(--sdp-space-2);
    font-size: var(--sdp-text-meta);
    color: var(--sdp-text-suau);
    text-align: center;
  }
}

/* ── TRACTORS (261002) ── */
@layer components {
  /* Porta d'aprovació de tractors (src/sections/tractors/PanellTractors.jsx).
     La llista a una banda i el detall a l'altra sense media queries: quan el
     detall no hi cap amb 30rem, baixa davall (funciona igual dins de
     l'encastament, que no té el viewport de la finestra). */
  .sdp-tractors-panell {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-4);
    max-width: 72rem;
    margin-inline: auto;
    padding-block-end: var(--sdp-space-8);
  }
  .sdp-tractors-panell > p { margin: 0; }
  .sdp-tractors-panell__titol {
    margin: 0;
    font-size: var(--sdp-text-h4);
    text-align: left;
  }
  .sdp-tractors-panell__cos {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    gap: var(--sdp-space-6);
  }
  .sdp-tractors-panell__llista {
    display: flex;
    flex: 1 1 16rem;
    flex-direction: column;
    gap: var(--sdp-space-2);
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .sdp-tractors-panell__llista > li { margin: 0; padding: 0; }
  /* Tota la fila és el botó; el triat porta aria-current i la vora d'acció. */
  .sdp-tractors-panell__tria {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--sdp-space-2);
    width: 100%;
    min-height: var(--sdp-touch);
    padding: var(--sdp-space-3) var(--sdp-space-4);
    border: 2px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
    color: var(--sdp-text-titol);
    font: inherit;
    font-size: var(--sdp-text-small);
    text-align: left;
    cursor: pointer;
  }
  @media (hover: hover) and (pointer: fine) {
    .sdp-tractors-panell__tria:hover { border-color: var(--sdp-vora-forta); }
  }
  .sdp-tractors-panell__tria[aria-current="true"] {
    border-color: var(--sdp-accio);
    background: var(--sdp-accio-subtil);
  }
  .sdp-tractors-panell__tria:focus-visible {
    outline: 3px solid var(--sdp-focus);
    outline-offset: 2px;
  }
  .sdp-tractors-panell__tria-nom { font-weight: 700; }
  .sdp-tractors-panell__detall {
    display: flex;
    flex: 999 1 0;
    flex-direction: column;
    gap: var(--sdp-space-4);
    min-width: min(100%, 30rem);
    padding: var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-g);
    background: var(--sdp-fons-targeta);
  }
  .sdp-tractors-panell__detall > p { margin: 0; }
  .sdp-tractors-panell__cap {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--sdp-space-3);
  }
  .sdp-tractors-panell__nom {
    margin: 0;
    padding: 0;
    border: 0;
    font-size: var(--sdp-text-h4);
  }
  .sdp-tractors-panell__motiu {
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-small);
  }
  .sdp-tractors-panell__dades {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
    gap: var(--sdp-space-3) var(--sdp-space-6);
    margin: 0;
  }
  .sdp-tractors-panell__dades dt { font-weight: 700; color: var(--sdp-text-titol); }
  .sdp-tractors-panell__dades dd { margin: 0; color: var(--sdp-text-cos); }
  .sdp-tractors-panell__dades ul { margin: 0; padding-inline-start: var(--sdp-space-5); }
  .sdp-tractors-panell__subtitol {
    margin: 0 0 var(--sdp-space-2);
    font-size: var(--sdp-text-h5);
  }
  /* L'empremta curta és el que el Mestre escriu per a confirmar: gran i monoespai. */
  .sdp-tractors-panell__empremta {
    padding: var(--sdp-space-4);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-subtil);
  }
  /* La caixa de l'empremta curta (abans un style= en línia a PanellTractors.jsx,
     261002): mateixa vora i radi, farciment a l'escala de 0.25rem, i se
     selecciona sencera d'un toc per a copiar-la a mà. */
  .sdp-tractors-panell__curta {
    display: inline-block;
    margin: 0 var(--sdp-space-2) var(--sdp-space-2) 0;
    padding: var(--sdp-space-2) var(--sdp-space-3);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    user-select: all;
    color: var(--sdp-text-titol);
    font-family: var(--sdp-font-mono);
    font-size: var(--sdp-text-h3);
    font-weight: 700;
    letter-spacing: 0.08em;
  }
  .sdp-tractors-panell__completa {
    display: block;
    color: var(--sdp-text-cos);
    font-family: var(--sdp-font-mono);
    font-size: var(--sdp-text-small);
    overflow-wrap: anywhere;
  }
  .sdp-tractors-panell__fonts summary {
    display: list-item;
    min-height: var(--sdp-touch);
    padding-block: var(--sdp-space-2);
    font-size: var(--sdp-text-small);
    cursor: pointer;
  }
  .sdp-tractors-panell__fonts summary:focus-visible {
    outline: 3px solid var(--sdp-focus);
    outline-offset: 2px;
  }
  .sdp-tractors-panell__fonts ul { margin: 0; padding-inline-start: var(--sdp-space-5); }
  .sdp-tractors-panell__codi {
    max-height: 24rem;
    margin: 0 0 var(--sdp-space-3);
    padding: var(--sdp-space-3);
    overflow: auto;
    border-radius: var(--sdp-radi-s);
    background: var(--sdp-fons-subtil);
    font-family: var(--sdp-font-mono);
    font-size: var(--sdp-text-small);
    white-space: pre;
  }
  /* La fitxa ix de parseMarkdown amb els títols dos esglaons més avall (h4-h6). */
  .sdp-tractors-panell__fitxa {
    padding-block-start: var(--sdp-space-2);
    border-block-start: 1px solid var(--sdp-vora);
  }
  .sdp-tractors-panell__fitxa :is(h4, h5, h6) {
    margin: var(--sdp-space-4) 0 var(--sdp-space-2);
    padding: 0;
    border: 0;
    font-size: var(--sdp-text-h5);
    text-align: left;
    text-transform: none;
    letter-spacing: normal;
  }
  .sdp-tractors-panell__fitxa h4 { font-size: var(--sdp-text-h4); }
  .sdp-tractors-panell__accions,
  .sdp-tractors-panell__peu {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--sdp-space-3);
  }
  .sdp-tractors-panell__peu > p {
    flex-basis: 100%;
    margin: 0;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-small);
  }
  .sdp-tractors-panell__historial {
    margin: 0;
    padding-inline-start: var(--sdp-space-5);
    color: var(--sdp-text-cos);
    font-size: var(--sdp-text-small);
  }
  .sdp-tractors-panell__historial > li + li { margin-block-start: var(--sdp-space-2); }

  /* DialegAprovacio.jsx: les dues vies (signatura i confirmació escrita) en caixes. */
  .sdp-tractors-dialeg {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-4);
  }
  .sdp-tractors-dialeg__empremta { margin: 0; }
  .sdp-tractors-dialeg__curta {
    font-family: var(--sdp-font-mono);
    font-size: var(--sdp-text-h5);
    letter-spacing: 0.08em;
  }
  .sdp-tractors-dialeg__via {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--sdp-space-3);
    padding: var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
  }
  .sdp-tractors-dialeg__via p { margin: 0; }
  .sdp-tractors-dialeg__via .sdp-camp { align-self: stretch; }
  .sdp-tractors-dialeg__titol {
    margin: 0;
    padding: 0;
    border: 0;
    font-size: var(--sdp-text-h5);
  }
}

/* ── GESTORIA ENVIAMENT (261002) ── */
@layer components {
  /* EnviamentGestoria.jsx: el correu del full trimestral per a la gestoria.
     Una sola columna de lectura, sense media queries (viu també dins de
     l'encastament). La vista prèvia es distingix pel fons subtil, i el cos
     del correu hi conserva els salts de línia tal com arribaran. */
  .sdp-gestoria-enviament {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-4);
    max-width: var(--sdp-measure);
  }
  .sdp-gestoria-enviament > p { margin: 0; }
  .sdp-gestoria-enviament > h2 {
    margin: 0;
    font-size: var(--sdp-text-h4);
    text-align: left;
  }
  .sdp-gestoria-enviament__formulari {
    display: grid;
    gap: var(--sdp-space-4);
  }
  .sdp-gestoria-enviament__formulari > .sdp-camp { margin: 0; }
  .sdp-gestoria-enviament__formulari > .sdp-boto { justify-self: start; }
  .sdp-gestoria-enviament__vista {
    padding: var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-cos);
  }
  .sdp-gestoria-enviament__vista > h3 {
    margin: 0 0 var(--sdp-space-3);
    padding: 0;
    border: 0;
    font-size: var(--sdp-text-h5);
  }
  .sdp-gestoria-enviament__dades { margin: 0 0 var(--sdp-space-3); }
  .sdp-gestoria-enviament__dades dt {
    font-weight: 700;
    color: var(--sdp-text-titol);
  }
  .sdp-gestoria-enviament__dades dd {
    margin: 0 0 var(--sdp-space-2);
    overflow-wrap: anywhere;
  }
  .sdp-gestoria-enviament__adjunts {
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .sdp-gestoria-enviament__cos {
    margin: 0;
    padding: var(--sdp-space-3);
    border-radius: var(--sdp-radi-s);
    background: var(--sdp-fons-targeta);
    color: var(--sdp-text-cos);
    white-space: pre-wrap;
    overflow-wrap: anywhere;
  }
  .sdp-gestoria-enviament__accions {
    display: grid;
    gap: var(--sdp-space-4);
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .sdp-gestoria-enviament__opcio {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--sdp-space-2);
    margin: 0;
  }
  .sdp-gestoria-enviament__ajuda {
    margin: 0;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-small);
  }
}

/* ── CALENDARI · FONTS (261002) ── */
@layer components {
  /* T1 (prompt 261002_0125) · Amb fonts de calendari configurades
     (src/sections/calendari/fonts/), el calendari de /calendari va al costat
     del panell «Els meus calendaris», com a Google Calendar. Sense media
     queries (funciona igual dins de l'encastament): quan el calendari no hi
     cap amb 30rem, el panell queda damunt a tota l'amplada. Sense
     configuració no es pinta cap d'estes classes (Llei del Píxel). */
  .sdp-calendari-fonts-costat {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    gap: var(--sdp-space-4);
  }
  .sdp-calendari-fonts-costat__principal {
    flex: 999 1 0;
    min-width: min(100%, 30rem);
  }
  .sdp-calendari-fonts-panell {
    display: flex;
    flex: 1 1 15rem;
    flex-direction: column;
    gap: var(--sdp-space-4);
    padding: var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
    color: var(--sdp-text-cos);
  }
  .sdp-calendari-fonts-panell__titol,
  .sdp-calendari-fonts-panell__compte-nom {
    margin: 0;
    padding: 0;
    border: 0;
    color: var(--sdp-text-titol);
    text-align: left;
  }
  .sdp-calendari-fonts-panell__titol { font-size: var(--sdp-text-h5); }
  .sdp-calendari-fonts-panell__compte-nom {
    font-size: var(--sdp-text-small);
    overflow-wrap: anywhere;
  }
  .sdp-calendari-fonts-panell__compte {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--sdp-space-2);
  }
  .sdp-calendari-fonts-panell__llista {
    display: flex;
    flex-direction: column;
    align-self: stretch;
    gap: var(--sdp-space-1);
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .sdp-calendari-fonts-panell__font { margin: 0; padding: 0; }
  /* La casella porta el color de la font: la vora de l'esquerra i, marcada,
     el farciment (accent-color s'hereta fins a l'input). El nom ho diu tot:
     el color mai és l'únic senyal. */
  .sdp-calendari-fonts-panell__casella {
    display: flex;
    align-items: center;
    gap: var(--sdp-space-3);
    min-height: var(--sdp-touch);
    padding-inline-start: var(--sdp-space-2);
    border-inline-start: 0.25rem solid var(--sdp-vora-control);
    color: var(--sdp-text-titol);
    font-size: var(--sdp-text-small);
    cursor: pointer;
  }
  .sdp-calendari-fonts-panell__casella input {
    flex: none;
    width: 1.25rem;
    height: 1.25rem;
    margin: 0;
    cursor: pointer;
  }
  .sdp-calendari-fonts-panell__casella input:focus-visible {
    outline: 3px solid var(--sdp-focus);
    outline-offset: 2px;
  }
  .sdp-calendari-fonts-panell__casella--accio { border-inline-start-color: var(--sdp-accio); accent-color: var(--sdp-accio); }
  .sdp-calendari-fonts-panell__casella--accent { border-inline-start-color: var(--sdp-accent); accent-color: var(--sdp-accent); }
  .sdp-calendari-fonts-panell__casella--exit { border-inline-start-color: var(--sdp-exit); accent-color: var(--sdp-exit); }
  .sdp-calendari-fonts-panell__casella--avis { border-inline-start-color: var(--sdp-avis); accent-color: var(--sdp-avis); }
  .sdp-calendari-fonts-panell__casella--error { border-inline-start-color: var(--sdp-error); accent-color: var(--sdp-error); }
  .sdp-calendari-fonts-panell__estat,
  .sdp-calendari-fonts-panell__avis {
    margin: 0;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-small);
  }
  .sdp-calendari-fonts-panell__avis {
    display: block;
    padding-inline-start: var(--sdp-space-3);
  }
  .sdp-calendari-fonts-panell__estat--error,
  .sdp-calendari-fonts-panell__avis--error { color: var(--sdp-error-text); }
}

/* ── GESTORIA PANELL (261002) ── */
@layer components {
  /* PanellGestoria.jsx: el full trimestral per a la gestoria, en cinc passos
     numerats. Sense media queries (viu també dins de l'encastament): els
     blocs es pleguen amb flex-wrap i les taules es desplacen en horitzontal
     dins de la seua caixa (mai en vertical: taules.capes.test.js). L'estat
     de cada pas el diu la insígnia amb text; la vora només l'acompanya. */
  .sdp-gestoria-panell {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-4);
    max-width: 80rem;
    margin-inline: auto;
