    align-items: center;
    justify-content: space-between;
    gap: var(--sdp-space-3);
    padding: var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
    background: var(--sdp-fons-targeta);
  }
  .sdp-gestoria-panell__barra > p {
    flex: 1 1 20rem;
    margin: 0;
    color: var(--sdp-text-cos);
  }
  .sdp-gestoria-panell__avis {
    margin: 0;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-small);
  }
  .sdp-gestoria-panell__passos {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-6);
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .sdp-gestoria-panell__pas {
    margin: 0;
    padding: var(--sdp-space-4);
    border: 1px solid var(--sdp-vora);
    border-inline-start: 0.25rem solid var(--sdp-vora);
    border-radius: var(--sdp-radi-g);
    background: var(--sdp-fons-targeta);
  }
  .sdp-gestoria-panell__pas[data-estat="actiu"] { border-inline-start-color: var(--sdp-accio); }
  .sdp-gestoria-panell__pas[data-estat="fet"] { border-inline-start-color: var(--sdp-exit); }
  .sdp-gestoria-panell__cap {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--sdp-space-3);
    margin-block-end: var(--sdp-space-3);
  }
  .sdp-gestoria-panell__titol,
  .sdp-gestoria-panell__subtitol,
  .sdp-gestoria-panell__grup-titol {
    margin: 0;
    padding: 0;
    border: 0;
    color: var(--sdp-text-titol);
    text-align: left;
  }
  .sdp-gestoria-panell__titol { font-size: var(--sdp-text-h4); }
  .sdp-gestoria-panell__subtitol { font-size: var(--sdp-text-h5); }
  .sdp-gestoria-panell__grup-titol { font-size: var(--sdp-text-base); }
  .sdp-gestoria-panell__titol:focus-visible,
  .sdp-gestoria-panell__subtitol:focus-visible {
    outline: 3px solid var(--sdp-focus);
    outline-offset: 2px;
  }
  .sdp-gestoria-panell__cos,
  .sdp-gestoria-panell__bloc {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-4);
    min-width: 0;
  }
  .sdp-gestoria-panell__cos > p,
  .sdp-gestoria-panell__bloc > p { margin: 0; }
  .sdp-gestoria-panell__tractors,
  .sdp-gestoria-panell__incidencies,
  .sdp-gestoria-panell__excloses,
  .sdp-gestoria-panell__fitxers {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-2);
    margin: 0;
    padding: 0;
    list-style: none;
  }
  .sdp-gestoria-panell__tractor,
  .sdp-gestoria-panell__excloses > li {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--sdp-space-2) var(--sdp-space-3);
    margin: 0;
  }
  .sdp-gestoria-panell__tractor-nom {
    color: var(--sdp-text-titol);
    font-weight: 700;
  }
  .sdp-gestoria-panell__tractor code,
  .sdp-gestoria-panell__fitxer,
  .sdp-gestoria-panell__ruta code,
  .sdp-gestoria-panell__fitxer-generat > code {
    font-family: var(--sdp-font-mono);
    font-size: var(--sdp-text-small);
    overflow-wrap: anywhere;
  }
  .sdp-gestoria-panell__nota {
    margin: 0;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-small);
  }
  .sdp-gestoria-panell__accions,
  .sdp-gestoria-panell__accions-fila {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--sdp-space-3);
  }
  .sdp-gestoria-panell__accions-fila { gap: var(--sdp-space-2); }
  .sdp-gestoria-panell__progres { max-width: 40rem; }
  .sdp-gestoria-panell__avisos {
    margin: 0;
    padding-inline-start: var(--sdp-space-5);
    color: var(--sdp-text-cos);
    font-size: var(--sdp-text-small);
  }
  .sdp-gestoria-panell__dades {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
    gap: var(--sdp-space-3) var(--sdp-space-6);
    margin: 0;
  }
  .sdp-gestoria-panell__dades dt {
    color: var(--sdp-text-titol);
    font-weight: 700;
  }
  .sdp-gestoria-panell__dades dd {
    margin: 0;
    color: var(--sdp-text-cos);
  }
  /* Incidències: les que sempre decidix la persona (fora del trimestre,
     factures mensuals, correu i retencions) porten fons d'avís i negreta. */
  .sdp-gestoria-panell__grup {
    display: flex;
    flex-direction: column;
    gap: var(--sdp-space-2);
  }
  .sdp-gestoria-panell__incidencia {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: var(--sdp-space-2);
    margin: 0;
    padding: var(--sdp-space-2) var(--sdp-space-3);
    border-inline-start: 0.25rem solid var(--sdp-vora);
    color: var(--sdp-text-cos);
  }
  .sdp-gestoria-panell__incidencia[data-destacada="true"] {
    border-inline-start-color: var(--sdp-avis);
    background: var(--sdp-avis-fons);
    color: var(--sdp-text-titol);
    font-weight: 700;
  }
  /* Taules editables: una cel·la, un camp amb la seua etiqueta accessible. */
  .sdp-gestoria-panell__taula { background: var(--sdp-fons-targeta); }
  .sdp-gestoria-panell__taula tfoot td {
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-small);
  }
  .sdp-gestoria-panell__cel[data-tipus="import"] {
    text-align: end;
    white-space: nowrap;
  }
  .sdp-gestoria-panell__control {
    box-sizing: border-box;
    width: 100%;
    min-width: 8rem;
    min-height: var(--sdp-touch);
    padding: var(--sdp-space-1) var(--sdp-space-2);
    font-size: var(--sdp-text-small);
  }
  .sdp-gestoria-panell__control[data-mida="curta"] { min-width: 7rem; }
  .sdp-gestoria-panell__control[data-mida="ampla"] { min-width: 14rem; }
  .sdp-gestoria-panell__control[data-tipus="import"] { text-align: end; }
  .sdp-gestoria-panell__control[data-dubte="true"] {
    border-width: 2px;
    border-color: var(--sdp-avis);
  }
  .sdp-gestoria-panell__control[aria-invalid="true"] {
    border-width: 2px;
    border-color: var(--sdp-error);
  }
  .sdp-gestoria-panell__control:focus-visible {
    outline: 3px solid var(--sdp-focus);
    outline-offset: 2px;
  }
  .sdp-gestoria-panell__cel-error {
    display: block;
    margin-block-start: var(--sdp-space-1);
    color: var(--sdp-error-text);
    font-size: var(--sdp-text-small);
    white-space: normal;
  }
  .sdp-gestoria-panell__documents > summary {
    display: list-item;
    min-height: var(--sdp-touch);
    padding-block: var(--sdp-space-2);
    color: var(--sdp-text-titol);
    font-weight: 700;
    cursor: pointer;
  }
  .sdp-gestoria-panell__documents > summary:focus-visible {
    outline: 3px solid var(--sdp-focus);
    outline-offset: 2px;
  }
  .sdp-gestoria-panell__ruta { font-weight: 400; }
  .sdp-gestoria-panell__fitxer-generat {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--sdp-space-2);
    margin: 0;
    padding: var(--sdp-space-3);
    border: 1px solid var(--sdp-vora);
    border-radius: var(--sdp-radi-m);
  }

  /* VistaPreviaFull.jsx: el full com el veurà la gestoria. Barres fosques amb
     el text clar (la roca no canvia amb el tema), capçalera grisa i totals en
     negreta; cap ratllat alternat ni realç en passar-hi per damunt. */
  .sdp-gestoria-full table { border-collapse: collapse; }
  .sdp-gestoria-full tr { background: var(--sdp-fons-targeta); }
  .sdp-gestoria-full :where(th, td) {
    padding: var(--sdp-space-1) var(--sdp-space-2);
    border: 1px solid var(--sdp-vora);
    color: var(--sdp-text-cos);
    font-size: var(--sdp-text-small);
  }
  .sdp-gestoria-full__cel[data-tipus="import"] {
    text-align: end;
    white-space: nowrap;
  }
  .sdp-gestoria-full__cel[data-tipus="data"] { white-space: nowrap; }
  .sdp-gestoria-full__titol > td {
    color: var(--sdp-text-titol);
    font-weight: 700;
    text-align: center;
  }
  .sdp-gestoria-full__barra > th {
    background: var(--sdp-fons-roca);
    color: var(--sdp-sobre-roca);
    font-weight: 700;
    text-align: center;
  }
  .sdp-gestoria-full__capcalera > th {
    background: var(--sdp-fons-subtil);
    color: var(--sdp-text-titol);
    font-weight: 700;
    text-align: center;
  }
  .sdp-gestoria-full__dada > td { vertical-align: top; }
  .sdp-gestoria-full__totals > td {
    color: var(--sdp-text-titol);
    font-weight: 700;
  }
  .sdp-gestoria-full__buida > td {
    padding-block: var(--sdp-space-2);
    border-inline: 0;
  }
}

/* ── P7-A · PORTADA PLEGABLE DE LA PÀGINA UNIVERSAL (directriu 261003_2320,
   «Hero Image Toggle»; UniversalPage.jsx, prop portadaPlegable) ──
   El botó viu dins del marc de la portada (.hero-image, que ja és
   position: relative i context de nivell 0, layout.css), abans de la imatge.
   Amb la portada a la vista flota dalt a la dreta, damunt de la il·lustració,
   amb la pell de Boto secundari (fons de targeta i vora) i una ombra perquè
   es llija sobre qualsevol dibuix. Plegada, la franja ocupa el marc sencer
   amb el fons de l'app (tapa el taronja del marc) i el botó es queda al
   mateix lloc. Text a la mida base (gent gran); l'alçada mínima
   (--sdp-touch-min) i el focus visible són els de .sdp-boto. Cap transició:
   res que prefers-reduced-motion haja d'aturar. Sense la prop no hi ha cap
   d'estes classes al DOM. */
@layer components {
  .sdp-portada__barra {
    position: absolute;
    inset-block-start: var(--sdp-space-3);
    inset-inline-end: var(--sdp-space-3);
    z-index: 1;
    display: flex;
    justify-content: flex-end;
  }
  .sdp-portada__barra--plegada {
    position: static;
    padding: var(--sdp-space-2) var(--sdp-space-3);
    background: var(--sdp-fons-app);
  }
  .sdp-portada__boto {
    font-size: var(--sdp-text-base);
    box-shadow: var(--sdp-ombra-2);
  }
}

/* W4-08 (Onada 4, 261004) · Panell de Control · La secció «Maquinària i
   Sistema» s'aparta de les Utilitats amb el token d'espai de 48px (abans, un
   style en línia de 3rem: 48px amb l'arrel de 16px). En px de token, el
   marge no depén de la mida de lletra de l'arrel de l'amfitrió WordPress. */
@layer components {
  .sdp-control-maquinaria {
    margin-block-start: var(--sdp-space-12);
  }
}

/* Ordre del Mestre, 261004 (prompt 261004_0515) · Front «nucli».
     · .page-title-accio · l'acció principal d'una pàgina (PageFrame,
       `accioPrincipal`), dins del bloc del títol: 32px de token dalt i baix,
       el mateix aire que les etiquetes (.page-title-labels). Sense la prop no
       hi ha cap div al DOM.
     · .sdp-card-llista · GraellaTargetes en variant 'llista': les targetes
       planes (variant 'pla') una davall de l'altra, sense buit entre elles;
       la vora de baix ja la porta .sp-card--pla. La variant 'graella' és la
       .sdp-card-grid de sempre. */
@layer components {
  .page-title-accio {
    margin-block: var(--sdp-space-8);
  }
  .sdp-card-llista {
    display: flex;
    flex-direction: column;
    gap: 0;
  }
}

/* Ordre del Mestre, 261004 (prompt 261004_0515) · Front «autoria».
     · .sdp-card-llista > .sp-card · en la variant 'llista' de GraellaTargetes
       (la «Revista» del Lector), la targeta plana ocupa tota la columna, com
       la fila que substituïx (LlistaArticles, inline-size: 100%): sense el
       sostre de 500px de la targeta del Mur (components.css, .sp-card), que
       .sp-card--pla no anul·la.
     · .sp-card-link-overlay[aria-keyshortcuts] · el sobreposat d'una targeta
       amb acció secundària (onAccioSecundaria: només llavors porta l'atribut)
       no obri el menú ni la previsualització de l'enllaç de Safari d'iOS ni
       comença cap selecció en la pulsació llarga, com les rajoles i les files
       que reemplaça (catalegColleccio.css). Sense la prop, res no canvia. */
@layer components {
  .sdp-card-llista > .sp-card {
    max-width: none;
  }
  .sp-card-link-overlay[aria-keyshortcuts] {
    touch-action: manipulation;
    -webkit-user-select: none;
    user-select: none;
    -webkit-touch-callout: none;
  }
}

/* Ordre del Mestre, 261004 (integració final) · Front «lector-nevera».
     · .sdp-card-llista > .sp-card > .sp-card-media-container · en la variant
       'llista' de GraellaTargetes (la «Revista» del Lector) la targeta ocupa
       tota la columna i la imatge 1:1 s'hi estirava sencera. Sostre: l'amplària
       d'una targeta de la graella (--sdp-targeta-incrustada-ample, 360px, la
       columna de .sdp-card-grid), centrada. La peça és legítima; el defecte
       era només el sostre (Codex i l'orquestrador hi coincidixen).
     · [data-sdp-app="nevera"] .sdp-card-grid > .sp-card · a la Nevera, entre
       targeta i targeta hi havia 56px: el gap de la graella (24) més el marge
       de baix de la targeta del Mur (32, components.css). Un sol espaiat, el
       canònic de la graella: el marge de baix fora. Només la Nevera (l'ordre);
       el Lector, el Mercat i la Consola continuen com eren (Llei del Píxel).
     · [data-sdp-app="lector"] … [aria-current="true"] · arreglo 6 (arreglo del
       verificador): les columnes de navegació del Lector (carpetes i fonts) ja
       són UniversalCard, i la targeta oberta (aria-current a l'element
       principal) havia de continuar veient-se, com a TargetesColleccions: una
       vora interior del color d'acció, de 4px de token. Amb el focus de teclat
       mana l'anell de focus de sempre (components.css). */
@layer components {
  .sdp-card-llista > .sp-card > .sp-card-media-container {
    max-inline-size: var(--sdp-targeta-incrustada-ample);
    margin-inline: auto;
  }
  [data-sdp-app="nevera"] .sdp-card-grid > .sp-card {
    margin-block-end: 0;
  }
  [data-sdp-app="lector"] .sdp-card-llista > .sp-card > .sp-card-link-overlay[aria-current="true"]:not(:focus-visible) {
    box-shadow: 0 0 0 var(--sdp-space-1) var(--sdp-accio) inset;
  }
}

/* T7 · Ordre del Mestre, 261004 (prompt 261004_0515) · Front «editor».
   TARGETES INCRUSTADES al cos de l'UniversalEditor i de la lectura
   (components/universal/richText/extensions/targetes). Es tracten com una
   imatge: un bloc autònom dins del text. La forma la porta data-forma, que
   es deriva del nombre de targetes del grup (cap selector de pare ni cap
   consulta de contenidor: Baseline 2022).
     · 1 («sola»): flotant a l'esquerra o a la dreta, de 360px
       (--sdp-targeta-incrustada-ample). left i right: els valors lògics de
       la flotant arriben amb Chrome 118, fora de la Baseline 2022, i el
       marge és físic pel mateix motiu. En mòbil, min(100%, …) la fa
       d'amplària completa sense cap @media.
     · 2 («parella»): centrades, en una fila que es plega.
     · 3 o més («graella»): la mateixa fórmula de .sdp-card-grid.
   La targeta del Mur porta marge i un sostre de 500px: ací mana el grup. El
   cos que porta targetes (.sdp-amb-targetes: l'arrel de l'editor i l'article
   de lectura) conté la flotant, i els trossos de text de la lectura
   hidratada no pinten cap caixa (.sdp-cos-tros). A l'editor, la targeta
   triada porta l'anell de focus del sistema i les seues eines davall. */
@layer components {
  .sdp-targetes {
    margin-block: var(--sdp-space-6);
  }
  .sdp-targeta .sp-card {
    margin: 0;
    max-width: none;
  }
  .sdp-targetes[data-forma="sola"] > .sdp-targeta {
    inline-size: min(100%, var(--sdp-targeta-incrustada-ample));
    margin-block-end: var(--sdp-space-4);
  }
  .sdp-targetes[data-forma="sola"][data-alineacio="esquerra"] > .sdp-targeta {
    float: left;
    margin-right: var(--sdp-space-6);
  }
  .sdp-targetes[data-forma="sola"][data-alineacio="dreta"] > .sdp-targeta {
    float: right;
    margin-left: var(--sdp-space-6);
  }
  .sdp-targetes[data-forma="parella"] {
    clear: both;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--sdp-space-6);
  }
  .sdp-targetes[data-forma="parella"] > .sdp-targeta {
    flex: 0 1 var(--sdp-targeta-incrustada-ample);
    min-inline-size: 0;
  }
  .sdp-targetes[data-forma="graella"] {
    clear: both;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(100%, var(--sdp-targeta-incrustada-ample)), 1fr));
    gap: var(--sdp-space-6);
    align-items: start;
  }
  .sdp-amb-targetes::after {
    content: '';
    display: block;
    clear: both;
  }
  .sdp-cos-tros {
    display: contents;
  }
  .sdp-targeta.ProseMirror-selectednode {
    outline: var(--sdp-focus-gruix) solid var(--sdp-focus);
    outline-offset: var(--sdp-focus-separacio);
  }
  .sdp-targeta-incrustada__eines {
    display: flex;
    flex-wrap: wrap;
    gap: var(--sdp-space-2);
    margin-block-start: var(--sdp-space-2);
  }
  .sdp-tria-targeta {
    display: grid;
    gap: var(--sdp-space-4);
  }
  .sdp-tria-targeta__avis {
    margin: 0;
    color: var(--sdp-text-suau);
    font-size: var(--sdp-text-meta);
  }
}

/* ═══ BARRA TARONJA UNIVERSAL (ordre del Mestre, 261004) ════════════════
   Tota pàgina porta la barra taronja (PageFrame.jsx), també les que no
   porten barra blava (chrome 'page' i 'none': l'Admin, la pàgina 404). La
   taronja s'enganxa just davall de la blava (top: var(--sdp-alt-accio), a
   layout.css i a utilities.css): sense blava, eixe top deixaria un forat
   per on es veuria passar el contingut. El modificador, que PageFrame només
   posa quan no hi ha blava, la porta a dalt de tot. Especificitat (0,2,1):
   guanya a la del mode contingut (0,2,0) de utilities.css sense dependre de
   l'ordre. Amb la blava no canvia res (Llei del Píxel).
   D3 (261004) · Una graella de columnes (AppGridShell) dins d'una pàgina
   sense blava (l'Admin, chrome 'page') és absoluta (inset: 0,
   AppGridShell.css): començava a dalt de tot i la barra taronja, enganxada
   a top 0 i amb un z-index més alt, tapava les capçaleres de les tres
   columnes (58px). Ara la graella comença just davall de la taronja.
   AppGridShell.css no es toca: (0,3,0) guanya al seu inset (0,1,0) dins de
   la mateixa capa. Cap altra pàgina embolcalla una graella amb una Pàgina
   Universal, i amb la blava (sense el modificador) no canvia res. */
@layer components {
  .sdp-universal-page-container--sense-blava > section.bar-orange { top: 0; }
  .sdp-universal-page-container--sense-blava > .content-wrapper > .app-grid-page { top: var(--sdp-alt-accio); }
}

/* ═══ MODE BANCAL · SUPERFÍCIES DE MODULES.CSS (Q1, 261004) ══════════════
   L'interruptor data-contrast="bancal" va a :root fora de l'incrustat i a
   :host dins del shadow root, com data-theme. És el plus d'exterior: llegir
   a ple sol al bancal. Els colors (text suau, accent de text) els canvia
   tokens.css; ací només hi ha el que és propi d'este full, sense cap color.
     · Text opac: les accions de la bombolla del Xat es veuen sempre (no
       esperen el ratolí) i el mapa de fons de la conversa desapareix: el
       text queda sobre un fons pla.
     · Pes: la lletra menuda de la interfície densa (14 a 16px) passa a 600.
       El cos de lectura (18px) i els títols no canvien. La llista va dins de
       :where() perquè no pese més que una classe: les variants que ja eren
       negretes (700) ho continuen sent amb una regla pròpia, darrere.
     · Les ombres de sempre (Q6): cap vora substituta.
   Dins de @layer components: guanya a `legacy` per capa i a les regles de
   components per especificitat (l'atribut de :root o :host hi suma) o per
   ordre (este bloc va l'últim). */
@layer components {
  :root[data-contrast="bancal"] .sdp-xat-bombolla__accions,
  :host([data-contrast="bancal"]) .sdp-xat-bombolla__accions { opacity: 1; }

  :root[data-contrast="bancal"] .sdp-xat-conversa::before,
  :host([data-contrast="bancal"]) .sdp-xat-conversa::before { display: none; }

  :root[data-contrast="bancal"] :where(
    .sdp-gestor-fitxa__subtitol, .sdp-nota-fitxa__data,
    .sdp-xat-fila__hora, .sdp-xat-capcalera__sub, .sdp-xat-sistema__text,
    .sdp-xat-bombolla__meta, .sdp-xat-opcio__text, .sdp-xat-control__estat,
    .sdp-xat-resultats__avis, .sdp-xat-fitxa-comunitat__tipus, .sdp-xat-avis,
    .sdp-xat-vista__subtitol, .sdp-xat-ajustos__nota,
    .sdp-cal-agenda__cap, .sdp-cal-any__graella th, .sdp-cal-dia__nom,
    .sdp-calendari--gran .sdp-calendari__pindola,
    .sdp-connectar__autor, .sdp-connectar__identitat, .sdp-connectar__ajuda,
    .sdp-connectar__nota, .sdp-connexio-resum__detall, .sdp-calaix-identitats__rol,
    .sdp-targeta-opcio__ajuda, .sdp-realitat__connexio-text,
    .sdp-resultat-cerca__meta, .sdp-cerca__estat,
    .toc-level-4 button, .toc-level-6 button, .sdp-slash-menu__ajuda,
    .sdp-avisador-efimer, .sdp-chat-bubble-meta, .search-result-meta,
    .file-item-meta, .download-card-meta, .embed-caption, .upload-zone-sub,
    .stat-label, .divider-label, .pagination-label
  ),
  :host([data-contrast="bancal"]) :where(
    .sdp-gestor-fitxa__subtitol, .sdp-nota-fitxa__data,
    .sdp-xat-fila__hora, .sdp-xat-capcalera__sub, .sdp-xat-sistema__text,
    .sdp-xat-bombolla__meta, .sdp-xat-opcio__text, .sdp-xat-control__estat,
    .sdp-xat-resultats__avis, .sdp-xat-fitxa-comunitat__tipus, .sdp-xat-avis,
    .sdp-xat-vista__subtitol, .sdp-xat-ajustos__nota,
    .sdp-cal-agenda__cap, .sdp-cal-any__graella th, .sdp-cal-dia__nom,
    .sdp-calendari--gran .sdp-calendari__pindola,
    .sdp-connectar__autor, .sdp-connectar__identitat, .sdp-connectar__ajuda,
