#!/usr/bin/env node
/** Vocabulari tancat: tema canònic, endolls numèrics explícits i fonts de producció.
 * Les proves de contraexemples s'executen a la CI; els seus literals no són CSS de l'app.
 * T1 desconegut; T2 fallback de tema; T3 definició fora de font; T4 primitiu;
 * T5 capa0; T6 Tailwind; T7 endoll runtime sense propietari verificable. Cap baseline.
 */
import fs from 'node:fs';
import path from 'node:path';
import { parse } from '@babel/parser';
import postcss from 'postcss';
import { arrel, esMain } from '../lib/arrel.mjs';

const FONT_TOKENS = 'src/css/tokens.css';
const FONT_CANON = 'src/css/design-tokens.css';
const CONTRACTE = 'tooling/contracts/css-runtime-properties.json';
const EXT = /\.(css|[cm]?[jt]sx?)$/;
const PRIMITIVA = /^--sdp-(pedra|primary|secondary|error|avis|exit)-\d+$|^--sdp-(blanc|negre)(-pur)?$/;
const EXEMPTS_T4 = new Set([FONT_TOKENS, 'src/sections/disseny/DesignSection.jsx']);
const esProva = rel => /\.(?:test|spec)\.[cm]?[jt]sx?$/.test(rel) || /\/(?:__tests__|__fixtures__|__mocks__)\//.test(rel);
const linia = (s, i) => s.slice(0, i).split('\n').length;
const calleeName = n => n?.type === 'Identifier' ? n.name : null;
const keyName = n => n?.type === 'StringLiteral' ? n.value : n?.type === 'Identifier' ? n.name : null;

export function comprovaTokens(root = arrel(), { nomes = null } = {}) {
  if (nomes !== null && !/^T[1-7]$/.test(nomes)) throw new Error(`Regla desconeguda: ${nomes}`);
  const errors = [], ok = [], produccio = [], excloses = [];
  const actiu = rule => !nomes || rule === nomes;
  const falla = (llei, fitxer, fila, missatge) => { if (actiu(llei) || llei === 'T0') errors.push({llei,fitxer,linia:fila,missatge}); };
  const read = rel => fs.readFileSync(path.join(root,rel),'utf8');
  function walk(rel) {
    for (const entry of fs.readdirSync(path.join(root,rel),{withFileTypes:true})) {
      if (entry.name.startsWith('.') || ['node_modules','dist','build','coverage'].includes(entry.name)) continue;
      const file = `${rel}/${entry.name}`;
      if (fs.statSync(path.join(root,file)).isDirectory()) walk(file);
      else if (EXT.test(entry.name)) (esProva(file) ? excloses : produccio).push(file);
    }
  }
  walk('src');
  if (!produccio.length) throw new Error('Cap font de producció: una auditoria buida no pot donar verd.');
  const definitions = new Set();
  for (const file of [FONT_TOKENS,FONT_CANON]) {
    const css = postcss.parse(read(file),{from:file});
    css.walkDecls(d => { if (/^--(?:sdp|z)-[\w-]+$/.test(d.prop)) definitions.add(d.prop); });
  }
  const contract = JSON.parse(read(CONTRACTE));
  if (contract.schema !== 'sdp.css.runtime.v1' || contract.hook !== 'src/hooks/usePropietatsCss.js' || !Array.isArray(contract.parameters)) throw new Error('Contracte runtime invàlid.');
  const runtime = new Map(), seen = new Map();
  const hostExports=new Map(), exportsSeen=new Map();
  if (!Array.isArray(contract.hostExports??[])) throw new Error('Exportacions host invàlides.');
  for (const h of contract.hostExports??[]) {
    if (h.name!=='--sdp-bg'||h.writer!=='src/PedraSecaEmbed.jsx'||h.scope!=='amfitrio-opt-in'||h.sourceToken!=='--sdp-fons-app'||h.contract!=='_wiki_de_poble/02_saber/estandard_integracio_react.md'||!Array.isArray(h.methods)||h.methods.join(',')!=='_pintaAmfitrio,_despintaAmfitrio'||hostExports.has(h.name)||!produccio.includes(h.writer)||!definitions.has(h.sourceToken)) throw new Error('Contracte host desconegut o sense propietari.');
    hostExports.set(h.name,h);exportsSeen.set(h.name,new Set());
  }
  for (const p of contract.parameters) {
    if (!/^--sdp-cal-[\w-]+$/.test(p.name) || p.kind !== 'number' || runtime.has(p.name) || !Array.isArray(p.writers) || !p.writers.length || new Set(p.writers).size !== p.writers.length || p.writers.some(f => !produccio.includes(f)) || (p.fallback !== undefined && !Number.isFinite(p.fallback))) throw new Error(`Paràmetre runtime invàlid: ${p.name}`);
    runtime.set(p.name,p); seen.set(p.name,new Set());
  }
  function reads(value,file,fila) {
    for (const m of value.matchAll(/var\(\s*(--(?:sdp|z)-[\w-]+)\s*([,)])/g)) {
      const name = m[1];
      if (!definitions.has(name) && !runtime.has(name)) falla('T1',file,fila+linia(value,m.index)-1,`Token inexistent: ${name}`);
      if (m[2] === ',') {
        const fallback = value.slice(m.index+m[0].length).match(/^\s*([^)]*)\)/)?.[1]?.trim();
        const parameter = runtime.get(name);
        if (!parameter || parameter.fallback === undefined || fallback !== String(parameter.fallback)) falla('T2',file,fila+linia(value,m.index)-1,`Fallback prohibit: ${name}, ${fallback ?? '?'}`);
      }
      if (!EXEMPTS_T4.has(file) && PRIMITIVA.test(name)) falla('T4',file,fila,`Primitiva en component: ${name}`);
      if (file !== FONT_TOKENS && file !== FONT_CANON && name.startsWith('--sdp-canon-')) falla('T5',file,fila,`Capa 0 en component: ${name}`);
    }
    if (/(?:bg|text|border)-\[#[0-9a-fA-F]{3,6}\]/.test(value)) falla('T6',file,fila,'Color fix Tailwind.');
  }
  function cssInscrit(text,file,fila,obligatori=false) {
    // Els comentaris CSS no són declaracions. El text de <style>, en canvi,
    // és una font executable encara que Babel el represente com a JSXText.
    if (obligatori || (text.includes('{') && text.includes('}'))) {
      try {
        const css=postcss.parse(text,{from:file});
        css.walkDecls(d=>{
          const row=fila+d.source.start.line-1;
          if(d.prop.startsWith('--sdp-'))falla('T3',file,row,`Definició CSS fora de la font: ${d.prop}`);
