          const name=node.arguments[0]?.type==='StringLiteral'?node.arguments[0].value:null;
          const host=hostExports.get(name);
          const owner=[...parents].reverse().find(n=>n.type==='ClassMethod');
          const ownerName=keyName(owner?.key);
          const start=owner?.body?.body?.[0];
          const documentGuard=start?.type==='IfStatement'&&start.test?.type==='BinaryExpression'&&start.test.operator==='==='&&start.test.left?.type==='UnaryExpression'&&start.test.left.operator==='typeof'&&start.test.left.argument?.name==='document'&&start.test.right?.value==='undefined'&&start.consequent?.type==='ReturnStatement';
          const first=documentGuard?owner?.body?.body?.[1]:start;
          const guard=first?.type==='IfStatement'&&first.test?.type==='UnaryExpression'&&first.test.operator==='!'&&first.test.argument?.type==='CallExpression'&&first.test.argument.callee?.object?.type==='ThisExpression'&&first.test.argument.callee?.property?.name==='hasAttribute'&&first.test.argument.arguments?.[0]?.value==='pinta-amfitrio'&&first.consequent?.type==='ReturnStatement';
