    console.log(`ℹ️ ${r.excloses.length} fonts de proves/fixtures excloses del CSS productiu; les regressions s'executen a test:ci.`);
    for(const rule of r.ok)console.log(`✅ ${rule}`);
    for(const error of r.errors)console.error(`${error.fitxer}:${error.linia} [${error.llei}] ${error.missatge}`);
