  --sdp-text-cos:    var(--sdp-pedra-700);   /* 11,20:1 */
  --sdp-text-suau:   var(--sdp-pedra-650);   /*  9,09:1 · AAA · 8,00 sobre l'app, 7,71 sobre el fons subtil */
