     o més (components.css): a l'editor li queden 36rem. */
  --sdp-targeta-viva-ample: 24rem;
  --sdp-targeta-incrustada-ample: 22.5rem; /* T7 (261004) · la targeta incrustada al cos: 360px, com .sdp-card-grid */
  /* Norma del Mestre, 261004 (prompt 261004_1108, T2) · L'avatar redó de qui
     signa (una persona o la IA) davant de l'H1: 300px, més menut que el
     logotip d'una entitat (fins a 600px). PageFrame, .page-title-avatar. */
  --sdp-avatar-capcalera: 18.75rem;

  /* LLEI DE VIDA · objectiu tàctil mínim. Cap control per davall.
     Mestre 261004 (Q2): 48px sempre, a tot arreu; el mateix valor que
     --sdp-touch-min (capa 0, design-tokens.json). Si un control no hi cap,
     s'ajusta l'espai de dins, mai el sòl. */
  --sdp-touch: 48px;

  --sdp-touch-comode: 48px;

  /* Mida de GLIF: el dibuix de la icona dins d'un control, no la seua zona
     tàctil. La zona tàctil la posa el control que el conté. */
  --sdp-icona-xs: 14px;

  /* Escala z-index · única font de veritat */
  --z-eines-editor: 99070;   /* per davall de la taronja: el desplegable d'estat hi passa per damunt */
  --z-barra-taronja: 99080;
  --z-barra-blava: 99090;
  --z-barra-negra: 99100;
  --z-sidebar: 99200;
  --z-fab: 99500;
  --z-nav-mobil: 99950;
  --z-vel: 99960;
  --z-calaix: 99990;

  /* Tipografia */
  --sdp-font: 'Noto Sans', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --sdp-font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;

  /* P6 (directriu 261003_2325, confirmació 3 del Mestre) · Escala dels
     encapçalaments un esglaó amunt per a llegir sense zoom (veïnat major):
     cada nivell pren la mida del de damunt i l'h1 puja mig rem, com de l'h2
     a l'h1. Abans: 2.5 · 2 · 1.75 · 1.5 · 1.25 · 1.125rem. El títol de les
     targetes en penja (components.css, .sp-card-title: un --sdp-text-hN). */
  --sdp-text-h1: 3rem;
  --sdp-text-h2: 2.5rem;
  --sdp-text-h3: 2rem;
  --sdp-text-h4: 1.75rem;
  --sdp-text-h5: 1.5rem;
  --sdp-text-h6: 1.25rem;
  --sdp-text-lead: 1.25rem;
  --sdp-text-base: 1.125rem;
  --sdp-text-small: 1rem;
  --sdp-text-meta: 0.875rem;   /* 14px · sòl absolut de mida de lletra */

  /* Fase D (Q5 del Mestre, 261004) · Tipografia fluida de la PROSA (base.css:
     h1-h6, p, llistes i .lead). Rang real de cada nivell al comentari de la
     línia: el mínim (a 320px) queda per davall de l'escala P6 fixa de dalt
     perquè el títol càpia sencer en un mòbil estret (acta 261004_1027, ràtio
     màxim 1.8); el màxim (a 1024px) és moderat. Interpolació lineal entre
     320 i 1024px (20 i 64rem): constants precalculades, perquè la Baseline
     2022 no dividix longituds dins de calc(). Terme en rem + terme d'amplada:
     creix amb el zoom i amb la lletra triada (WCAG 1.4.4). Els components
     conserven els --sdp-text-* fixos.
     Valor de BASE en vw (Baseline 2022: Chrome 100 i Firefox 100 no tenen cqi).
     El terme en cqi (relatiu al contenidor, decisió de MarIA 261004) el posa
     el bloc @supports (width: 1cqi) de davall d'este. No es pot declarar com
     una segona línia ací: una custom property no es valida en llegir-la, la
     segona declaració guanya sempre i, en un navegador sense cqi, var() dona
     un valor invàlid i el títol hereta la mida del pare.
     Tota la tipografia passa per custom properties: el futur tauler
     d'administració les podrà reescriure en calent. */
  --sdp-fluid-h1:   clamp(2rem, 1.3182rem + 3.4091vw, 3.5rem);        /* 32 a 56px */
  --sdp-fluid-h2:   clamp(1.75rem, 1.2386rem + 2.5568vw, 2.875rem);   /* 28 a 46px */
  --sdp-fluid-h3:   clamp(1.5rem, 1.1591rem + 1.7045vw, 2.25rem);     /* 24 a 36px */
  --sdp-fluid-h4:   clamp(1.25rem, 0.9659rem + 1.4205vw, 1.875rem);   /* 20 a 30px */
  --sdp-fluid-h5:   clamp(1.125rem, 0.8977rem + 1.1364vw, 1.625rem);  /* 18 a 26px */
  --sdp-fluid-h6:   clamp(1rem, 0.8295rem + 0.8523vw, 1.375rem);      /* 16 a 22px */
  --sdp-fluid-lead: clamp(1.125rem, 1.0114rem + 0.5682vw, 1.375rem);  /* 18 a 22px */
  --sdp-fluid-cos:  clamp(1rem, 0.8864rem + 0.5682vw, 1.25rem);       /* 16 a 20px */

  /* Interlineat (Impeccable): 1.2 als títols i 1.6 al cos. */
  --sdp-leading-titol: 1.2;
  --sdp-leading-cos:   1.6;

  /* Pesos i espaiat de la prosa: abans eren literals de base.css. */
  --sdp-pes-semi:    600;
  --sdp-pes-negreta: 700;
  --sdp-pes-extra:   800;
  --sdp-tracking-h1: -0.01em;
  --sdp-tracking-h2: -0.005em;
  --sdp-tracking-versaletes: 0.08em;

  /* Amplades de Noto Sans (font-stretch), servides pel paquet local
     (public/fonts/noto-sans.css). Sense la cara estreta, el navegador pinta
     l'amplada normal: no la sintetitza. */
  --sdp-font-amplada-semi:    87.5%;
  --sdp-font-amplada-estreta: 75%;

  /* Q8 (ajornat, 261004) · rem dins de WordPress: rem es resol contra
     l'element arrel del document AMFITRIÓ, no contra :host. Un tema que
     pose la lletra de l'arrel al 62,5 % encongiria tota la tipografia un
     37,5 %. Cap guarda encara: s'estudia a l'onada de l'arquitectura de
     plugins (directriu 261003_2320). */

  /* Una mateixa plantilla tipogràfica per al menú, les categories i les
     capçaleres de columna, també quan es mostren com a pestanyes. */
  --sdp-font-barra: 600 var(--sdp-text-small)/1.5 var(--sdp-font);

  /* Tipografia d'Interfície (Compacta). Cap per davall del sòl de 14px. */
  --sdp-ui-base: 0.9375rem;    /* 15px */
  --sdp-ui-sm: 0.875rem;       /* 14px · el sòl (abans 13px) */

  /* Interlineats de component: mètriques de peces (targetes, calendari,
     consola), no de prosa. Es conserven: el calendari calcula quantes línies
     caben en un bloc amb --sdp-leading-tight. */
  --sdp-leading-tight: 1.15;
  --sdp-leading-snug: 1.21;
  --sdp-leading-body: 1.65;

  /* Escala d'espaiat modular · base 4/8 */
  --sdp-space-0: 0px;   --sdp-space-1: 4px;   --sdp-space-2: 8px;
  --sdp-space-3: 12px;  --sdp-space-4: 16px;  --sdp-space-5: 20px;
  --sdp-space-6: 24px;  --sdp-space-8: 32px;  --sdp-space-10: 40px;
  --sdp-space-12: 48px; --sdp-space-16: 64px; --sdp-space-20: 80px;

  /* ── RITME VERTICAL EDITORIAL ── */
  --sdp-measure: 68ch;                 /* mesura de columna · APLICADA */
  /* Noms antics de la prosa, ara àlies dels interlineats Impeccable. */
  --sdp-leading-editorial: var(--sdp-leading-cos);
  --sdp-leading-display: var(--sdp-leading-titol);
  --sdp-mt-h1: 0;    --sdp-mb-h1: 16px;
  --sdp-mt-h2: 48px; --sdp-mb-h2: 12px;   /* corregit: h2 domina h3 */
  --sdp-mt-h3: 40px; --sdp-mb-h3: 12px;
  --sdp-mt-h4: 32px; --sdp-mb-h4: 8px;
  /* D-C (ordre del Mestre, 261004) · a la reixeta de 4px: l'h5 i l'h6, de 6 a 8px. */
  --sdp-mt-h5: 24px; --sdp-mb-h5: 8px;
  --sdp-mt-h6: 20px; --sdp-mb-h6: 8px;
  --sdp-mb-lead: 24px;
  --sdp-mb-p: 20px;
  --sdp-mb-ul: 20px;
  --sdp-li-gap: 8px;
  --sdp-bq-indent: 24px;

  /* ═══ CAPA 2b · CROM · LA CLOSCA IMMUTABLE (260911) ═══════════════
     TopBar (header.bar-black) i SideBar (nav.app-sidebar) no canvien
     MAI entre clar i fosc. Llei:
       · Els --sdp-crom-* es declaren NOMÉS ací. Prohibit redefinir-los
         al bloc fosc (ho vigila tooling/gates/tractor-crom.mjs).
       · Les regles de la closca només pinten amb --sdp-crom-* o literals.
       · Són l'única porta legítima a les rampes des de la closca: així
         ni els components toquen primitius ni la closca toca semàntics
         que s'inverteixen. Resol la contradicció de pedra-seca/SKILL.md.
     Tots els parells text/fons són AAA (mesurats al dictamen 260911). */
  --sdp-crom-fons:              var(--sdp-pedra-900);
  --sdp-crom-capcalera-clara:   var(--sdp-pedra-600);
  --sdp-crom-capcalera:         var(--sdp-pedra-700);
  --sdp-crom-subcapcalera:      var(--sdp-pedra-750);
  --sdp-crom-subcapcalera-fosca: var(--sdp-pedra-800);
  --sdp-crom-text:              var(--sdp-pedra-50);
  --sdp-crom-text-suau:         rgba(255, 255, 255, 0.78);
  --sdp-crom-vora:              rgba(255, 255, 255, 0.06);
  --sdp-crom-hover:             rgba(255, 255, 255, 0.09);
  --sdp-crom-actiu-fons:        var(--sdp-primary-500);
  --sdp-crom-actiu-fons-hover:  var(--sdp-primary-400);
  --sdp-crom-actiu-text:        var(--sdp-pedra-900);
  /* T62 · Selecció de la navegació secundària sobre crom: la 1a columna
     (arbre de carpetes, famílies i categories, rail del Xat) i els rails
     plegats. Els actius van en blau (Pedra Seca §2); la barra principal,
     CONTROL i les capçaleres continuen amb --sdp-crom-actiu-*.
     T62b (ordre del Mestre, 260928): «quan el fons d'un element actiu
     canvie a blau, el text i la icona han de ser obligatòriament blancs».
     Fons Blau 600, el fort (#00599d), i text i icona Blanc pur (#ffffff).
     Contrastos WCAG sobre els hex reals:
       · text i icona blancs sobre la cel·la: 7,20:1 · AAA;
       · cel·la contra la columna Grafit 700 (#3d3b35): 1,55:1, i contra
         el rail plegat del Workspace, Carbó 800 (#22211e): 2,24:1. Queda
         per davall del 3:1 de 1.4.11 (a validar pel Mestre): l'estat el
         porten el to (gris → blau) i aria-current, no la lluminositat;
       · anell de focus del crom, Taronja 400 (#ff955b), dins de la
         cel·la activa: 3,33:1; fora, sobre la columna: 5,17:1, i sobre
         el rail plegat: 7,44:1;
       · vora de l'arrel que conté la selecció al rail plegat: continua
         en Blau 400 (#49a3fa), 6,06:1 contra el Carbó 800. En Blau 600
         faria 2,24:1 i deixaria de veure's;
       · marcador blanc de 3px a l'inici de línia de la cel·la activa
         (decisió del Mestre, 260928: «Marcador blanc 3px»), amb el
         mateix --sdp-crom-seleccio-text: sobre la cel·la (#00599d),
         7,20:1; contra la columna Grafit 700 (#3d3b35), 11,20:1, i contra
         el rail plegat Carbó 800 (#22211e), 16,10:1. Com que la cel·la
         només fa 1,55:1 i 2,24:1 contra el seu fons, és el marcador el que
         fa que l'estat no depenga només del color (WCAG 1.4.1).
     Van en línia pròpia: C2 (tractor-cromatic) mesura contra la targeta
     blanca, i estos parells viuen sobre el crom. */
  --sdp-crom-seleccio-fons:     var(--sdp-secondary-600);
  --sdp-crom-seleccio-text:     var(--sdp-blanc-pur);
  --sdp-crom-seleccio-vora:     var(--sdp-secondary-400);
  --sdp-crom-control-fons:      var(--sdp-secondary-700);
  --sdp-crom-control-hover:     var(--sdp-secondary-600);
  --sdp-crom-control-text:      var(--sdp-pedra-50);
  --sdp-crom-sistema:           rgba(255, 230, 100, 0.9);
  --sdp-crom-sistema-viu:       rgba(255, 230, 100, 1);
  --sdp-crom-sistema-actiu:     rgba(255, 230, 100, 0.1);
  /* T7 (261001) · El pilot de connexió de la franja de l'amfitrió, sobre el
     crom (--sdp-crom-fons, #0e0d0c). WCAG 2.x, 1.4.11 (objectes no textuals,
     mínim 3:1): verd ple #027e38, 3,74:1; groc en anell #ffe664, 15,5:1. La
     forma (ple o anell) i el text de la franja també diuen l'estat (1.4.1). */
  --sdp-crom-pilot-verd:        var(--sdp-exit-500);
  --sdp-crom-pilot-groc:        var(--sdp-crom-sistema-viu);
  --sdp-crom-focus:             var(--sdp-primary-400);
  --sdp-crom-scroll:            var(--sdp-pedra-600);
  --sdp-crom-vora-forta:        rgba(255, 255, 255, 0.15);
  --sdp-crom-realc:             rgba(255, 255, 255, 0.07);
  --sdp-crom-scroll-pista:      rgba(0, 0, 0, 0.15);
  --sdp-crom-scroll-puny:       rgba(0, 0, 0, 0.21);
  --sdp-crom-scroll-puny-viu:   rgba(0, 0, 0, 0.35);
  --sdp-crom-ombra:             0 18px 44px rgba(14, 13, 12, 0.16);


  /* === ANELLS DE FOCUS I VALIDACIO ==============================
     Abans eren rgba() literals repartits pel monolit: el canon blau
     escrit a ma (1,110,191), el roig d'error (194,20,25) i el taronja
     (254,116,6). Ara la tinta viu aci i prou. */
  --sdp-anell-accio:  rgba(1, 110, 191, 0.16);
  --sdp-anell-error:  rgba(194, 20, 25, 0.16);
  --sdp-anell-accent: rgba(254, 116, 6, 0.15);
  --sdp-accent-vel:   rgba(254, 116, 6, 0.18);
  --sdp-ombra-accio:  0 8px 20px rgba(0, 73, 131, 0.45);

  /* Tinta de les ombres pedra: els box-shadow ad hoc del legat. */
  --sdp-ombra-hover:   0 6px 16px rgba(14, 13, 12, 0.16);
  --sdp-ombra-premut:  0 2px 6px rgba(14, 13, 12, 0.14);
  --sdp-ombra-flotant: 0 12px 32px rgba(14, 13, 12, 0.28);
  --sdp-fons-hover-subtil: rgba(14, 13, 12, 0.06);

  /* Blanc que NO s'inverteix. --sdp-text-invers SI que s'inverteix
     (pedra-50 en clar, pedra-900 en fosc): posar-lo damunt d'un fons
     saturat com --sdp-error deixaria text negre sobre roig en fosc.
     Per a text damunt de color massis, este es el token. */
  --sdp-sobre-color: #ffffff;

  accent-color: var(--sdp-accio);
  color-scheme: light;
}

/* Tipografia fluida relativa al contenidor (decisió de MarIA, 261004): només
   on el navegador entén cqi (Safari 16, Chrome 105, Firefox 110). Mateixos
   mínims, màxims i coeficients que el valor de base en vw del bloc de dalt;
   ací només canvia la unitat del terme d'amplada. Fora d'este @supports, el
   vw de dalt continua manant (Baseline 2022). */
@supports (width: 1cqi) {
  :root, :host, .sdp-root {
    --sdp-fluid-h1:   clamp(2rem, 1.3182rem + 3.4091cqi, 3.5rem);
    --sdp-fluid-h2:   clamp(1.75rem, 1.2386rem + 2.5568cqi, 2.875rem);
    --sdp-fluid-h3:   clamp(1.5rem, 1.1591rem + 1.7045cqi, 2.25rem);
    --sdp-fluid-h4:   clamp(1.25rem, 0.9659rem + 1.4205cqi, 1.875rem);
    --sdp-fluid-h5:   clamp(1.125rem, 0.8977rem + 1.1364cqi, 1.625rem);
    --sdp-fluid-h6:   clamp(1rem, 0.8295rem + 0.8523cqi, 1.375rem);
    --sdp-fluid-lead: clamp(1.125rem, 1.0114rem + 0.5682cqi, 1.375rem);
    --sdp-fluid-cos:  clamp(1rem, 0.8864rem + 0.5682cqi, 1.25rem);
  }
}

/* Fons de mapa de la conversa del Xat. Viu a :root i :host, i NO a .sdp-root:
   incrustada, l'app penja d'un .sdp-root dins del shadow root, i si el token
   s'hi tornara a declarar tallaria l'herència del valor que l'element
   <soc-de-poble> fixa al seu estil amb la base de recursos de l'amfitrió. */
:root, :host {
  --sdp-xat-fons-imatge: url('/assets/system/ui/xat-bg-map-v2.jpg');
}

/* ═══ CAPA 2 · SEMÀNTICS · TEMA FOSC ═══════════════════════════════
   Un sol bloc. Redefinix NOMÉS semàntics: els primitius no es toquen
   mai, per això l'escala pedra continua sent monòtona i res no es
   torna invisible.

   La resolució de la preferència del sistema la fa el script mínim
   del <head>, que escriu data-theme a l'<html> abans del primer
   pintat. Per això ACÍ NO hi ha cap @media (prefers-color-scheme):
   duplicar-lo seria dos fonts de veritat per al mateix fet.

   IDENTITAT ESTABLE: el taronja continua sent el taronja i el blau
   continua sent el blau. Vegeu la nota D-4 de l'informe.
   ───────────────────────────────────────────────────────────────── */

:root[data-theme="dark"], :host([data-theme="dark"]),
:root[data-theme="dark"] .sdp-root, :host([data-theme="dark"]) .sdp-root {
  color-scheme: dark;

  --sdp-fons-app:        var(--sdp-pedra-900);
  --sdp-fons-targeta:    var(--sdp-pedra-850);
  --sdp-fons-elevat:     var(--sdp-pedra-800);
  --sdp-fons-superficie: var(--sdp-pedra-850);
  --sdp-fons-subtil:     var(--sdp-pedra-750);
  --sdp-fons-invers:     var(--sdp-pedra-100);
  --sdp-fons-vel:        rgba(14, 13, 12, 0.72);

  /* Ràtios sobre la targeta fosca (--sdp-pedra-850), recalculades 261004. */
  --sdp-text-titol:  var(--sdp-pedra-50);    /* 17,91:1 */
  --sdp-text-cos:    var(--sdp-pedra-200);   /* 15,20:1 */
  --sdp-text-suau:   var(--sdp-pedra-300);   /* 12,49:1 */
  --sdp-text-invers: var(--sdp-pedra-900);
  --sdp-text-desactivat: var(--sdp-pedra-500);

  --sdp-vora:         var(--sdp-pedra-750);
  --sdp-vora-control: var(--sdp-pedra-500);  /*  4,90:1 */
  --sdp-vora-forta:   var(--sdp-pedra-400);

  --sdp-accent:            var(--sdp-primary-500);
  --sdp-accent-hover:      var(--sdp-primary-400);
  --sdp-accent-subtil:     var(--sdp-primary-900);
  --sdp-sobre-accent:      var(--sdp-pedra-900);   /*  7,12:1 sobre --sdp-accent */
  --sdp-accent-text:       var(--sdp-primary-400); /*  8,28:1 */
  --sdp-accent-text-hover: var(--sdp-primary-300); /* 10,30:1 */
  --sdp-accent-titol:      var(--sdp-primary-300); /* 10,30:1 */

  --sdp-accio:         var(--sdp-secondary-500);
  --sdp-accio-hover:   var(--sdp-secondary-400);
  --sdp-accio-forta:   var(--sdp-accio-text);
  --sdp-accio-subtil:  var(--sdp-secondary-900);
  --sdp-sobre-accio:   #ffffff;
  --sdp-accio-text:    var(--sdp-secondary-300);   /* 10,32:1 */
  --sdp-focus:         var(--sdp-focus-invers);
  --sdp-focus-invers:  var(--sdp-primary-400);

  --sdp-error-fons: #2a0f11; --sdp-error-text: #ffb3b0;
  --sdp-avis-fons:  #2a1e05; --sdp-avis-text:  #f5c96b;
  --sdp-exit-fons:  #052213; --sdp-exit-text:  #86dfa4;
  --sdp-info-fons:  #041f33; --sdp-info-text:  var(--sdp-secondary-300);

  --sdp-ombra-1: 0 1px 3px rgba(0, 0, 0, 0.45);
  --sdp-ombra-2: 0 3px 10px rgba(0, 0, 0, 0.55);
  --sdp-ombra-3: 0 10px 28px rgba(0, 0, 0, 0.62);
}

/* ═══ MODE BANCAL · CONTRAST EXTREM PER A L'HORT A PLE SOL ════════════
   Q1 del Mestre (261004): les correccions AAA van sempre, en tots els
   modes; el Bancal és l'interruptor de més. data-contrast="bancal" el posa
   config/theme.js (arrelDePresentacio, W4-12) a l'<html> quan l'app és ama
   del document, a l'amfitrió <soc-de-poble> i, en un document alié sense
   Shadow DOM, a l'arrel del mòdul: el primer selector de cada bloc,
   .sdp-root[data-contrast="bancal"], mai l'<html> d'un altre. Allà el tema
   continua a l'<html>, i el niat fosc el troba amb :root[data-theme="dark"].
   La tria «sistema» resol prefers-contrast: ací tampoc hi ha cap consulta de
   mitjà.
   · Text: tres graons foscos; el pitjor cas, el suau sobre el fons subtil,
     passa de 9:1.
   · Enllaços, h2, h4 i accent de text: 7:1 o més sobre la targeta i l'app.
   · Premut sense escala: el retorn és de color.
   · Les ombres de les targetes es queden (Q6): cap vora sòlida nova.
   · Cap token de text translúcid. Els --sdp-crom-* no es redefinixen: la
     closca és immutable (tractor-crom, K1).
   El bloc fosc niat és obligatori: el Bancal clar empata amb el tema fosc
   (mateixa especificitat) i va darrere, així que sense el niat pintaria
   text fosc del tema clar sobre els fons foscos. El niat té un atribut més
   i guanya els dos.
   ───────────────────────────────────────────────────────────────── */
.sdp-root[data-contrast="bancal"],
